/* 111 שאלות המאגר הפתוחות — חולצו אוטומטית מעמוד מאגר התרגול */
window.BANK_OPEN_QUESTIONS = [{"id":"BK-1.1","cat":"סיבוכיות","difficulty":3,"skills":["סיבוכיות"],"origin":"bank","kind":"open","sourceLabel":"🤖 קלוד · 1.1","prompt":"מהי סיבוכיות זמן הריצה של קטע הקוד הבא כפונקציה של <span dir=\"ltr\">n</span>? נמק את החישוב במפורש (הצג את הסכום שאתה מחשב).","qtype":"analysis","hint":"כשגבול הלולאה הפנימית תלוי במשתנה החיצוני — סוכמים את מספר הצעדים על פני i, לא כופלים.","rule":"לולאה פנימית תלויה בחיצונית","html":"<div class=\"qh\"><b>1.1</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🤖 קלוד</span><span class=\"src\">לולאה פנימית תלויה בחיצונית</span></div>\n<pre class=\"c\">for (i = 1; i &lt;= n; i++)\n    for (j = 1; j &lt;= i * i; j++)\n        cnt++;</pre>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<p><b>O(n³).</b> הלולאה הפנימית רצה i² פעמים, ולכן הסכום הוא\n1² + 2² + … + n² = n(n+1)(2n+1)/6 ≈ n³/3.</p>\n<div class=\"tip\" style=\"margin-bottom:0\">כשהפנימית תלויה בחיצונית — <b>סוכמים</b>,\nלא כופלים. הכפל (n · n²) נותן כאן במקרה את אותה תשובה, אבל בסכומים כמו\n1+2+…+i הוא כבר יטעה אותך.</div>\n</div></details>"},{"id":"BK-1.2","cat":"סיבוכיות","difficulty":2,"skills":["סיבוכיות"],"origin":"bank","kind":"open","sourceLabel":"🤖 קלוד · 1.2","prompt":"מהי סיבוכיות זמן הריצה של קטע הקוד הבא כפונקציה של <span dir=\"ltr\">n</span>? נמק כמה פעמים רצה כל אחת משתי הלולאות.","qtype":"analysis","hint":"בדוק אם מספר הצעדים של הלולאה הפנימית תלוי ב-<span dir=\"ltr\">i</span> — אם לא, זו מכפלה פשוטה.","rule":"חלוקה בחוץ, ליניארי בפנים","html":"<div class=\"qh\"><b>1.2</b><span class=\"diff diff-e\">קל</span><span class=\"diff srcb\">🤖 קלוד</span><span class=\"src\">חלוקה בחוץ, ליניארי בפנים</span></div>\n<pre class=\"c\">for (i = n; i &gt; 1; i /= 2)\n    for (j = 0; j &lt; n; j++)\n        cnt++;</pre>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<p><b>O(n·log n).</b> החיצונית רצה log n פעמים (n → n/2 → … → 1),\nוהפנימית — n פעמים <b>קבועות</b>, בלי תלות ב-i. לכן מכפלה: n·log n.</p>\n</div></details>"},{"id":"BK-1.3","cat":"סיבוכיות","difficulty":3,"skills":["סיבוכיות"],"origin":"bank","kind":"open","sourceLabel":"🤖 קלוד · 1.3","prompt":"נתונה הפונקציה הרקורסיבית הבאה. רשום את נוסחת הנסיגה <span dir=\"ltr\">T(n)</span> שלה, ופתור אותה בעזרת נוסחת האב (משפט המאסטר). מהי הסיבוכיות הסופית?","qtype":"analysis","hint":"ספור כמה קריאות רקורסיביות יש ועל איזה גודל קלט, וכמה עולה העבודה מחוץ לרקורסיה.","rule":"רקורסיה + נוסחת האב","html":"<div class=\"qh\"><b>1.3</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🤖 קלוד</span><span class=\"src\">רקורסיה + נוסחת האב</span></div>\n<pre class=\"c\">int f(int n)\n{\n    if (n &lt;= 1) return 1;\n    for (int i = 0; i &lt; n; i++)\n        cnt++;\n    return f(n/2) + f(n/2) + f(n/2) + f(n/2);\n}</pre>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<p>הנסיגה: <code>T(n) = 4T(n/2) + O(n)</code> → a=4, b=2, k=1.</p>\n<p><code>b^k = 2 &lt; 4 = a</code> → המקרה של \"הרקורסיה מנצחת\":\n<b>O(n^log₂4) = O(n²)</b>.</p>\n</div></details>"},{"id":"BK-1.4","cat":"סיבוכיות","difficulty":3,"skills":["סיבוכיות"],"origin":"bank","kind":"open","sourceLabel":"🤖 קלוד · 1.4","prompt":"מהי סיבוכיות זמן הריצה של קטע הקוד הבא? שים לב שיש בו <b>שני</b> משתני קלט — התשובה חייבת להיות כפונקציה של <span dir=\"ltr\">n</span> ושל <span dir=\"ltr\">m</span> גם יחד.","qtype":"analysis","hint":"כל לולאה נשלטת על ידי משתנה אחר; אל תניח ש-<span dir=\"ltr\">m</span> ו-<span dir=\"ltr\">n</span> מאותו סדר גודל.","rule":"שני משתנים — n ו-m","html":"<div class=\"qh\"><b>1.4</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🤖 קלוד</span><span class=\"src\">שני משתנים — n ו-m</span></div>\n<pre class=\"c\">for (i = 0; i &lt; n; i++)\n    for (j = 1; j &lt; m; j *= 2)\n        cnt++;</pre>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<p><b>O(n·log m).</b> את התשובה חייבים לתת כפונקציה של <b>שני</b> המשתנים —\nלכתוב O(n·log n) זו טעות שעולה נקודות (זה בדיוק הדפוס של 2025 ש'1ב).</p>\n</div></details>"},{"id":"BK-1.5","cat":"סיבוכיות","difficulty":3,"skills":["סיבוכיות"],"origin":"bank","kind":"open","sourceLabel":"🤖 קלוד · 1.5","prompt":"מהי סיבוכיות זמן הריצה של הלולאה הבאה כפונקציה של <span dir=\"ltr\">n</span>? נמק — רשום את ערכי <span dir=\"ltr\">i</span> בכל איטרציה והסבר מתי הלולאה נעצרת.","qtype":"analysis","hint":"בכל צעד <span dir=\"ltr\">i</span> מתרבע — כתוב את <span dir=\"ltr\">i</span> אחרי k צעדים כחזקה של חזקה.","rule":"הטריק הנדיר — חזרה על 2021","html":"<div class=\"qh\"><b>1.5</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🤖 קלוד</span><span class=\"src\">הטריק הנדיר — חזרה על 2021</span></div>\n<pre class=\"c\">for (i = 2; i &lt; n; i = i * i)\n    cnt++;</pre>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<p><b>O(log log n).</b> i מרבע את עצמו: 2 → 4 → 16 → 256 → … כלומר\n2^(2^k) אחרי k צעדים. מגיעים ל-n כש-2^k ≈ log n, כלומר k ≈ log log n.</p>\n</div></details>"},{"id":"BK-1.6","cat":"סיבוכיות","difficulty":4,"skills":["סיבוכיות"],"origin":"bank","kind":"open","sourceLabel":"🤖 קלוד · 1.6","prompt":"מהי סיבוכיות זמן הריצה של קטע הקוד הבא כפונקציה של <span dir=\"ltr\">n</span>? היזהר — התשובה האינטואיטיבית כאן שגויה. נמק על ידי חישוב סכום מספר הפעולות בכל סיבוב של הלולאה החיצונית.","qtype":"analysis","hint":"הלולאה הפנימית מצטמקת יחד עם <span dir=\"ltr\">n</span> — מה ערכו של הסכום <span dir=\"ltr\">n + n/2 + n/4 + …</span>?","rule":"מלכודת הסכום ההנדסי","html":"<div class=\"qh\"><b>1.6</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🤖 קלוד</span><span class=\"src\">מלכודת הסכום ההנדסי</span></div>\n<pre class=\"c\">while (n &gt; 0)\n{\n    for (j = 0; j &lt; n; j++)\n        cnt++;\n    n /= 2;\n}</pre>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<p><b>O(n) — לא O(n·log n)!</b> הפנימית רצה n, ואז n/2, ואז n/4…\nהסכום: n + n/2 + n/4 + … = <b>2n</b>. סכום הנדסי מתכנס לקבוע כפול האיבר\nהראשון.</p>\n<div class=\"warn\" style=\"margin-bottom:0\">ההבדל בין 1.2 ל-1.6: שם הפנימית\nרצה <b>n קבוע</b> בכל סיבוב (מכפלה), כאן היא <b>מצטמקת עם n</b> (סכום).\nלזהות את ההבדל הזה = 4 נקודות.</div>\n</div></details>"},{"id":"BK-1.7","cat":"סיבוכיות","difficulty":3,"skills":["סיבוכיות"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 1.7","prompt":"נתון: המערך <span dir=\"ltr\">arr</span> ממוין, והפונקציה <span dir=\"ltr\">log10</span> עולה <span dir=\"ltr\">O(1)</span>. עבור קטע הקוד הבא, קבע את סיבוכיות זמן הריצה של כל אחת משלוש המסגרות המסומנות (<span dir=\"ltr\">#1, #2, #3</span>) בנפרד, ואת סיבוכיות זמן הריצה של הפונקציה כולה. נמק כל סעיף.","qtype":"analysis","hint":"בכל מסגרת שאל: מה הגבול העליון של הלולאה ומהו הצעד? קבועים כפליים נבלעים בסימון האסימפטוטי.","rule":"מבחן 2018 שאלון A · שאלה 1 · 12 נק'","html":"<div class=\"qh\"><b>1.7</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן עבר</span><span class=\"src\"><span class=\"tag exam\">מבחן 2018 שאלון A · שאלה 1 · 12 נק'</span></span></div>\n<pre class=\"c\">int f1(int arr[], int n, int x)\n{\n    int idx, i, counter = 0;\n    idx = binarySearch(arr, n / 2, x);      // #1\n\n    if (idx &gt;= 0)\n    {\n        for (i = 1; i &lt; log10(n); i *= 10)  // #2\n            counter++;\n        for (i = n; i &gt; 0; i -= 10)         // #3\n            counter++;\n    }\n    return counter;\n}</pre>\n<p>נתון: arr ממוין, log10 עולה O(1). מה הסיבוכיות של #1, #2, #3 ושל כל הפונקציה?</p>\n<details class=\"sol\"><summary>התשובות הרשמיות</summary><div class=\"body\">\n<p><b>#1: O(log n)</b> — חיפוש בינארי על n/2 איברים; הקבוע ½ נבלע בלוגריתם.</p>\n<p><b>#2: O(log log n)</b> — הגבול הוא log₁₀(n) והצעד <code>i *= 10</code>\nכופל פי 10: מגיעים ל-log n בערך תוך log(log n) צעדים.</p>\n<p><b>#3: O(n)</b> — מ-n עד 0 בצעדי 10; הקבוע 1/10 נעלם.</p>\n<p><b>סה\"כ: O(n)</b> — הגדול מבין השלושה.</p>\n</div></details>"},{"id":"BK-1.8","cat":"סיבוכיות","difficulty":4,"skills":["סיבוכיות"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 1.8","prompt":"עבור קטע הקוד הבא, קבע את סיבוכיות זמן הריצה של כל אחת משלוש המסגרות המסומנות (<span dir=\"ltr\">#1, #2, #3</span>) בנפרד, ואת סיבוכיות זמן הריצה של הפונקציה כולה. נמק כל סעיף. נתון ש-<span dir=\"ltr\">MergeSort</span> עולה <span dir=\"ltr\">O(k·log k)</span> על <span dir=\"ltr\">k</span> איברים.","qtype":"analysis","hint":"בדוק בקפידה מהו ערכו של <span dir=\"ltr\">j</span> בסוף הלולאה הפנימית — ומה זה עושה לתנאי של ה-<span dir=\"ltr\">while</span> החיצוני.","rule":"מבחן 2018 שאלון B · שאלה 1 · 12 נק'","html":"<div class=\"qh\"><b>1.8</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🎓 מבחן עבר</span><span class=\"src\"><span class=\"tag exam\">מבחן 2018 שאלון B · שאלה 1 · 12 נק'</span></span></div>\n<pre class=\"c\">int f1(int arr[], int n)\n{\n    int i = 0, j, counter = 0;\n    MergeSort(arr, n / 3);              // #1\n    while (i &lt; n / 3)                   // #2\n    {\n        for (j = 3; j &lt; n / 3; j *= j)  // #3\n            counter++;\n        i = j * 3;\n    }\n    return counter;\n}</pre>\n<details class=\"sol\"><summary>התשובות הרשמיות</summary><div class=\"body\">\n<p><b>#1: O(n·log n)</b> — MergeSort על n/3 איברים.</p>\n<p><b>#2: O(1)</b> — המלכודת: אחרי הסיבוב הראשון <code>j ≥ n/3</code>,\nולכן <code>i = j*3 ≥ n</code> — הלולאה רצה <b>פעם אחת</b>.</p>\n<p><b>#3: O(log log n)</b> — שוב <code>j *= j</code> (ריבוע), כמו ב-2021.</p>\n<p><b>סה\"כ: O(n·log n)</b> — המיון שולט.</p>\n<div class=\"tip\" style=\"margin-bottom:0\">שים לב כמה פעמים חוזרות שתי\nהמלכודות האלה: <code>j *= j</code> → log log (‏2018B, 2021X)\nו\"לולאה שרצה פעם אחת\" (2018B, 2021X, 2021Y). המרצים ממחזרים.</div>\n</div></details>"},{"id":"BK-1.9","cat":"סיבוכיות","difficulty":4,"skills":["סיבוכיות"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 1.9","prompt":"עבור הפונקציה הבאה, קבע את סיבוכיות זמן הריצה של כל אחת משלוש המסגרות המסומנות (<span dir=\"ltr\">#1, #2, #3</span>) בנפרד, ואת סיבוכיות זמן הריצה של הפונקציה כולה. נמק כל סעיף בפירוט.","qtype":"analysis","hint":"לכל לולאה חשב \"מרחק חלקי גודל צעד\", ובדוק אילו משתנים מתאפסים מחדש בכל סיבוב של הלולאה החיצונית ואילו לא.","rule":"מבחן 2022 · שאלה 1 · 16 נק'","html":"<div class=\"qh\"><b>1.9</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🎓 מבחן עבר</span><span class=\"src\"><span class=\"tag exam\">מבחן 2022 · שאלה 1 · 16 נק'</span> · הקשה מכולן</span></div>\n<pre class=\"c\">int f1(int n)\n{\n    int counter = 0;\n    double i, j;\n    for (i = n * n * n; i &gt; n; i -= n / 3.0)   // #1\n    {\n        j = n * n * n;\n        while (j &gt; n)                          // #2\n        {\n            counter++;\n            j -= 3 * n;\n        }\n        while (j &gt; 0)                          // #3\n        {\n            counter++;\n            j -= 3 * counter;\n        }\n    }\n    return counter;\n}</pre>\n<details class=\"sol\"><summary>התשובות הרשמיות + ההסבר</summary><div class=\"body\">\n<p><b>#1: O(n²)</b> — מרחק n³ בצעדים של n/3: ‏n³ / (n/3) = 3n².</p>\n<p><b>#2: O(n²)</b> — מרחק n³ בצעדים של 3n: ‏n³ / 3n = n²/3.</p>\n<p><b>#3: O(1)</b> — כשמגיעים אליה j ≤ n, ו-counter כבר ענק (מסדר n²\nמהאיטרציות הקודמות), אז ‏j נגמר במספר צעדים חסום.</p>\n<p><b>סה\"כ: O(n⁴)</b> — ‏#1 רץ n² פעמים וכל איטרציה עולה n² בגלל #2.\n<b>מכפלה</b>, כי #2 מתאפס מחדש (<code>j = n³</code>) בכל סיבוב של #1.</p>\n<div class=\"warn\" style=\"margin-bottom:0\">O(n⁴) היא התשובה הגבוהה ביותר\nשהופיעה אי-פעם במבחני הקורס — אל תפחד לכתוב אותה אם החשבון מוביל לשם.</div>\n</div></details>"},{"id":"BK-1.10","cat":"סיבוכיות","difficulty":3,"skills":["סיבוכיות"],"origin":"bank","kind":"open","sourceLabel":"📘 מצגת · 1.10","prompt":"מהי סיבוכיות זמן הריצה של קטע הקוד הבא כפונקציה של <span dir=\"ltr\">n</span>? נמק כמה פעמים רצה כל לולאה והאם מדובר במכפלה או בסכום.","qtype":"analysis","hint":"בדוק אם גבולות הלולאה הפנימית תלויים ב-<span dir=\"ltr\">i</span>.","rule":"מצגת הסיבוכיות · שקף 34","html":"<div class=\"qh\"><b>1.10</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">📘 מצגת המרצה</span><span class=\"src\">מצגת הסיבוכיות · שקף 34</span></div>\n<pre class=\"c\">for (i = 0; i &lt;= n*n; i++)\n    for (j = n; j &gt; 1; j /= 2)\n        printf(\"hi!\\n\");</pre>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<p><b>O(n²·log n)</b> — החיצונית n², הפנימית log n, אין תלות ⟵ מכפלה.\nזו הדוגמה הרשמית מהמצגת לשילוב \"טווח ריבועי × חלוקה\".</p>\n</div></details>"},{"id":"BK-1.11","cat":"סיבוכיות","difficulty":3,"skills":["סיבוכיות"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 1.11","prompt":"עבור קטע הקוד הבא, קבע את סיבוכיות זמן הריצה של כל אחת משלוש המסגרות המסומנות (<span dir=\"ltr\">#1, #2, #3</span>) ואת הסיבוכיות הכוללת. נמק — במיוחד: כמה פעמים באמת רצה לולאת ה-<span dir=\"ltr\">while</span> שבמסגרת <span dir=\"ltr\">#2</span>?","qtype":"analysis","hint":"עקוב אחרי הערך של <span dir=\"ltr\">j</span> אחרי שהלולאה הפנימית מסתיימת, ואז חשב את <span dir=\"ltr\">i = j - 1</span>.","rule":"סיבוכיות — הריבוע והלולאה החד-פעמית","html":"<div class=\"qh\"><b>1.11</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2021 · ש'1 · 12 נק'</span><span class=\"src\">סיבוכיות — הריבוע והלולאה החד-פעמית</span></div>\n<pre class=\"c\">for (i = 2; i &lt;= n*n; i = i*i)   // #1\n    counter++;\nwhile (i &gt; 0)                    // #2\n{   for (j = n/2; j &gt;= 1; j /= 2)  // #3\n        counter++;\n    i = j - 1; }</pre>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p>‏#1: <b>O(log log n)</b> (ריבוע) · ‏#2: <b>רץ פעם אחת</b> (‏j יורד מתחת ל-1 ולכן <code>i &lt;= 0</code>) ·\n‏#3: <b>O(log n)</b> · סה\"כ: <b>O(log n)</b>.</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d01','')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-1.12","cat":"סיבוכיות","difficulty":3,"skills":["סיבוכיות"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 1.12","prompt":"נתון <span dir=\"ltr\">i = log(n)</span>. עבור קטע הקוד הבא, קבע את סיבוכיות זמן הריצה של כל אחת משלוש המסגרות המסומנות (<span dir=\"ltr\">#1, #2, #3</span>) ואת הסיבוכיות הכוללת. נמק.","qtype":"analysis","hint":"כשהגבול העליון של לולאה הוא <span dir=\"ltr\">log n</span> — התייחס אל <span dir=\"ltr\">log n</span> כאילו הוא ה-<span dir=\"ltr\">n</span> החדש.","rule":"סיבוכיות — לולאות על log n","html":"<div class=\"qh\"><b>1.12</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2023 · ש'1 · 16 נק'</span><span class=\"src\">סיבוכיות — לולאות על log n</span></div>\n<pre class=\"c\">for (j = log(n); j &gt; 2; j /= 4)      // #1\nwhile (i &gt; 1) {                      // #2, i=log(n)\n    for (j = 100; j &lt; n*n; j *= 100) // #3\n        counter++;\n    i--; }</pre>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p>‏#1: <b>O(log log n)</b> · ‏#2: <b>O(log n)</b> · ‏#3: <b>O(log n)</b> ·\nסה\"כ: <b>O(log²n)</b> — ‏log n הוא \"ה-n החדש\".</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d17','')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-1.13","cat":"סיבוכיות","difficulty":3,"skills":["סיבוכיות"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 1.13","prompt":"קבע את סיבוכיות זמן הריצה בכל אחד משלושת הסעיפים הבאים, ונמק: (א) שתי לולאות <span dir=\"ltr\">while</span> מקוננות המקדמות את <b>אותו</b> משתנה <span dir=\"ltr\">i</span> על פני רצפים במערך; (ב) לולאה <span dir=\"ltr\">for (i=1; i&lt;log(n); i*=2)</span> ואחריה לולאה <span dir=\"ltr\">for (i=n; i&gt;0; i-=2)</span>; (ג) נוסחת הנסיגה <span dir=\"ltr\">T(n) = 2T(n/2) + O(1)</span>.","qtype":"analysis","hint":"בסעיף א' ספור את סך הצעדים של <span dir=\"ltr\">i</span> לאורך כל הריצה במקום לכפול לולאות; בסעיף ג' השתמש בנוסחת האב.","rule":"סיבוכיות — 3 סעיפים","html":"<div class=\"qh\"><b>1.13</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2024 · ש'1 · 16 נק'</span><span class=\"src\">סיבוכיות — 3 סעיפים</span></div>\n<p>א) שתי while מקוננות שמקדמות את <b>אותו i</b> על רצפים ·\nב) ‏<code>i&lt;log(n); i*=2</code> ואז <code>i=n; i-=2</code> ·\nג) ‏<code>T(n)=2T(n/2)+O(1)</code>.</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p>א: <b>O(n)</b> (סך צעדי i חסום ב-n) · ב: מסגרת <b>O(log log n)</b>,\nהכול <b>O(n)</b> · ג: נוסחת האב ⟵ <b>O(n)</b>.</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d17','')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-1.14","cat":"סיבוכיות","difficulty":4,"skills":["סיבוכיות"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 1.14","prompt":"נתונה הפונקציה הרקורסיבית <span dir=\"ltr\">f1(n)</span> שקודה מופיע למטה. קבע את סיבוכיות זמן הריצה של המסגרת הלא-רקורסיבית (לולאת ה-<span dir=\"ltr\">while</span>), רשום את נוסחת הנסיגה, ופתור אותה. מהי הסיבוכיות הכוללת?","qtype":"analysis","hint":"חשב במדויק כמה איטרציות עושה <span dir=\"ltr\">i = n*n</span> כשבכל צעד מחלקים אותו ב-<span dir=\"ltr\">n</span> — ואז השתמש בנוסחת האב עם שלוש קריאות על <span dir=\"ltr\">n/3</span>.","rule":"סיבוכיות — רקורסיה משולשת","html":"<div class=\"qh\"><b>1.14</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🎓 מבחן 2025 · ש'1א · 6 נק'</span><span class=\"src\">סיבוכיות — רקורסיה משולשת</span></div>\n<pre class=\"c\">if (n &lt; 3) return;\nint i = n*n;\nwhile (i &gt; 1){ printf(\"*\"); i /= n; }  // מסגרת 1\nf1(n/3); f1(n/3); f1(n/3);</pre>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p>רשמית: מסגרת <b>O(n)</b> וסה\"כ <b>O(n·log n)</b> — אבל לפי הקוד המודפס\nהמסגרת היא O(1)! (‏n²→n→1). ראה את ניתוח הסתירה המלא ומה לכתוב במבחן.</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d01','sol-2025-1a')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-1.15","cat":"סיבוכיות","difficulty":3,"skills":["סיבוכיות"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 1.15","prompt":"נתונים שני מערכים: <span dir=\"ltr\">nArr</span> בגודל <span dir=\"ltr\">n</span> ו-<span dir=\"ltr\">mArr</span> ממוין בגודל <span dir=\"ltr\">m</span>. קבע את סיבוכיות זמן הריצה של כל אחת משתי המסגרות המסומנות בקוד הבא ואת הסיבוכיות הכוללת, כפונקציה של <span dir=\"ltr\">n</span> ו-<span dir=\"ltr\">m</span>.","qtype":"analysis","hint":"<span dir=\"ltr\">cnt</span> הוא אינדקס שהוחזר מהחיפוש הבינארי — עד כמה גדול הוא יכול להיות במקרה הגרוע?","rule":"סיבוכיות עם n ו-m","html":"<div class=\"qh\"><b>1.15</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2025 · ש'1ב · 10 נק'</span><span class=\"src\">סיבוכיות עם n ו-m</span></div>\n<pre class=\"c\">for (i = 0; i &lt; n; i++){\n    cnt = binarySearch(mArr, m, nArr[i]);  // מסגרת 1\n    int t = cnt;\n    while (t &gt; 0){ print(\"*\"); t--; }      // מסגרת 2\n}</pre>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p>מסגרת 1: <b>O(log m)</b> · מסגרת 2: <b>O(m)</b> (האינדקס עד m) ·\nסה\"כ: <b>O(n·m)</b>. חובה להבדיל בין n ל-m!</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d17','')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-2.1","cat":"רקורסיה","difficulty":2,"skills":["רקורסיה"],"origin":"bank","kind":"open","sourceLabel":"🤖 קלוד · 2.1","prompt":"עקוב אחרי הפונקציה הרקורסיבית שלמטה: מה יודפס בקריאה <span dir=\"ltr\">mys(1234)</span>? מהי סיבוכיות זמן הריצה שלה? והסבר בעד 8 מילים מה הפונקציה עושה.","qtype":"trace","hint":"שים לב שההדפסה מופיעה <b>אחרי</b> הקריאה הרקורסיבית — איזו ספרה מגיעה להדפסה ראשונה?","rule":"מעקב + הסבר","html":"<div class=\"qh\"><b>2.1</b><span class=\"diff diff-e\">קל</span><span class=\"diff srcb\">🤖 קלוד</span><span class=\"src\">מעקב + הסבר</span></div>\n<pre class=\"c\">void mys(int n)\n{\n    if (n == 0) return;\n    mys(n / 10);\n    printf(\"%d\", n % 10);\n}</pre>\n<p>מה יודפס עבור <code>mys(1234)</code>? מה הסיבוכיות?\nוהסבר ב-≤8 מילים מה הפונקציה עושה.</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<p><b>פלט: 1234.</b> ההדפסה אחרי הקריאה → הספרה העמוקה ביותר (האלפים)\nמודפסת ראשונה.</p>\n<p><b>סיבוכיות:</b> O(log n) — מספר הספרות.</p>\n<p><b>ב-8 מילים:</b> \"מדפיסה את ספרות המספר משמאל לימין\".</p>\n<div class=\"tip\" style=\"margin-bottom:0\"><b>וריאציה שחייבים לזהות:</b> אם\nמעבירים את ה-printf <b>לפני</b> הקריאה — הפלט מתהפך: 4321.\nמיקום הפעולה ביחס לקריאה הרקורסיבית קובע את הכיוון.</div>\n</div></details>"},{"id":"BK-2.2","cat":"רקורסיה","difficulty":2,"skills":["רקורסיה"],"origin":"bank","kind":"open","sourceLabel":"🤖 קלוד · 2.2","prompt":"מה מחזירה הקריאה <span dir=\"ltr\">f(arr, 5)</span> עבור <span dir=\"ltr\">arr = {3, 8, 5, 6, 2}</span>? נמק, והסבר בעד 8 מילים מה הפונקציה עושה.","qtype":"trace","hint":"מהו הערך המספרי של הביטוי <span dir=\"ltr\">(arr[n-1] % 2 == 0)</span> בשפת C?","rule":"מה מוחזר?","html":"<div class=\"qh\"><b>2.2</b><span class=\"diff diff-e\">קל</span><span class=\"diff srcb\">🤖 קלוד</span><span class=\"src\">מה מוחזר?</span></div>\n<pre class=\"c\">int f(int arr[], int n)\n{\n    if (n == 0) return 0;\n    return f(arr, n - 1) + (arr[n-1] % 2 == 0);\n}</pre>\n<p>מה מחזירה <code>f(arr, 5)</code> עבור <code>arr = {3, 8, 5, 6, 2}</code>?\nוהסבר ב-≤8 מילים.</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<p><b>מוחזר 3</b> — הביטוי <code>(arr[n-1]%2==0)</code> שווה 1 לזוגי ו-0\nלאי-זוגי, והרקורסיה סוכמת: 8, 6, 2 זוגיים.</p>\n<p><b>ב-8 מילים:</b> \"סופרת כמה מספרים זוגיים יש במערך\".</p>\n</div></details>"},{"id":"BK-2.3","cat":"רקורסיה","difficulty":2,"skills":["רקורסיה"],"origin":"bank","kind":"open","sourceLabel":"🤖 קלוד · 2.3","prompt":"כתוב פונקציה <b>רקורסיבית</b> <code>int countDigit(int n, int d)</code> המחזירה כמה פעמים מופיעה הספרה <span dir=\"ltr\">d</span> במספר החיובי <span dir=\"ltr\">n</span>. <b>אסור להשתמש בלולאות</b> ובמבני עזר.","qtype":"code","signature":"int countDigit(int n, int d)","hint":"השלד הקבוע: תנאי עצירה, טיפול בספרת האחדות <span dir=\"ltr\">n % 10</span>, ורקורסיה על <span dir=\"ltr\">n / 10</span>.","rule":"כתיבה בלי לולאות","html":"<div class=\"qh\"><b>2.3</b><span class=\"diff diff-e\">קל</span><span class=\"diff srcb\">🤖 קלוד</span><span class=\"src\">כתיבה בלי לולאות</span></div>\n<p>כתוב פונקציה רקורסיבית <code>int countDigit(int n, int d)</code>\nשמחזירה כמה פעמים הספרה d מופיעה במספר החיובי n. <b>בלי לולאות.</b></p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<pre class=\"c\">int countDigit(int n, int d)\n{\n    if (n == 0) return 0;\n    return (n % 10 == d) + countDigit(n / 10, d);\n}</pre>\n<p>השלד הקבוע: תנאי עצירה → פעולה על הספרה הנוכחית → רקורסיה על השאר.\nבדיוק כמו <code>checkDigits</code> מ-2024.</p>\n</div></details>"},{"id":"BK-2.4","cat":"רקורסיה","difficulty":3,"skills":["רקורסיה"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 2.4","prompt":"הפונקציה הרקורסיבית שלמטה מקבלת שני עצים בינאריים (<span dir=\"ltr\">root1</span> ו-<span dir=\"ltr\">root2</span>). הסבר במדויק מה היא עושה ומה בדיוק היא מחזירה. נמק את תשובתך.","qtype":"analysis","hint":"שים לב באילו שדות של הצמתים הקוד נוגע — והאם הוא בכלל משווה מפתחות.","rule":"מבחן 2022 · שאלה 2 · 14 נק'","html":"<div class=\"qh\"><b>2.4</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן עבר</span><span class=\"src\"><span class=\"tag exam\">מבחן 2022 · שאלה 2 · 14 נק'</span> · \"מה עושה הפונקציה?\"</span></div>\n<pre class=\"c\">int func(NODE2* root1, NODE2* root2)\n{\n    if (!root1 &amp;&amp; !root2)\n        return 1;\n    if (!root1 || !root2)\n        return 0;\n    return func(root1-&gt;left,  root2-&gt;left) &amp;&amp;\n           func(root1-&gt;right, root2-&gt;right);\n}</pre>\n<p>הפונקציה מקבלת שני עצים בינאריים. מה היא עושה? יש לכתוב תשובה מדויקת.</p>\n<details class=\"sol\"><summary>התשובה הרשמית</summary><div class=\"body\">\n<p><b>\"הפונקציה בודקת אם מבנה העצים זהה</b> (כלומר, העצים זהים בצורתם,\nאך המפתחות של צמתים במיקום זהה יכולים להיות שונים).\"</p>\n<p><b>איך מזהים:</b> הקוד אף פעם לא נוגע ב-<code>key</code>! רק ב-NULL-ים.\nשני NULL → מסכימים (1). אחד NULL → צורה שונה (0). זו בדיקת <b>צורה</b> בלבד.</p>\n<div class=\"warn\" style=\"margin-bottom:0\">התשובה \"בודקת אם העצים זהים\"\nבלי הסייג על המפתחות — מאבדת נקודות. במבחן 2022 זה היה ההבדל בין תשובה\nמלאה לחלקית.</div>\n</div></details>"},{"id":"BK-2.5","cat":"רקורסיה","difficulty":2,"skills":["רקורסיה"],"origin":"bank","kind":"open","sourceLabel":"🌐 אינטרנט · 2.5","prompt":"מה מדפיסה הקריאה <span dir=\"ltr\">mys(13)</span> עבור הפונקציה שלמטה? נמק, והסבר בעד 8 מילים מה הפונקציה עושה.","qtype":"trace","hint":"ההדפסה היא של השאריות בחלוקה ב-2, וההדפסה מתבצעת אחרי הקריאה הרקורסיבית.","rule":"מעובד ממאגרי תרגול באינטרנט (קלאסיקה)","html":"<div class=\"qh\"><b>2.5</b><span class=\"diff diff-e\">קל</span><span class=\"diff srcb\">🌐 אינטרנט</span><span class=\"src\">מעובד ממאגרי תרגול באינטרנט (קלאסיקה)</span></div>\n<p>מה מדפיסה <code>mys(13)</code>? והסבר ב-≤8 מילים.</p>\n<pre class=\"c\">void mys(int n)\n{\n    if (n == 0) return;\n    mys(n / 2);\n    printf(\"%d\", n % 2);\n}</pre>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<p><b>פלט: 1101</b> — הייצוג הבינארי של 13.</p>\n<p>אותו שלד בדיוק כמו הדפסת ספרות (2.1), רק בבסיס 2: השארית העמוקה\nביותר (הביט המשמעותי) מודפסת ראשונה.</p>\n<p><b>ב-8 מילים:</b> \"מדפיסה את הייצוג הבינארי של המספר\".</p>\n</div></details>"},{"id":"BK-2.6","cat":"רקורסיה","difficulty":3,"skills":["רקורסיה"],"origin":"bank","kind":"open","sourceLabel":"📝 מטלה · 2.6","prompt":"מערך נקרא <b>\"מערך מתגלגל\"</b> אם ספרת האחדות של האיבר ה-<span dir=\"ltr\">i</span> שווה לספרה השמאלית ביותר של האיבר ה-<span dir=\"ltr\">i+1</span> (לדוגמה <span dir=\"ltr\">[123, 38, 82, 29, 91]</span> הוא מערך מתגלגל). כתוב פונקציה <b>רקורסיבית</b> <code>int isRollingArray(int a[], int n)</code> המחזירה 1 אם המערך מתגלגל ו-0 אחרת. <b>בלי לולאות ובלי מבני עזר</b> (מותר להיעזר בפונקציית עזר רקורסיבית).","qtype":"code","signature":"int isRollingArray(int a[], int n)","hint":"כדי \"לקצר\" את המערך בלי מבנה עזר אפשר להעביר <span dir=\"ltr\">a + 1</span> עם <span dir=\"ltr\">n - 1</span>; לחילוץ הספרה השמאלית כתוב פונקציית עזר רקורסיבית.","rule":"שאלה 1 — isRollingArray","html":"<div class=\"qh\"><b>2.6</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">📝 מטלה HW1</span><span class=\"src\">שאלה 1 — isRollingArray</span></div>\n<p>\"מערך מתגלגל\": ספרת האחדות של האיבר ה-i שווה לספרה השמאלית ביותר\nשל האיבר ה-i+1 (למשל <code>[123,38,82,29,91]</code>). כתוב פונקציה\nרקורסיבית שבודקת זאת — בלי לולאות ובלי מבנה עזר.</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<pre class=\"c\">int leftDigit(int x)\n{\n    return x &lt; 10 ? x : leftDigit(x / 10);\n}\n\nint isRollingArray(int a[], int n)\n{\n    if (n &lt;= 1) return 1;\n    if (a[0] % 10 != leftDigit(a[1])) return 0;\n    return isRollingArray(a + 1, n - 1);\n}</pre>\n<p><b>שני רעיונות:</b> פונקציית עזר רקורסיבית במקום לולאה לספרה\nהשמאלית, ו-<code>a+1</code> כדי \"לקצר\" את המערך בלי מבנה עזר.\nבדיקה על הדוגמה: ‏3=3 ✔ ‏8=8 ✔ ‏2=2 ✔ ‏9=9 ✔.</p>\n</div></details>"},{"id":"BK-2.7","cat":"רקורסיה","difficulty":3,"skills":["רקורסיה"],"origin":"bank","kind":"open","sourceLabel":"📝 מטלה · 2.7","prompt":"כתוב פונקציה <b>רקורסיבית</b> <code>int changeEvenToZero(int n)</code> המקבלת מספר שלם חיובי ומחזירה את המספר שבו כל ספרה זוגית הוחלפה ב-0. לדוגמה: <span dir=\"ltr\">1254 → 1050</span>, <span dir=\"ltr\">332 → 330</span>, <span dir=\"ltr\">24 → 0</span>, <span dir=\"ltr\">13 → 13</span>. <b>אסור להשתמש בלולאות.</b>","qtype":"code","signature":"int changeEvenToZero(int n)","hint":"כדי לבנות מחדש את המספר: את תוצאת הרקורסיה על <span dir=\"ltr\">n/10</span> יש להכפיל ב-10 ולהוסיף את הספרה המטופלת.","rule":"שאלה 3 — changeEvenToZero","html":"<div class=\"qh\"><b>2.7</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">📝 מטלה HW1</span><span class=\"src\">שאלה 3 — changeEvenToZero</span></div>\n<p>מקבלת מספר חיובי ומחזירה מספר שבו כל ספרה זוגית הפכה ל-0.\n‏1254⟵1050 · ‏332⟵330 · ‏24⟵0 · ‏13⟵13. רקורסיה, בלי לולאות.</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<pre class=\"c\">int changeEvenToZero(int n)\n{\n    if (n == 0) return 0;\n    int d = n % 10;\n    if (d % 2 == 0) d = 0;\n    return changeEvenToZero(n / 10) * 10 + d;\n}</pre>\n<p><b>הבנייה מחדש:</b> התוצאה של \"שאר המספר\" מוכפלת ב-10 ומקבלת את\nהספרה המטופלת. ‏1254: ‏4⟵0, ‏5, ‏2⟵0, ‏1 ⟵ ‏1050 ✔.</p>\n</div></details>"},{"id":"BK-2.8","cat":"רקורסיה","difficulty":4,"skills":["רקורסיה"],"origin":"bank","kind":"open","sourceLabel":"📝 מטלה · 2.8","prompt":"נתונים <span dir=\"ltr\">balls</span> כדורים זהים ו-<span dir=\"ltr\">cells</span> תאים, כאשר בכל תא מותר להניח 0, 1 או 2 כדורים בלבד. כתוב פונקציה <b>רקורסיבית</b> <code>int countOptions(int balls, int cells)</code> המחזירה את מספר הפיזורים האפשריים של כל הכדורים בתאים. <b>בלי לולאות ובלי מבני עזר.</b> מהי סיבוכיות הפתרון?","qtype":"code","signature":"int countOptions(int balls, int cells)","hint":"לכל תא יש שלוש אפשרויות — סכם את שלוש הרקורסיות, וזהה בזהירות את שני תנאי העצירה (נגמרו הכדורים / נגמרו התאים).","rule":"שאלה 4 — countOptions","html":"<div class=\"qh\"><b>2.8</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">📝 מטלה HW1</span><span class=\"src\">שאלה 4 — countOptions</span></div>\n<p>‏balls כדורים זהים, ‏cells תאים, בכל תא 0/1/2 כדורים. החזר את מספר\nהפיזורים האפשריים. רקורסיה בלבד, בלי לולאות ובלי עזר.</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<pre class=\"c\">int countOptions(int balls, int cells)\n{\n    if (balls == 0) return 1;      /* פיזרנו הכול — דרך אחת */\n    if (cells == 0) return 0;      /* נשארו כדורים בלי תא   */\n\n    int ways = countOptions(balls, cells - 1)      /* תא ריק   */\n             + countOptions(balls - 1, cells - 1); /* כדור אחד */\n    if (balls &gt;= 2)\n        ways += countOptions(balls - 2, cells - 1);/* שני כדורים */\n    return ways;\n}</pre>\n<p><b>העץ המשולש:</b> כל תא בוחר 0/1/2 — שלוש קריאות ⟵ סיבוכיות\nO(3^cells). זו רקורסיה קומבינטורית — הקשה ביותר ב-HW1, ובסיס מצוין\nלשאלות \"ספירת אפשרויות\".</p>\n</div></details>"},{"id":"BK-2.9","cat":"רקורסיה","difficulty":2,"skills":["רקורסיה"],"origin":"bank","kind":"open","sourceLabel":"📘 מצגת · 2.9","prompt":"כתוב פונקציה <b>רקורסיבית</b> <code>int power(int n, int k)</code> המחזירה את <span dir=\"ltr\">n</span> בחזקת <span dir=\"ltr\">k</span> (עבור <span dir=\"ltr\">k ≥ 0</span>), ללא לולאות. מהי סיבוכיות זמן הריצה שלה? צייר גם את מחסנית הקריאות עבור קריאה לדוגמה.","qtype":"code","signature":"int power(int n, int k)","hint":"תנאי העצירה הוא <span dir=\"ltr\">k == 0</span> (חזקה 0 שווה 1); בכל צעד מקטינים את המעריך באחד.","rule":"מצגת הרקורסיה — חישוב חזקה","html":"<div class=\"qh\"><b>2.9</b><span class=\"diff diff-e\">קל</span><span class=\"diff srcb\">📘 מצגת המרצה</span><span class=\"src\">מצגת הרקורסיה — חישוב חזקה</span></div>\n<p>כתוב <code>int power(int n, int k)</code> רקורסיבית. מה הסיבוכיות?</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<pre class=\"c\">int power(int n, int k)\n{\n    if (k == 0) return 1;\n    return power(n, k - 1) * n;\n}</pre>\n<p><b>O(k)</b> — ‏k קריאות, כל אחת O(1). הדוגמה שבה המצגת מציירת את\nמחסנית הקריאות שלב-שלב — לדעת לצייר אותה גם ביד.</p>\n</div></details>"},{"id":"BK-2.10","cat":"רקורסיה","difficulty":2,"skills":["רקורסיה"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 2.10","prompt":"כתוב פונקציה <b>רקורסיבית</b> <code>int sumPositiveInArray(int a[], int n)</code> המחזירה את סכום האיברים החיוביים במערך. לדוגמה: עבור <span dir=\"ltr\">[3, −2, 4, −5, 1, −23]</span> יוחזר <span dir=\"ltr\">8</span>. <b>אסור להשתמש בלולאות.</b>","qtype":"code","signature":"int sumPositiveInArray(int a[], int n)","hint":"צמצם את הבעיה למערך באורך <span dir=\"ltr\">n-1</span>, והוסף את האיבר האחרון רק אם הוא חיובי.","rule":"sumPositiveInArray — בלי לולאות","html":"<div class=\"qh\"><b>2.10</b><span class=\"diff diff-e\">קל</span><span class=\"diff srcb\">🎓 מבחן 2023 · ש'4 · 18 נק'</span><span class=\"src\">sumPositiveInArray — בלי לולאות</span></div>\n<p>מחזירה את סכום האיברים החיוביים במערך. ‏[3,−2,4,−5,1,−23] ⟵ 8.</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<pre class=\"c\">int sumPositiveInArray(int a[], int n)\n{\n    if (n == 0) return 0;\n    int rest = sumPositiveInArray(a, n - 1);\n    return a[n-1] &gt; 0 ? a[n-1] + rest : rest;\n}</pre>\n<p><a class=\"golink\" onclick=\"jumpSol('d02','sol-rec-write')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-2.11","cat":"רקורסיה","difficulty":3,"skills":["רקורסיה"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 2.11","prompt":"כתוב פונקציה <b>רקורסיבית</b> <code>int checkDigits(int n)</code> המקבלת מספר שלם חיובי ומחזירה 1 אם <b>כל</b> ספרותיו זוגיות או ש<b>כל</b> ספרותיו אי-זוגיות, ו-0 אחרת. לדוגמה: <span dir=\"ltr\">2468 → 1</span>, <span dir=\"ltr\">1357 → 1</span>, <span dir=\"ltr\">1245 → 0</span>. <b>אסור להשתמש בלולאות.</b>","qtype":"code","signature":"int checkDigits(int n)","hint":"במקום לזכור את זוגיות הספרה הראשונה, השווה בכל צעד את הזוגיות של שתי ספרות <b>שכנות</b>.","rule":"checkDigits — כל הספרות באותה זוגיות","html":"<div class=\"qh\"><b>2.11</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2024 · ש'2 · 12 נק'</span><span class=\"src\">checkDigits — כל הספרות באותה זוגיות</span></div>\n<p>מחזירה 1 אם כל הספרות זוגיות או כולן אי-זוגיות. ‏2468⟵1 ·\n‏1357⟵1 · ‏1245⟵0.</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<pre class=\"c\">int checkDigits(int n)\n{\n    if (n &lt; 10) return 1;             /* ספרה אחת */\n    if ((n % 10) % 2 != ((n/10) % 10) % 2)\n        return 0;                     /* שכנות שונות */\n    return checkDigits(n / 10);\n}</pre>\n<p>משווים <b>זוגיות של שכנות</b> — אם כל שכנות מסכימות, כולן זהות.</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d02','sol-rec-write')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-2.12","cat":"רקורסיה","difficulty":3,"skills":["רקורסיה"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 2.12","prompt":"נתונה הפונקציה הרקורסיבית <code>rec(char s[], int n)</code> המבצעת מעבר אחד על המחרוזת ומחליפה בין כל שני תווים שכנים שאינם בסדר עולה, ואז קוראת לעצמה עם <span dir=\"ltr\">rec(s, n-1)</span>. עבור המחרוזת <span dir=\"ltr\">\"omgicu\"</span>: (א) מה יודפס בסיום? (ב) מהי סיבוכיות זמן הריצה? (ג) הסבר בעד 8 מילים מה הפונקציה עושה.","qtype":"trace","hint":"רשום את המחרוזת אחרי כל מעבר; נוסחת הנסיגה היא <span dir=\"ltr\">T(n) = T(n−1) + O(n)</span>, ואת האלגוריתם המוסווה אתה כבר מכיר בשם אחר.","rule":"rec על \"omgicu\" — פלט, סיבוכיות, 8 מילים","html":"<div class=\"qh\"><b>2.12</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2025 · ש'2 · 12 נק'</span><span class=\"src\">rec על \"omgicu\" — פלט, סיבוכיות, 8 מילים</span></div>\n<p>לולאת החלפת-שכנים ואז <code>rec(s, n-1)</code>, על \"omgicu\".</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p>פלט: <b>cgimou</b> · סיבוכיות: <b>O(n²)</b>\n(‏T(n)=T(n−1)+O(n)) · ‏8 מילים: <b>\"מיון בועות\"</b> — לזהות את המיון\nהמוסווה.</p>\n<p><b>🎬 המחרוזת מתמיינת מול העיניים — מעבר אחר מעבר:</b></p>\n<div id=\"d14_p2\"></div>\n<p><a class=\"golink\" onclick=\"jumpSol('d17','')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-3.1","cat":"רשימות מקושרות","difficulty":3,"skills":["רשימות מקושרות"],"origin":"bank","kind":"open","sourceLabel":"🤖 קלוד · 3.1","prompt":"כתוב פונקציה <code>void deleteEverySecond(NODE* head)</code> המקבלת מצביע לצומת <b>הראשון</b> ברשימה מקושרת חד-כיוונית, ומוחקת ממנה (כולל שחרור הזיכרון) את כל האיברים שבמקומות הזוגיים — השני, הרביעי, השישי וכן הלאה.","qtype":"code","signature":"void deleteEverySecond(NODE* head)","hint":"שמור את הצומת שנמחק במשתנה עזר, עקוף אותו <b>לפני</b> ה-<span dir=\"ltr\">free</span>, ואז המשך מהצומת הבא ששרד.","rule":"מחיקה לסירוגין","html":"<div class=\"qh\"><b>3.1</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🤖 קלוד</span><span class=\"src\">מחיקה לסירוגין</span></div>\n<p>כתוב <code>void deleteEverySecond(NODE* head)</code> שמוחקת את כל\nהאיברים במקומות הזוגיים (השני, הרביעי…). <code>head</code> הוא הצומת הראשון.</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<pre class=\"c\">void deleteEverySecond(NODE* head)\n{\n    if (!head || !head-&gt;next)\n        return;\n\n    NODE* tmp = head-&gt;next;          // הצומת שנמחק\n    head-&gt;next = tmp-&gt;next;          // עוקפים אותו\n    free(tmp);\n\n    deleteEverySecond(head-&gt;next);   // הבא שנשאר — שוב \"ראשון\"\n}</pre>\n<p>שים לב לסדר: קודם עוקפים (<code>head-&gt;next = tmp-&gt;next</code>),\nרק אז <code>free</code>. הפוך — ואיבדת את הרשימה.</p>\n</div></details>"},{"id":"BK-3.2","cat":"רשימות מקושרות","difficulty":4,"skills":["רשימות מקושרות"],"origin":"bank","kind":"open","sourceLabel":"🤖 קלוד · 3.2","prompt":"נתונה רשימה מקושרת עם חוליית ראש דמה (<span dir=\"ltr\">LIST</span> עם שדה <span dir=\"ltr\">head</span>), כפי שנלמד בקורס. כתוב פונקציה <code>void moveMaxToEnd(LIST* pLst)</code> המעבירה את הצומת בעל הערך המקסימלי לסוף הרשימה. <b>אסור להקצות או לשחרר זיכרון ואסור להעתיק ערכים בין צמתים</b> — יש להזיז מצביעים בלבד. טפל במקרי הקצה.","qtype":"code","signature":"void moveMaxToEnd(LIST* pLst)","hint":"כדי לנתק צומת צריך מצביע ל<b>קודם</b> לו — לכן סרוק לפי <span dir=\"ltr\">p-&gt;next</span>, ואל תשכח את המקרה שבו המקסימום כבר אחרון.","rule":"בלי הקצאת זיכרון — בסגנון 2025 ש'3","html":"<div class=\"qh\"><b>3.2</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🤖 קלוד</span><span class=\"src\">בלי הקצאת זיכרון — בסגנון 2025 ש'3</span></div>\n<p>כתוב <code>void moveMaxToEnd(LIST* pLst)</code> שמעבירה את הצומת עם\nהערך המקסימלי לסוף הרשימה. <b>בלי הקצאה או שחרור זיכרון</b> — רק הזזת\nמצביעים. (לרשימה head דמה כמו בקורס.)</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<pre class=\"c\">void moveMaxToEnd(LIST* pLst)\n{\n    NODE *p, *pMaxPrev, *pMax, *pLast;\n\n    if (!pLst-&gt;head.next || !pLst-&gt;head.next-&gt;next)\n        return;                       // 0 או 1 איברים\n\n    pMaxPrev = &amp;pLst-&gt;head;           // מחפשים את *הקודם* למקסימום\n    for (p = &amp;pLst-&gt;head; p-&gt;next; p = p-&gt;next)\n        if (p-&gt;next-&gt;key &gt; pMaxPrev-&gt;next-&gt;key)\n            pMaxPrev = p;\n\n    pMax = pMaxPrev-&gt;next;\n    if (!pMax-&gt;next)                  // המקסימום כבר אחרון\n        return;\n\n    pMaxPrev-&gt;next = pMax-&gt;next;      // ניתוק\n\n    pLast = pMaxPrev;                 // הליכה עד הסוף\n    while (pLast-&gt;next)\n        pLast = pLast-&gt;next;\n\n    pLast-&gt;next = pMax;               // חיבור בסוף\n    pMax-&gt;next  = NULL;\n}</pre>\n<p><b>שני הלקחים הקבועים:</b> תמיד לשמור מצביע ל<b>קודם</b> (לכן הסריקה\nעל <code>p-&gt;next</code>), ותמיד לבדוק את מקרה הקצה \"כבר בסוף\".</p>\n</div></details>"},{"id":"BK-3.3","cat":"רשימות מקושרות","difficulty":2,"skills":["רשימות מקושרות"],"origin":"bank","kind":"open","sourceLabel":"🤖 קלוד · 3.3","prompt":"כתוב פונקציה <b>רקורסיבית</b> <code>BOOL isSortedList(NODE* head)</code> הבודקת אם רשימה מקושרת חד-כיוונית ממוינת בסדר עולה. <b>אסור להשתמש בלולאות.</b>","qtype":"code","signature":"BOOL isSortedList(NODE* head)","hint":"רשימה ריקה או בת צומת אחד ממוינת תמיד; אחרת השווה את הצומת הנוכחי לזה שאחריו והמשך.","rule":"רקורסיה על רשימה","html":"<div class=\"qh\"><b>3.3</b><span class=\"diff diff-e\">קל</span><span class=\"diff srcb\">🤖 קלוד</span><span class=\"src\">רקורסיה על רשימה</span></div>\n<p>כתוב <code>BOOL isSortedList(NODE* head)</code> שבודקת אם הרשימה ממוינת\nבסדר עולה. <b>בלי לולאות.</b></p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<pre class=\"c\">BOOL isSortedList(NODE* head)\n{\n    if (!head || !head-&gt;next)\n        return True;                  // 0/1 איברים — ממוין\n\n    if (head-&gt;key &gt; head-&gt;next-&gt;key)\n        return False;\n\n    return isSortedList(head-&gt;next);\n}</pre>\n<p>אותו רעיון בדיוק כמו <code>isSorted</code> על מחסנית מ-2021 —\nרק שברשימה אפשר \"להציץ\" עם <code>head-&gt;next</code> בלי להרוס כלום.</p>\n</div></details>"},{"id":"BK-3.4","cat":"רשימות מקושרות","difficulty":3,"skills":["רשימות מקושרות"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 3.4","prompt":"כתוב פונקציה <b>רקורסיבית</b> <code>void PrintEvenPlaces(NODE* pNode)</code> המקבלת מצביע לאיבר הראשון ברשימה מקושרת ומדפיסה את הערכים שנמצאים במקומות ה<b>זוגיים</b> (השני, הרביעי, השישי…). לדוגמה: עבור הרשימה <span dir=\"ltr\">1,2,4,3,5,7,12,14,15</span> יודפס <span dir=\"ltr\">2,3,7,14</span>. בנוסף, כתוב את שורת הקריאה לפונקציה בהינתן ההגדרה <code>LIST lst;</code>","qtype":"code","signature":"void PrintEvenPlaces(NODE* pNode)","hint":"דרוש תנאי עצירה <b>כפול</b> — גם <span dir=\"ltr\">pNode == NULL</span> וגם <span dir=\"ltr\">pNode-&gt;next == NULL</span> — אחרת רשימה באורך אי-זוגי תגרום לקריסה. וזכור ש-<span dir=\"ltr\">head</span> הוא חוליית דמה.","rule":"מבחן 2018 שאלון A · שאלה 4 · 18 נק'","html":"<div class=\"qh\"><b>3.4</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן עבר</span><span class=\"src\"><span class=\"tag exam\">מבחן 2018 שאלון A · שאלה 4 · 18 נק'</span> · רקורסיה על רשימה</span></div>\n<p>כתוב פונקציה <b>רקורסיבית</b> <code>PrintEvenPlaces</code> שמקבלת את\nהאיבר הראשון ברשימה ומדפיסה את הערכים במקומות ה<b>זוגיים</b> (2, 4, 6…).\n<br>לדוגמה: עבור <code>1,2,4,3,5,7,12,14,15</code> יודפס <code>2,3,7,14</code>.\n<br>בנוסף, השלם את שורת הקריאה בהינתן <code>LIST lst;</code></p>\n<details class=\"sol\"><summary>הפתרון הרשמי</summary><div class=\"body\">\n<pre class=\"c\">void PrintEvenPlaces(NODE* pNode)\n{\n    if (pNode == NULL || pNode-&gt;next == NULL)\n        return;\n    printf(\"%d \", pNode-&gt;next-&gt;key);     // המקום הזוגי הבא\n    pNode = pNode-&gt;next-&gt;next;           // קפיצה של 2\n    PrintEvenPlaces(pNode);\n}</pre>\n<p><b>הקריאה:</b> <code>PrintEvenPlaces(lst.head.next);</code> —\nה-head הוא דמה, האיבר הראשון האמיתי הוא <code>head.next</code>.</p>\n<div class=\"tip\" style=\"margin-bottom:0\">תנאי העצירה הכפול\n(<code>NULL || next==NULL</code>) הוא הנקודה שנבדקת: רשימה באורך אי-זוגי\nמסתיימת בלי איבר במקום זוגי — ובלי הבדיקה הכפולה תקרוס.</div>\n</div></details>"},{"id":"BK-3.5","cat":"רשימות מקושרות","difficulty":4,"skills":["רשימות מקושרות"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 3.5","prompt":"כתוב פונקציה <code>void EvenOddList(LIST* pLst)</code> המסדרת מחדש רשימה מקושרת כך שכל האיברים הזוגיים יופיעו לפני כל האי-זוגיים (הסדר הפנימי בכל קבוצה אינו חשוב). <b>בלי מבנה עזר</b>; מותר להשתמש בפונקציות <code>L_insert</code> ו-<code>L_delete</code> של הקורס. לדוגמה: <span dir=\"ltr\">1,2,4,3,5,7,12,14,15</span> יכולה להפוך ל-<span dir=\"ltr\">14,12,4,2,1,3,5,7,15</span>. שים לב לטפל נכון גם במקרה שבו האיבר הראשון ברשימה זוגי.","qtype":"code","signature":"void EvenOddList(LIST* pLst)","hint":"העתק כל זוגי לראש הרשימה ומחק את המקור; זכור ש-<span dir=\"ltr\">L_delete(pPrev)</span> מוחקת את הצומת <b>שאחרי</b> <span dir=\"ltr\">pPrev</span> — בדוק מה קורה כאשר <span dir=\"ltr\">pPrev</span> הוא עדיין ה-head.","rule":"מבחן 2018 שאלון B · שאלה 4 · 18 נק'","html":"<div class=\"qh\"><b>3.5</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🎓 מבחן עבר</span><span class=\"src\"><span class=\"tag exam\">מבחן 2018 שאלון B · שאלה 4 · 18 נק'</span> · עם L_insert / L_delete</span></div>\n<p>כתוב <code>void EvenOddList(LIST* pLst)</code> שמסדרת את הרשימה כך\nשכל הזוגיים לפני כל האי-זוגיים (הסדר הפנימי לא חשוב). בלי מבנה עזר.\n<br>לדוגמה: <code>1,2,4,3,5,7,12,14,15</code> →\n<code>14,12,4,2,1,3,5,7,15</code>.</p>\n<details class=\"sol\"><summary>הפתרון הרשמי</summary><div class=\"body\">\n<pre class=\"c\">void EvenOddList(LIST* pLst)\n{\n    if (!pLst || !pLst-&gt;head.next)\n        return;\n\n    NODE* pHead = &amp;pLst-&gt;head;\n    NODE* pPrev = pHead;\n    NODE* pNode = pLst-&gt;head.next;\n\n    while (pNode != NULL)\n    {\n        if (pNode-&gt;key % 2 == 0)\n        {\n            L_insert(pHead, pNode-&gt;key);   // שכפול לראש הרשימה\n            L_delete(pPrev);               // מחיקת המקור\n        }\n        else\n            pPrev = pNode;\n\n        pNode = pPrev-&gt;next;\n    }\n}</pre>\n<p><b>הרעיון:</b> כל זוגי \"מועתק\" לראש הרשימה ונמחק ממקומו — בסוף כל\nהזוגיים מקדימה (בסדר הפוך), והאי-זוגיים נשארים בסדרם. שים לב:\n<code>L_delete(pPrev)</code> מוחקת את הצומת <b>שאחרי</b> pPrev —\nהמוסכמה הקבועה של הקורס.</p>\n<div class=\"warn\" style=\"margin-bottom:0\"><b>⚠ באג בפתרון הרשמי כפי\nשמודפס:</b> אם <b>האיבר הראשון ברשימה זוגי</b> (למשל ‏2,3), אז בכניסה\nהראשונה <code>pPrev == pHead</code>, ההעתק החדש נכנס <b>בין</b> ה-head\nלמקור, ו-<code>L_delete(pPrev)</code> מוחקת את ההעתק במקום את המקור —\nלולאה אינסופית! (על הדוגמה שבשאלון, שמתחילה ב-1, זה לא מתגלה.)\n<b>התיקון</b> — שורה אחת אחרי ה-insert:\n<pre class=\"c\">L_insert(pHead, pNode-&gt;key);\nif (pPrev == pHead)\n    pPrev = pHead-&gt;next;   /* ההעתק החדש הוא כעת הקודם למקור */\nL_delete(pPrev);</pre>\nבמבחן: כתוב את הגרסה המתוקנת — ואם אתה מזהה\nבאג כזה בקוד נתון, לציין אותו שווה נקודות.</div>\n</div></details>"},{"id":"BK-3.6","cat":"רשימות מקושרות","difficulty":3,"skills":["רשימות מקושרות"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 3.6","prompt":"ממש את הפונקציה <code>void insertNumToSortList(LIST* plst, int num)</code> המקבלת רשימה מקושרת <b>ממוינת בסדר עולה</b> (עם חוליית ראש דמה) ומכניסה אליה את הערך <span dir=\"ltr\">num</span> במקום הנכון, כך שהרשימה תישאר ממוינת. טפל בכל המקרים: הכנסה לראש, לאמצע ולסוף.","qtype":"code","signature":"void insertNumToSortList(LIST* plst, int num)","hint":"התחל את הסריקה מחוליית הדמה ועצור על הצומת <b>שאחריו</b> יש להכניס; בתנאי ה-<span dir=\"ltr\">while</span> בדוק <span dir=\"ltr\">NULL</span> לפני שאתה ניגש ל-<span dir=\"ltr\">key</span>.","rule":"מבחן 2022 · שאלה 3 · 16 נק'","html":"<div class=\"qh\"><b>3.6</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן עבר</span><span class=\"src\"><span class=\"tag exam\">מבחן 2022 · שאלה 3 · 16 נק'</span> · הכנסה לרשימה ממוינת</span></div>\n<p>ממש <code>void insertNumToSortList(LIST* plst, int num)</code> —\nמכניסה את num לרשימה ממוינת בסדר עולה כך שהמיון נשמר.</p>\n<details class=\"sol\"><summary>פתרון (בסגנון פתרונות הקורס)</summary><div class=\"body\">\n<pre class=\"c\">void insertNumToSortList(LIST* plst, int num)\n{\n    NODE* pPrev = &amp;plst-&gt;head;            // מתחילים מהדמה\n\n    while (pPrev-&gt;next != NULL &amp;&amp;\n           pPrev-&gt;next-&gt;key &lt; num)\n        pPrev = pPrev-&gt;next;\n\n    L_insert(pPrev, num);                 // מכניסה אחרי pPrev\n}</pre>\n<p><b>למה זה כל הסיפור:</b> בזכות ה-head הדמה אין שום מקרה קצה —\nהכנסה לראש, לאמצע ולסוף כולן \"הכנסה אחרי pPrev\". התנאי המורכב\n(<code>next != NULL &amp;&amp; next-&gt;key &lt; num</code>) חייב להיבדק\n<b>בסדר הזה</b> — הפוך, ותקרוס על סוף הרשימה.</p>\n</div></details>"},{"id":"BK-3.7","cat":"רשימות מקושרות","difficulty":3,"skills":["רשימות מקושרות"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 3.7","prompt":"כתוב פונקציה <code>BOOL MergeLists(LIST* L1, LIST* L2, LIST* L3)</code> הממזגת שתי רשימות מקושרות הממוינות בסדר עולה, <span dir=\"ltr\">L1</span> ו-<span dir=\"ltr\">L2</span>, לתוך הרשימה <span dir=\"ltr\">L3</span> (שהיא ריקה ומאותחלת), כך ש-<span dir=\"ltr\">L3</span> תהיה ממוינת בסדר עולה. מותר להשתמש בפונקציות הבסיסיות של הקורס. מהי סיבוכיות הפתרון?","qtype":"code","signature":"BOOL MergeLists(LIST* L1, LIST* L2, LIST* L3)","hint":"החזק מצביע לכל אחת מהרשימות ומצביע \"זנב\" לסוף <span dir=\"ltr\">L3</span>; <span dir=\"ltr\">L_insert</span> מחזירה את הצומת החדש — נצל זאת כדי לקדם את הזנב. אל תשכח את שאריות הרשימות.","rule":"מבחן 2019 שאלון X · שאלה 4 · 20 נק'","html":"<div class=\"qh\"><b>3.7</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן עבר</span><span class=\"src\"><span class=\"tag exam\">מבחן 2019 שאלון X · שאלה 4 · 20 נק'</span> · מיזוג רשימות</span></div>\n<p>כתוב <code>BOOL MergeLists(LIST* L1, LIST* L2, LIST* L3)</code> —\nממזגת שתי רשימות ממוינות בסדר עולה לרשימה L3 (ריקה ומאותחלת),\nכך ש-L3 ממוינת. מותר להשתמש בפונקציות הבסיסיות.</p>\n<details class=\"sol\"><summary>פתרון (בסגנון פתרונות הקורס)</summary><div class=\"body\">\n<pre class=\"c\">BOOL MergeLists(LIST* L1, LIST* L2, LIST* L3)\n{\n    NODE *p1 = L1-&gt;head.next;\n    NODE *p2 = L2-&gt;head.next;\n    NODE *pTail = &amp;L3-&gt;head;          // תמיד מצביע לאחרון ב-L3\n\n    while (p1 != NULL &amp;&amp; p2 != NULL)\n    {\n        if (p1-&gt;key &lt;= p2-&gt;key)\n        {\n            pTail = L_insert(pTail, p1-&gt;key);\n            p1 = p1-&gt;next;\n        }\n        else\n        {\n            pTail = L_insert(pTail, p2-&gt;key);\n            p2 = p2-&gt;next;\n        }\n    }\n    while (p1 != NULL)                 // שארית L1\n    {\n        pTail = L_insert(pTail, p1-&gt;key);\n        p1 = p1-&gt;next;\n    }\n    while (p2 != NULL)                 // שארית L2\n    {\n        pTail = L_insert(pTail, p2-&gt;key);\n        p2 = p2-&gt;next;\n    }\n    return True;\n}</pre>\n<p><b>שני מצביעים + זנב.</b> זה בדיוק שלב ה-merge של Merge Sort —\nלדעת אותו ביד סוגר גם את משבצת 8 וגם את זו. הטריק היחיד:\n<code>L_insert</code> מחזירה את הצומת החדש — וכך הזנב מתקדם.</p>\n</div></details>"},{"id":"BK-3.8","cat":"רשימות מקושרות","difficulty":2,"skills":["רשימות מקושרות"],"origin":"bank","kind":"open","sourceLabel":"🌐 אינטרנט · 3.8","prompt":"כתוב פונקציה <code>int findMiddle(NODE* head)</code> המחזירה את הערך שנמצא ב<b>אמצע</b> הרשימה המקושרת (במקרה של מספר איברים זוגי — השני מבין שני האמצעיים). <b>מותר מעבר אחד בלבד</b> על הרשימה, ואסור להשתמש במבנה עזר או בספירה מוקדמת של האיברים.","qtype":"code","signature":"int findMiddle(NODE* head)","hint":"טכניקת שני המצביעים: אחד מתקדם צעד אחד בכל סיבוב והשני שני צעדים.","rule":"מעובד ממאגרי תרגול באינטרנט (קלאסיקה) · שני מצביעים","html":"<div class=\"qh\"><b>3.8</b><span class=\"diff diff-e\">קל</span><span class=\"diff srcb\">🌐 אינטרנט</span><span class=\"src\">מעובד ממאגרי תרגול באינטרנט (קלאסיקה) · שני מצביעים</span></div>\n<p>כתוב <code>int findMiddle(NODE* head)</code> שמחזירה את הערך באמצע\nהרשימה (בזוגית — השני מבין השניים), <b>במעבר אחד בלבד</b> על הרשימה.</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<pre class=\"c\">int findMiddle(NODE* head)\n{\n    NODE *slow = head, *fast = head;\n\n    while (fast != NULL &amp;&amp; fast-&gt;next != NULL)\n    {\n        slow = slow-&gt;next;          // צעד אחד\n        fast = fast-&gt;next-&gt;next;    // שני צעדים\n    }\n    return slow-&gt;key;\n}</pre>\n<p><b>איטי/מהיר:</b> כשהמהיר מסיים, האיטי באמצע. אותה משפחה כמו\n<code>FindThirdFromEnd</code> מ-2021 (שם שני מצביעים במרווח קבוע) —\nהמבחן אוהב את המשפחה הזאת כי היא בודקת \"מעבר אחד בלבד\".</p>\n</div></details>"},{"id":"BK-3.9","cat":"רשימות מקושרות","difficulty":3,"skills":["רשימות מקושרות"],"origin":"bank","kind":"open","sourceLabel":"📝 מטלה · 3.9","prompt":"כתוב פונקציה <code>int countSequence(NODE* p, int x)</code> המחזירה כמה <b>רצפים</b> של הערך <span dir=\"ltr\">x</span> יש ברשימה המקושרת (הופעה בודדת נחשבת גם היא רצף). לדוגמה: ברשימה <span dir=\"ltr\">4,22,3,4,5,6,6,3,4,4,4</span> עבור <span dir=\"ltr\">x = 4</span> יוחזר <span dir=\"ltr\">3</span>.","qtype":"code","signature":"int countSequence(NODE* p, int x)","hint":"החזק דגל \"אני כרגע בתוך רצף\" והגדל את המונה רק ברגע הכניסה לרצף חדש.","rule":"שאלה 6 — countSequence","html":"<div class=\"qh\"><b>3.9</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">📝 מטלה HW2</span><span class=\"src\">שאלה 6 — countSequence</span></div>\n<p>מחזירה כמה <b>רצפים</b> של מספר נתון יש ברשימה. לדוגמה:\n‏4,22,3,4,5,6,6,3,4,4,4 עם ‏4 ⟵ מוחזר 3 (רצף בודד = רצף).</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<pre class=\"c\">int countSequence(NODE* p, int x)\n{\n    int cnt = 0, inRun = 0;\n    for (; p != NULL; p = p-&gt;next)\n    {\n        if (p-&gt;key == x){ if (!inRun) cnt++; inRun = 1; }\n        else inRun = 0;\n    }\n    return cnt;\n}</pre>\n<p><b>דגל \"בתוך רצף\":</b> סופרים רק בכניסה לרצף (מעבר 0⟵1). אותה\nתבנית רצפים כמו 2024 ש'1א ואלגוריתם הבלוקים של 2020 — שלישית הופעה!</p>\n</div></details>"},{"id":"BK-3.10","cat":"רשימות מקושרות","difficulty":4,"skills":["רשימות מקושרות"],"origin":"bank","kind":"open","sourceLabel":"📝 מטלה · 3.10","prompt":"נתונות שתי רשימות מקושרות <b>דו-כיווניות</b>, כאשר ב-<span dir=\"ltr\">list1</span> יש מספר זוגי של חוליות. כתוב פונקציה <code>void insertListToMiddle(DLIST* l1, DLIST* l2)</code> המכניסה את כל <span dir=\"ltr\">list2</span> בדיוק באמצע <span dir=\"ltr\">list1</span>. לדוגמה: <span dir=\"ltr\">3,6,4,88</span> ו-<span dir=\"ltr\">10,40,30</span> יתנו <span dir=\"ltr\">3,6,10,40,30,4,88</span>. <b>בלי הקצאת זיכרון</b> — תפירת מצביעים בלבד.","qtype":"code","signature":"void insertListToMiddle(DLIST* l1, DLIST* l2)","hint":"מצא את סוף החצי הראשון בעזרת מצביע איטי ומצביע מהיר, ואז עדכן ארבעה מצביעים — שני <span dir=\"ltr\">next</span> ושני <span dir=\"ltr\">prev</span>.","rule":"שאלה 7 — insertListToMiddle","html":"<div class=\"qh\"><b>3.10</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">📝 מטלה HW2</span><span class=\"src\">שאלה 7 — insertListToMiddle</span></div>\n<p>שתי רשימות <b>דו-כיווניות</b>; ב-list1 מספר זוגי של חוליות. הכנס את\nlist2 באמצע list1: ‏3,6,4,88 + ‏10,40,30 ⟵ ‏3,6,10,40,30,4,88.</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<pre class=\"c\">void insertListToMiddle(DLIST* l1, DLIST* l2)\n{\n    D_NODE *slow = l1-&gt;head.next, *fast = slow;\n    if (!slow || !l2-&gt;head.next) return;\n\n    while (fast-&gt;next &amp;&amp; fast-&gt;next-&gt;next)\n    {   slow = slow-&gt;next;           /* צעד אחד  */\n        fast = fast-&gt;next-&gt;next; }   /* שני צעדים */\n\n    D_NODE *after = slow-&gt;next;          /* החצי השני     */\n    D_NODE *first = l2-&gt;head.next;       /* תחילת list2   */\n    D_NODE *last  = first;\n    while (last-&gt;next) last = last-&gt;next;\n\n    slow-&gt;next = first;  first-&gt;prev = slow;   /* תפירה קדימה */\n    last-&gt;next = after;  after-&gt;prev = last;   /* תפירה אחורה */\n}</pre>\n<p><b>שני שלבים:</b> איטי/מהיר למציאת סוף החצי הראשון, ואז 4 עדכוני\nמצביעים (2 next + ‏2 prev — אל תשכח את ה-prev בדו-כיוונית!).</p>\n</div></details>"},{"id":"BK-3.11","cat":"רשימות מקושרות","difficulty":4,"skills":["רשימות מקושרות"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 3.11","prompt":"כל אחת משתי רשימות מקושרות מייצגת מספר שלם, כאשר <b>ספרת האחדות נמצאת בצומת הראשון</b> (הספרה המשמעותית ביותר בסוף). כתוב פונקציה המשווה בין שני המספרים ומחזירה <span dir=\"ltr\">1</span> אם הראשון גדול, <span dir=\"ltr\">−1</span> אם השני גדול, ו-<span dir=\"ltr\">0</span> אם הם שווים. <b>מעבר אחד בלבד ובלי מבנה עזר</b> (אין לחשב את ערכי המספרים).","qtype":"code","signature":"int compareNumbers(NODE* p1, NODE* p2)","hint":"סרוק את שתי הרשימות במקביל ושמור בכל צעד את תוצאת ההשוואה האחרונה — היא מגיעה מהספרה המשמעותית ביותר. ורשימה ארוכה יותר מייצגת מספר גדול יותר.","rule":"השוואת מספרים כרשימות ספרות","html":"<div class=\"qh\"><b>3.11</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🎓 מבחן 2019 שאלון Y · ש'3 · 20 נק'</span><span class=\"src\">השוואת מספרים כרשימות ספרות</span></div>\n<p>כל רשימה = מספר, ספרת האחדות ראשונה. החזר 1/−1/0 להשוואה.\nמעבר אחד, בלי מבנה עזר.</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<pre class=\"c\">while (p1 &amp;&amp; p2){\n    if (p1-&gt;key &gt; p2-&gt;key) res = 1;\n    else if (p1-&gt;key &lt; p2-&gt;key) res = -1;\n    p1 = p1-&gt;next; p2 = p2-&gt;next; }\nif (p1) return 1;  if (p2) return -1;  return res;</pre>\n<p><b>ההבדל האחרון מנצח</b> — הוא בספרה המשמעותית ביותר.</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d17','')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-3.12","cat":"רשימות מקושרות","difficulty":3,"skills":["רשימות מקושרות"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 3.12","prompt":"נתונה רשימה מקושרת <b>ממוינת</b> העשויה להכיל כפילויות. ממש את הפונקציה <code>void deleteDuplicate(LIST* pLst)</code> שתשאיר כל ערך פעם אחת בלבד (מחיקה בפועל של הצמתים העודפים בעזרת <code>L_delete</code>). במבחן ניתן שלד הקוד ונדרש להשלים שלושה ביטויים חסרים — אתחול המצביע, תנאי הלולאה ופעולת המחיקה.","qtype":"code","signature":"void deleteDuplicate(LIST* pLst)","hint":"אחרי מחיקת כפיל <b>אין</b> לקדם את המצביע — ייתכן שהצומת הבא הוא כפיל נוסף של אותו ערך.","rule":"deleteDuplicate — שלוש השלמות","html":"<div class=\"qh\"><b>3.12</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2020 שאלון X · ש'3 · 15 נק'</span><span class=\"src\">deleteDuplicate — שלוש השלמות</span></div>\n<p>רשימה ממוינת עם כפילויות ⟵ כל ערך פעם אחת. השלם 3 ביטויים.</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p>‏(1) <code>pLst-&gt;head.next</code> · ‏(2) <code>pNode-&gt;next != NULL</code> ·\n‏(3) <code>L_delete(pNode)</code> — ואחרי מחיקה <b>לא מתקדמים</b>\n(אולי עוד כפיל).</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d17','')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-3.13","cat":"רשימות מקושרות","difficulty":3,"skills":["רשימות מקושרות"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 3.13","prompt":"נתונה רשימה מקושרת <span dir=\"ltr\">head → A → B → C</span>. מריצים עליה את קטע הקוד (כ-10 שורות) המשתמש במצביעים <span dir=\"ltr\">prev</span>, <span dir=\"ltr\">current</span> ו-<span dir=\"ltr\">head</span>. עקוב אחרי המצביעים שורה-שורה, <b>צייר את הרשימה המתקבלת</b> בסיום, והסבר במשפט אחד מה עשה הקוד.","qtype":"trace","hint":"צייר את שלושת הצמתים ואת שלושת המצביעים אחרי כל שורה; שים לב לאיזה כיוון פונים החצים בסוף.","rule":"מעקב מצביעים — 10 שורות על 3 צמתים","html":"<div class=\"qh\"><b>3.13</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2021 · ש'4 · 18 נק'</span><span class=\"src\">מעקב מצביעים — 10 שורות על 3 צמתים</span></div>\n<p>‏head→A→B→C; מריצים את קטע ה-prev/current/head. צייר את התוצאה +\n\"מה עשתה הפונקציה במשפט אחד?\"</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p>התוצאה: ‏head→C→B→A — <b>\"הפכה את הרשימה\"</b>. זה גוף לולאת ההיפוך\nפרום ידנית. אנימציה מלאה בפרק פתרונות המבחנים!</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d03','')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-3.14","cat":"רשימות מקושרות","difficulty":4,"skills":["רשימות מקושרות"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 3.14","prompt":"כתוב פונקציה <code>void moveDoubleDigitsNumToStart(LIST* pLst)</code> המעבירה את כל המספרים ה<b>דו-ספרתיים</b> (בין 10 ל-99) לתחילת הרשימה המקושרת. הסדר הפנימי אינו חשוב, ויש להשתמש ב-<code>L_insert</code> ו-<code>L_delete</code> בלבד — <b>בלי מבנה עזר</b>. לדוגמה: <span dir=\"ltr\">30,1,40,5,3,7,600,70</span> יכולה להפוך ל-<span dir=\"ltr\">70,40,30,1,5,3,7,600</span>.","qtype":"code","signature":"void moveDoubleDigitsNumToStart(LIST* pLst)","hint":"סרוק עם מצביע ל<b>קודם</b>; כשמצאת דו-ספרתי — הכנס לראש ומחק את המקור, ואל תקדם את המצביע באותה איטרציה.","rule":"moveDoubleDigitsNumToStart","html":"<div class=\"qh\"><b>3.14</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🎓 מבחן 2023 · ש'6 · 18 נק'</span><span class=\"src\">moveDoubleDigitsNumToStart</span></div>\n<p>הזז את כל הדו-ספרתיים לתחילת הרשימה (סדר פנימי לא חשוב), עם\n‏L_insert/L_delete. ‏30,1,40,5,3,7,600,70 ⟵ ‏70,40,30,1,5,3,7,600.</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p>הרעיון: סריקה עם pPrev; דו-ספרתי (<code>10 &lt;= x &lt;= 99</code>) ⟵ ‏L_insert לראש +\n‏L_delete(pPrev), ו<b>לא</b> מקדמים את pPrev.</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d03','sol-2023-6')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-3.15","cat":"רשימות מקושרות","difficulty":3,"skills":["רשימות מקושרות"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 3.15","prompt":"נתון קטע הקוד <code>listQuestion</code> המבצע רצף פעולות של הכנסה, חיפוש ומחיקה על רשימה מקושרת (כולל שימוש ב-<span dir=\"ltr\">pN-&gt;next-&gt;next</span> ובפונקציה <span dir=\"ltr\">L_delete</span>). עקוב אחרי הקוד: האם תתרחש שגיאת ריצה (\"תעופה\")? אם כן — הסבר היכן ומדוע; אם לא — רשום במדויק מה יודפס.","qtype":"trace","hint":"זכור את המוסכמה של הקורס: <span dir=\"ltr\">L_delete(pN)</span> מוחקת את הצומת <b>שאחרי</b> <span dir=\"ltr\">pN</span>, לא את <span dir=\"ltr\">pN</span> עצמו.","rule":"מעקב listQuestion — האם תעופה?","html":"<div class=\"qh\"><b>3.15</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2024 · ש'3 · 12 נק'</span><span class=\"src\">מעקב listQuestion — האם תעופה?</span></div>\n<p>רצף insert/find/delete על רשימה (עם <code>pN-&gt;next-&gt;next</code>\nו-L_delete). תעופה? ואם לא — מה הפלט?</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p><b>אין תעופה.</b> הפלט: <code>14, 11, 19, 17</code> —\n‏L_delete(pN) מחקה את <b>12</b> (הבא אחרי 19), לא את 19!</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d17','')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-3.16","cat":"רשימות מקושרות","difficulty":4,"skills":["רשימות מקושרות"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 3.16","prompt":"נתונה רשימה מקושרת <b>דו-כיוונית</b>. כתוב פונקציה המעבירה את <span dir=\"ltr\">n</span> האיברים האחרונים אל ראש הרשימה, תוך שמירה על סדרם. לדוגמה עבור <span dir=\"ltr\">n = 2</span>: <span dir=\"ltr\">5,2,1,8,−3,22</span> יהפוך ל-<span dir=\"ltr\">−3,22,5,2,1,8</span>. <b>אסור להקצות או לשחרר זיכרון</b> — הזזת מצביעים בלבד.","qtype":"code","signature":"void moveCircular(DLIST* pLst, int n)","hint":"נצל את מצביעי ה-<span dir=\"ltr\">prev</span> של הרשימה הדו-כיוונית כדי לספור <span dir=\"ltr\">n−1</span> צעדים אחורה מהסוף, ואז נתק וחבר מחדש.","rule":"moveCircular — דו-כיוונית בלי הקצאה","html":"<div class=\"qh\"><b>3.16</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🎓 מבחן 2025 · ש'3 · 14 נק'</span><span class=\"src\">moveCircular — דו-כיוונית בלי הקצאה</span></div>\n<p>העבר את n האיברים האחרונים לראש הרשימה, בלי הקצאת זיכרון.\n‏n=2: ‏5,2,1,8,−3,22 ⟵ ‏−3,22,5,2,1,8.</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p>4 שלבים: מצא סוף ⟵ ספור אחורה n−1 עם prev (יתרון הדו-כיוונית!) ⟵\nנתק ⟵ חבר לפני הראש הישן + עדכן head.</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d03','sol-2025-3')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-4.1","cat":"עצים ו-BST","difficulty":2,"skills":["עצים ו-BST"],"origin":"bank","kind":"open","sourceLabel":"🤖 קלוד · 4.1","prompt":"כתוב פונקציה <b>רקורסיבית</b> <code>int countSingle(NODE2* p)</code> המחזירה את מספר הצמתים בעץ בינארי שיש להם <b>בן אחד בדיוק</b> (כלומר לא עלים ולא צמתים בעלי שני בנים). מהי סיבוכיות הפתרון?","qtype":"code","signature":"int countSingle(NODE2* p)","hint":"התבנית: תרומת הצומת הנוכחי (0 או 1) ועוד הרקורסיה על שני תת-העצים; \"בדיוק אחד קיים\" זהו XOR בין שתי הבדיקות.","rule":"ספירה עם תנאי מבני","html":"<div class=\"qh\"><b>4.1</b><span class=\"diff diff-e\">קל</span><span class=\"diff srcb\">🤖 קלוד</span><span class=\"src\">ספירה עם תנאי מבני</span></div>\n<p>כתוב <code>int countSingle(NODE2* p)</code> שמחזירה כמה צמתים בעץ\nיש להם <b>בן אחד בדיוק</b>.</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<pre class=\"c\">int countSingle(NODE2* p)\n{\n    if (!p) return 0;\n\n    int me = (p-&gt;left == NULL) != (p-&gt;right == NULL);\n\n    return me + countSingle(p-&gt;left) + countSingle(p-&gt;right);\n}</pre>\n<p><code>!=</code> על שני תנאים = XOR: בדיוק אחד מהבנים חסר.\nאפשר גם לכתוב את זה עם שני if — העיקר שעלה (0 בנים) וצומת מלא (2 בנים)\nלא נספרים.</p>\n</div></details>"},{"id":"BK-4.2","cat":"עצים ו-BST","difficulty":3,"skills":["עצים ו-BST"],"origin":"bank","kind":"open","sourceLabel":"🤖 קלוד · 4.2","prompt":"כתוב פונקציה <b>רקורסיבית</b> <code>int sumAtDepth(NODE2* p, int k)</code> המחזירה את סכום הערכים של כל הצמתים הנמצאים בעומק <span dir=\"ltr\">k</span> בדיוק בעץ בינארי (השורש נמצא בעומק 0).","qtype":"code","signature":"int sumAtDepth(NODE2* p, int k)","hint":"במקום לעקוב אחרי העומק הנוכחי — הקטן את <span dir=\"ltr\">k</span> באחד בכל ירידה, ועצור כשהוא מתאפס.","rule":"פרמטר נוסף שיורד עם העומק","html":"<div class=\"qh\"><b>4.2</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🤖 קלוד</span><span class=\"src\">פרמטר נוסף שיורד עם העומק</span></div>\n<p>כתוב <code>int sumAtDepth(NODE2* p, int k)</code> שמחזירה את סכום\nהערכים בעומק k בדיוק (השורש בעומק 0).</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<pre class=\"c\">int sumAtDepth(NODE2* p, int k)\n{\n    if (!p) return 0;\n    if (k == 0) return p-&gt;key;\n\n    return sumAtDepth(p-&gt;left,  k - 1) +\n           sumAtDepth(p-&gt;right, k - 1);\n}</pre>\n<p><b>התבנית:</b> במקום \"לרדת בעץ\" — <b>מקטינים את k</b>. כשהוא מתאפס,\nהגענו לעומק המבוקש.</p>\n</div></details>"},{"id":"BK-4.3","cat":"עצים ו-BST","difficulty":2,"skills":["עצים ו-BST"],"origin":"bank","kind":"open","sourceLabel":"🤖 קלוד · 4.3","prompt":"כתוב פונקציה <b>רקורסיבית</b> <code>void mirror(NODE2* p)</code> ההופכת עץ בינארי לתמונת הראי שלו — כלומר מחליפה בין הבן השמאלי לבן הימני בכל צומת בעץ. בנוסף, הסבר בעד 8 מילים מה קורה לפלט של סיור <span dir=\"ltr\">InOrder</span> על העץ אחרי הפעולה.","qtype":"code","signature":"void mirror(NODE2* p)","hint":"החלף את שני המצביעים בצומת הנוכחי בעזרת משתנה עזר, ורק אחר כך המשך ברקורסיה לשני תת-העצים.","rule":"שינוי העץ + \"8 מילים\"","html":"<div class=\"qh\"><b>4.3</b><span class=\"diff diff-e\">קל</span><span class=\"diff srcb\">🤖 קלוד</span><span class=\"src\">שינוי העץ + \"8 מילים\"</span></div>\n<p>כתוב <code>void mirror(NODE2* p)</code> שהופכת את העץ לתמונת ראי\n(מחליפה שמאל וימין בכל צומת). והסבר ב-≤8 מילים מה קורה לסיור InOrder\nאחרי הפעולה.</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<pre class=\"c\">void mirror(NODE2* p)\n{\n    if (!p) return;\n\n    NODE2* tmp = p-&gt;left;\n    p-&gt;left  = p-&gt;right;\n    p-&gt;right = tmp;\n\n    mirror(p-&gt;left);\n    mirror(p-&gt;right);\n}</pre>\n<p><b>ב-8 מילים:</b> \"סיור InOrder יחזיר את הערכים בסדר הפוך\".</p>\n</div></details>"},{"id":"BK-4.4","cat":"עצים ו-BST","difficulty":4,"skills":["עצים ו-BST"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 4.4","prompt":"נתונים שלושה עצים בינאריים <span dir=\"ltr\">A</span>, <span dir=\"ltr\">B</span> ו-<span dir=\"ltr\">C</span>, כל אחד מכיל את המספרים <span dir=\"ltr\">{1…n}</span> ללא חזרות. ידוע שסיור <span dir=\"ltr\">InOrder</span> על <span dir=\"ltr\">A</span>, סיור <span dir=\"ltr\">PostOrder</span> על <span dir=\"ltr\">B</span> וסיור <span dir=\"ltr\">PreOrder</span> על <span dir=\"ltr\">C</span> — כולם הדפיסו את <span dir=\"ltr\">1, 2, …, n</span> בסדר עולה. קבע לגבי כל טענה אם היא <b>נכונה</b> או <b>לא נכונה</b> ונמק (או הבא דוגמה נגדית): (א) <span dir=\"ltr\">A</span> בהכרח עץ חיפוש בינארי; (ב) ייתכן ש-<span dir=\"ltr\">A</span> אינו עץ חיפוש; (ג) <span dir=\"ltr\">B</span> בהכרח עץ חיפוש; (ד) ייתכן ש-<span dir=\"ltr\">C</span> הוא עץ חיפוש; (ה) סיור <span dir=\"ltr\">InOrder</span> על <span dir=\"ltr\">B</span> וסיור <span dir=\"ltr\">PostOrder</span> על <span dir=\"ltr\">C</span> ייתנו בהכרח אותו פלט; (ו) ייתכן שגם סיור <span dir=\"ltr\">PreOrder</span> על <span dir=\"ltr\">A</span> ייתן פלט ממוין.","qtype":"analysis","hint":"לכל טענה נסה את שני המקרים הקיצוניים — שרשרת שמאלית טהורה ושרשרת ימנית טהורה; רובן נופלות או מוכחות על אחד מהם.","rule":"מבחן 2018 שאלון A · שאלה 5 · 18 נק'","html":"<div class=\"qh\"><b>4.4</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🎓 מבחן עבר</span><span class=\"src\"><span class=\"tag exam\">מבחן 2018 שאלון A · שאלה 5 · 18 נק'</span> · נכון/לא נכון</span></div>\n<p>שלושה עצים בינאריים A, B, C, כל אחד מכיל את {1…n} ללא חזרות.\nסיור InOrder על A, סיור PostOrder על B וסיור PreOrder על C —\n<b>כולם</b> הדפיסו {1, 2, …, n} בסדר עולה. נכון או לא נכון:</p>\n<details class=\"sol\"><summary>התשובות הרשמיות + למה</summary><div class=\"body\">\n<div class=\"tw\"><table>\n<thead><tr><th>טענה</th><th class=\"c\">תשובה</th><th>למה</th></tr></thead>\n<tbody>\n<tr><td>א. A בהכרח עץ חיפוש</td><td class=\"c\"><b>נכון</b></td>\n<td>InOrder ממוין ⇔ BST — זו ההגדרה השקולה</td></tr>\n<tr><td>ב. ייתכן ש-A אינו עץ חיפוש</td><td class=\"c\"><b>לא נכון</b></td>\n<td>היפוך של א'</td></tr>\n<tr><td>ג. B בהכרח עץ חיפוש</td><td class=\"c\"><b>לא נכון</b></td>\n<td>PostOrder ממוין כופה צורה של \"שרשרת\" (כל צומת גדול מכל תת-העץ שלו) —\nלמשל שרשרת שמאלית טהורה: היא כן BST, אבל אפשר לבנות גם עץ שאינו BST.\nדוגמה: שורש 3, בן שמאלי 2, ולו בן ימני 1 — PostOrder: 1,2,3 ממוין,\nאבל 1 בתת-עץ של 2 בצד הלא-נכון → לא BST</td></tr>\n<tr><td>ד. ייתכן ש-C הוא עץ חיפוש</td><td class=\"c\"><b>נכון</b></td>\n<td>שרשרת ימנית טהורה 1→2→…→n: ‏PreOrder ממוין וגם BST</td></tr>\n<tr><td>ה. InOrder על B ו-PostOrder על C יתנו בהכרח אותו פלט</td>\n<td class=\"c\"><b>לא נכון</b></td>\n<td>הצורות של B ו-C לא נקבעות ביחידות — אין שום התחייבות</td></tr>\n<tr><td>ו. ייתכן ש-PreOrder על A ייתן גם הוא פלט ממוין</td>\n<td class=\"c\"><b>נכון</b></td>\n<td>שרשרת ימנית: גם InOrder וגם PreOrder ממוינים</td></tr>\n</tbody></table></div>\n<div class=\"tip\" style=\"margin-bottom:0\"><b>הכלי לכל השאלות האלה:</b>\nחשוב על שני הקיצונים — שרשרת שמאלית ושרשרת ימנית. רוב הטענות נופלות\nאו מוכחות באחד משניהם.</div>\n</div></details>"},{"id":"BK-4.5","cat":"עצים ו-BST","difficulty":3,"skills":["עצים ו-BST"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 4.5","prompt":"עץ בינארי נקרא <b>\"סימטרי\"</b> (מאוזן-גבהים) אם בכל צומת בעץ הפרש הגבהים בין תת-העץ השמאלי לתת-העץ הימני קטן או שווה ל-1. כתוב פונקציה <code>BOOL CheckSymetric(NODE2* v)</code> הבודקת אם עץ נתון סימטרי. מותר להשתמש בפונקציות עזר, <b>אסור להשתמש במבני עזר</b>.","qtype":"code","signature":"BOOL CheckSymetric(NODE2* v)","hint":"כתוב תחילה פונקציית עזר לחישוב גובה, וזכור שתנאי האיזון חייב להתקיים ב<b>כל</b> צומת ולא רק בשורש.","rule":"מבחן 2018 שאלון B · שאלה 6 · 18 נק'","html":"<div class=\"qh\"><b>4.5</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן עבר</span><span class=\"src\"><span class=\"tag exam\">מבחן 2018 שאלון B · שאלה 6 · 18 נק'</span> · עם פונקציית עזר</span></div>\n<p>\"עץ סימטרי\" (מאוזן-גבהים): בכל צומת, הפרש הגבהים בין תת-העץ השמאלי\nלימני ≤ 1. כתוב פונקציה שבודקת אם עץ נתון סימטרי. מותר פונקציות עזר,\nאסור מבני עזר.</p>\n<details class=\"sol\"><summary>הפתרון הרשמי</summary><div class=\"body\">\n<pre class=\"c\">int Height(NODE2 *v)\n{\n    int left, right;\n    if (v == NULL)\n        return -1;\n    left  = 1 + Height(v-&gt;left);\n    right = 1 + Height(v-&gt;right);\n    return left &gt; right ? left : right;\n}\n\nBOOL CheckSymetric(NODE2 *v)\n{\n    if (!v)\n        return True;\n    return CheckSymetric(v-&gt;left) &amp;&amp;\n           CheckSymetric(v-&gt;right) &amp;&amp;\n           abs(Height(v-&gt;left) - Height(v-&gt;right)) &lt;= 1;\n}</pre>\n<p><b>שים לב:</b> זו בדיוק בדיקת תנאי-האיזון של AVL (בלי תכונת ה-BST).\nהתנאי חייב להיבדק <b>בכל צומת</b>, לא רק בשורש — לכן שתי הקריאות\nהרקורסיביות בנוסף לבדיקת הגובה.</p>\n</div></details>"},{"id":"BK-4.6","cat":"עצים ו-BST","difficulty":3,"skills":["עצים ו-BST"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 4.6","prompt":"בעץ חיפוש בינארי מאוחסנים המספרים <span dir=\"ltr\">1…1000</span>, ומחפשים בו את הערך <b><span dir=\"ltr\">363</span></b>. עבור כל אחת מחמש הסדרות שלמטה, קבע האם היא יכולה להיות סדרת הצמתים שנבחנו במהלך החיפוש. אם לא — ציין מיהו המספר <b>הראשון</b> בסדרה שמהווה בעיה, והסבר מדוע.","qtype":"analysis","hint":"החזק חלון <span dir=\"ltr\">(min, max)</span> של הערכים האפשריים ועדכן אותו בכל צעד: ירידה שמאלה מקטינה את ה-<span dir=\"ltr\">max</span>, ירידה ימינה מגדילה את ה-<span dir=\"ltr\">min</span>.","rule":"מבחן 2019 שאלון Y · שאלה 2 · 20 נק'","html":"<div class=\"qh\"><b>4.6</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן עבר</span><span class=\"src\"><span class=\"tag exam\">מבחן 2019 שאלון Y · שאלה 2 · 20 נק'</span> · מסלולי חיפוש</span></div>\n<p>ב-BST מאוחסנים 1…1000 ומחפשים את <b>363</b>. עבור כל סדרה — האם היא\nיכולה להיות סדרת הצמתים שנבחנו? אם לא, מי המספר הראשון שמהווה בעיה?</p>\n<pre>1. 2, 252, 401, 398, 330, 344, 397, 363\n2. 924, 220, 911, 244, 898, 258, 362, 363\n3. 925, 202, 911, 240, 912, 245, 363\n4. 2, 399, 387, 219, 266, 382, 381, 278, 363\n5. 935, 278, 347, 621, 299, 392, 358, 363</pre>\n<details class=\"sol\"><summary>התשובות הרשמיות + השיטה</summary><div class=\"body\">\n<p><b>השיטה:</b> תוך כדי מעבר על הסדרה מחזיקים חלון (min, max). ירידה\nשמאלה (המספר גדול מ-363) מעדכנת max; ירידה ימינה מעדכנת min. מספר\nשיוצא מהחלון — פסול.</p>\n<ol>\n<li><b>נכון</b> — כל צעד מכווץ את החלון כדין.</li>\n<li><b>נכון</b> — זיגזג חוקי: ‏924↓, 220↑, 911↓… כל מספר בתוך החלון.</li>\n<li><b>לא נכון — 912.</b> אחרי 911 (ירידה שמאלה, max=911) מגיע 912\nשגדול מ-911 — מחוץ לחלון.</li>\n<li><b>נכון.</b></li>\n<li><b>לא נכון — 299.</b> אחרי 347 (ירדנו שמאלה מ-347? לא: <code>347 &lt; 363</code> →\nימינה, min=347) מגיע 621 (↓, max=621) ואז 299 — קטן מ-min=347. פסול.</li>\n</ol>\n<div class=\"tip\" style=\"margin-bottom:0\">אותה שאלה בדיוק חזרה ב-2020 ש'1ו\nוב-2021 Y ש'4 — שלוש הופעות. שיטת החלון פותרת את כולן ב-30 שניות.</div>\n</div></details>"},{"id":"BK-4.7","cat":"עצים ו-BST","difficulty":3,"skills":["עצים ו-BST"],"origin":"bank","kind":"open","sourceLabel":"🌐 אינטרנט · 4.7","prompt":"כתוב פונקציה <code>NODE2* firstCommon(NODE2* root, int a, int b)</code> המקבלת שורש של <b>עץ חיפוש בינארי</b> ושני ערכים <span dir=\"ltr\">a</span> ו-<span dir=\"ltr\">b</span> הקיימים בעץ, ומחזירה את הצומת המשותף הראשון בדרך מהשורש אל <span dir=\"ltr\">a</span> ואל <span dir=\"ltr\">b</span> (האב הקדמון המשותף הנמוך ביותר). <b>בלי מבני עזר</b>. מהי הסיבוכיות?","qtype":"code","signature":"NODE2* firstCommon(NODE2* root, int a, int b)","hint":"כל עוד שני הערכים נמצאים באותו צד ביחס לצומת הנוכחי — המשך לרדת; ברגע שהם מתפצלים, הגעת לתשובה.","rule":"מעובד ממאגרי תרגול באינטרנט (קלאסיקה) · LCA","html":"<div class=\"qh\"><b>4.7</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🌐 אינטרנט</span><span class=\"src\">מעובד ממאגרי תרגול באינטרנט (קלאסיקה) · LCA</span></div>\n<p>כתוב <code>NODE2* firstCommon(NODE2* root, int a, int b)</code>\nשמחזירה את הצומת המשותף הראשון בדרך משורש ה-BST אל a ואל b\n(האב הקדמון המשותף הנמוך ביותר). נתון ששניהם קיימים בעץ.</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<pre class=\"c\">NODE2* firstCommon(NODE2* root, int a, int b)\n{\n    if (a &lt; root-&gt;key &amp;&amp; b &lt; root-&gt;key)\n        return firstCommon(root-&gt;left, a, b);\n    if (a &gt; root-&gt;key &amp;&amp; b &gt; root-&gt;key)\n        return firstCommon(root-&gt;right, a, b);\n    return root;      // התפצלו (או אחד מהם הוא הצומת) — זה המשותף\n}</pre>\n<p><b>הרעיון:</b> כל עוד שניהם באותו צד — יורדים. ברגע שהם מתפצלים\n(או שפגשנו אחד מהם) — זה הצומת. O(h), בלי מבני עזר.</p>\n</div></details>"},{"id":"BK-4.8","cat":"עצים ו-BST","difficulty":2,"skills":["עצים ו-BST"],"origin":"bank","kind":"open","sourceLabel":"🧪 מעבדה · 4.8","prompt":"כתוב פונקציה <b>רקורסיבית</b> <code>BOOL isValueInTree(NODE2* p, int val)</code> הבודקת אם הערך <span dir=\"ltr\">val</span> קיים בעץ בינארי <b>כללי</b> (שאינו עץ חיפוש!). מהי סיבוכיות זמן הריצה, ובמה היא שונה מהחיפוש ב-BST?","qtype":"code","signature":"BOOL isValueInTree(NODE2* p, int val)","hint":"בעץ כללי אין מידע שמכוון לצד אחד — לכן חייבים לחפש בשני תת-העצים ולאחד את התוצאות ב-<span dir=\"ltr\">||</span>.","rule":"מעבדת העצים — isValueInTree","html":"<div class=\"qh\"><b>4.8</b><span class=\"diff diff-e\">קל</span><span class=\"diff srcb\">🧪 מעבדה</span><span class=\"src\">מעבדת העצים — isValueInTree</span></div>\n<p>בדוק אם ערך קיים בעץ בינארי <b>כללי</b> (לא BST!).</p>\n<details class=\"sol\"><summary>הפתרון מהמעבדה</summary><div class=\"body\">\n<pre class=\"c\">BOOL isValueInTree(NODE2* p, int val)\n{\n    if (p == NULL) return False;\n    if (p-&gt;key == val) return True;\n    return isValueInTree(p-&gt;left,  val) ||\n           isValueInTree(p-&gt;right, val);\n}</pre>\n<p>בעץ כללי חייבים לבדוק את <b>שני</b> הצדדים — O(n). ההשוואה ל-BST\n(שם יורדים צד אחד, O(h)) היא בדיוק ההבדל שנבחן.</p>\n</div></details>"},{"id":"BK-4.9","cat":"עצים ו-BST","difficulty":3,"skills":["עצים ו-BST"],"origin":"bank","kind":"open","sourceLabel":"🧪 מעבדה · 4.9","prompt":"כתוב פונקציה <b>רקורסיבית</b> <code>int maxTree(NODE2* p)</code> המחזירה את הערך המקסימלי בעץ בינארי <b>כללי</b> (שאינו עץ חיפוש). הקפד לבחור ערך החזרה נכון עבור תנאי העצירה.","qtype":"code","signature":"int maxTree(NODE2* p)","hint":"ערך העצירה של עץ ריק חייב להיות \"ניטרלי\" לפעולה — עבור מקסימום זהו <span dir=\"ltr\">INT_MIN</span>.","rule":"מעבדת העצים — maxTree","html":"<div class=\"qh\"><b>4.9</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🧪 מעבדה</span><span class=\"src\">מעבדת העצים — maxTree</span></div>\n<p>החזר את הערך המקסימלי בעץ בינארי <b>כללי</b>.</p>\n<details class=\"sol\"><summary>הפתרון מהמעבדה</summary><div class=\"body\">\n<pre class=\"c\">int maxTree(NODE2* p)\n{\n    if (p == NULL) return INT_MIN;   /* ניטרלי למקסימום */\n    int l = maxTree(p-&gt;left);\n    int r = maxTree(p-&gt;right);\n    int m = l &gt; r ? l : r;\n    return p-&gt;key &gt; m ? p-&gt;key : m;\n}</pre>\n<p><b>הנקודה:</b> ערך העצירה חייב להיות \"ניטרלי\" — ‏INT_MIN למקסימום,\n‏INT_MAX למינימום, ‏0 לסכום, ‏1 למכפלה. טעות בערך העצירה = טעות בכל\nהעץ.</p>\n</div></details>"},{"id":"BK-4.10","cat":"עצים ו-BST","difficulty":3,"skills":["עצים ו-BST"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 4.10","prompt":"קבע אם הטענה הבאה נכונה או לא נכונה, ונמק (בדוגמה נגדית אם צריך): \"בעץ חיפוש בינארי, מחיקת הצומת <span dir=\"ltr\">x</span> ואחריה מחיקת הצומת <span dir=\"ltr\">y</span> תמיד תיתן את אותו עץ כמו מחיקת <span dir=\"ltr\">y</span> ואחריה מחיקת <span dir=\"ltr\">x</span>.\"","qtype":"analysis","hint":"חשוב על מחיקת צומת בעל שני בנים — במה היא מחליפה אותו, והאם מחיקה קודמת יכולה לשנות מי זה?","rule":"האם סדר מחיקות ב-BST משנה?","html":"<div class=\"qh\"><b>4.10</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2020 שאלון X · ש'1ד · 5 נק'</span><span class=\"src\">האם סדר מחיקות ב-BST משנה?</span></div>\n<p>הטענה: מחיקת x ואז y = מחיקת y ואז x, תמיד. נכון?</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p><b>לא נכון.</b> מחיקת צומת עם 2 בנים מחליפה עם <b>העוקב</b> — ומחיקה\nקודמת יכולה לשנות מי העוקב ⟵ הסדר משנה את צורת העץ.</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d17','')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-4.11","cat":"עצים ו-BST","difficulty":2,"skills":["עצים ו-BST"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 4.11","prompt":"בעץ חיפוש בינארי מאוחסנים המספרים <span dir=\"ltr\">1–400</span>, ומחפשים בו את <span dir=\"ltr\">158</span>. האם הסדרה <span dir=\"ltr\">100, 300, 190, 130, 200, 150, 178</span> יכולה להיות סדרת הצמתים שנבחנו במהלך החיפוש? אם לא — ציין את המספר הראשון שמהווה בעיה ונמק.","qtype":"analysis","hint":"עקוב אחרי חלון הערכים האפשריים <span dir=\"ltr\">(min, max)</span> ובדוק בכל צעד אם המספר הבא נמצא בתוכו.","rule":"מסלול חיפוש ל-158 — תקין?","html":"<div class=\"qh\"><b>4.11</b><span class=\"diff diff-e\">קל</span><span class=\"diff srcb\">🎓 מבחן 2020 שאלון X · ש'1ו · 5 נק'</span><span class=\"src\">מסלול חיפוש ל-158 — תקין?</span></div>\n<p>‏BST עם 1–400, מחפשים 158:\n<code>100, 300, 190, 130, 200, 150, 178</code></p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p><b>לא.</b> שיטת החלון: אחרי 190 (שמאלה) החלון (130,190) —\n‏200 מחוץ לחלון ⟵ פסול.</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d17','')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-4.12","cat":"עצים ו-BST","difficulty":3,"skills":["עצים ו-BST"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 4.12","prompt":"נתונים סיור <span dir=\"ltr\">PreOrder</span> וסיור <span dir=\"ltr\">InOrder</span> של עץ בינארי (ראה למטה). שחזר את העץ וכתוב את סיור ה-<span dir=\"ltr\">PostOrder</span> שלו. הסבר את שיטת השחזור.","qtype":"trace","hint":"האיבר הראשון ב-<span dir=\"ltr\">PreOrder</span> הוא השורש; מצא אותו ב-<span dir=\"ltr\">InOrder</span> כדי לפצל לתת-עץ שמאלי וימני, וחזור על התהליך רקורסיבית.","rule":"שחזור עץ מ-Pre+In + כתיבת Post","html":"<div class=\"qh\"><b>4.12</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2020 שאלון X · ש'2 · 10 נק'</span><span class=\"src\">שחזור עץ מ-Pre+In + כתיבת Post</span></div>\n<pre>Pre: 88,52,82,36,87,72,11,86,32,27,56\nIn:  82,52,36,88,11,86,32,72,27,56,87</pre>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p>‏Post-Order: <b>82,36,52,32,86,11,56,27,72,87,88</b>.\nהשיטה: ראשון ב-Pre = שורש; פיצול ב-In; רקורסיה.</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d04','sol-tree-rebuild')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-4.13","cat":"עצים ו-BST","difficulty":2,"skills":["עצים ו-BST"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 4.13","prompt":"כתוב פונקציה <code>void PrintEvens(tnode* root)</code> המדפיסה את כל הערכים ה<b>זוגיים</b> שבעץ חיפוש בינארי, מהקטן לגדול.","qtype":"code","signature":"void PrintEvens(tnode* root)","hint":"בעץ חיפוש, \"בסדר עולה\" פירושו סיור אחד מסוים — הוסף לו רק תנאי לפני ההדפסה.","rule":"PrintEvens — זוגיים בסדר עולה","html":"<div class=\"qh\"><b>4.13</b><span class=\"diff diff-e\">קל</span><span class=\"diff srcb\">🎓 מבחן 2021 · ש'5 · 18 נק'</span><span class=\"src\">PrintEvens — זוגיים בסדר עולה</span></div>\n<p>הדפס את כל הערכים הזוגיים ב-BST מהקטן לגדול.</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<pre class=\"c\">void PrintEvens(tnode* root){\n    if (root != NULL){\n        PrintEvens(root-&gt;left);\n        if (root-&gt;num % 2 == 0) printf(\"%d \", root-&gt;num);\n        PrintEvens(root-&gt;right); } }</pre>\n<p>\"בסדר עולה\" על BST = <b>InOrder</b> + תנאי. ‏18 נק' על 7 שורות.</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d04','')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-4.14","cat":"עצים ו-BST","difficulty":3,"skills":["עצים ו-BST"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 4.14","prompt":"נתון סיור <span dir=\"ltr\">PreOrder</span> של <b>עץ חיפוש בינארי</b>: <span dir=\"ltr\">100, 70, 60, 50, 80, 120, 110, 130, 140</span>. שחזר וצייר את העץ, והסבר כיצד ווידאת שהשחזור נכון.","qtype":"trace","hint":"הכנס את הערכים לעץ לפי סדר הופעתם, כשכל ערך יורד שמאלה אם הוא קטן וימינה אם הוא גדול; בסוף בדוק שסיור <span dir=\"ltr\">InOrder</span> יוצא ממוין.","rule":"שחזור BST מ-PreOrder","html":"<div class=\"qh\"><b>4.14</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2023 · ש'5א · 10 נק'</span><span class=\"src\">שחזור BST מ-PreOrder</span></div>\n<pre>Pre: 100, 70, 60, 50, 80, 120, 110, 130, 140</pre><p>צייר את העץ.</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p>מכניסים לפי הסדר (כל ערך יורד קטן⟵שמאלה, גדול⟵ימינה):\n‏100 שורש; ‏70(שמ)⟵60⟵50, ‏80 ימני של 70; ‏120(ימ)⟵110, ‏130⟵140.\nבדיקה: InOrder עולה ✔.</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d04','sol-tree-rebuild')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-4.15","cat":"עצים ו-BST","difficulty":4,"skills":["עצים ו-BST"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 4.15","prompt":"נתון עץ חיפוש בינארי כפי שהוא נראה <b>אחרי</b> שנמחק ממנו הצומת <span dir=\"ltr\">90</span> (ראה ציור למטה). שחזר עץ אפשרי אחד שהיה קיים <b>לפני</b> המחיקה, והסבר את השיקולים. שים לב: ייתכנו כמה תשובות נכונות — ציין את משפחות התשובות האפשריות.","qtype":"trace","hint":"חשוב הפוך על אלגוריתם המחיקה: או ש-90 היה עלה, או שהיה בעל שני בנים והוחלף בעוקב שלו — בטל את ההחלפה.","rule":"השאלה ההפוכה — העץ שלפני המחיקה","html":"<div class=\"qh\"><b>4.15</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🎓 מבחן 2024 · ש'4 · 12 נק'</span><span class=\"src\">השאלה ההפוכה — העץ שלפני המחיקה</span></div>\n<p>נתון עץ אחרי <b>מחיקת 90</b> — שחזר עץ אפשרי שהיה לפני. (יש יותר\nמתשובה נכונה אחת!)</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p>שתי משפחות תשובות: ‏90 היה עלה שנתלה במקום המתאים, או ‏90 הוחלף\nבעוקב — הפוך את החלפת-העוקב. פירוט מלא עם שתי התשובות הקבילות — בדק העצים.</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d04','sol-2024-4')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-4.16","cat":"עצים ו-BST","difficulty":3,"skills":["עצים ו-BST"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 4.16","prompt":"עץ בינארי נקרא <b>\"עץ פירוק לגורמים\"</b> אם לכל צומת פנימי בו יש בדיוק שני בנים, ומכפלת הערכים של שני האחים שווה לערך האב. ממש פונקציה רקורסיבית הבודקת אם עץ נתון הוא עץ פירוק לגורמים (עלים ועץ ריק מקיימים את התנאי באופן ריק).","qtype":"code","signature":"BOOL isGoremTree(NODE2* p)","hint":"הפרד בין שלושה מקרים: עץ ריק, עלה, וצומת עם בן אחד בלבד (שפוסל מיד) — ורק אז בדוק את תנאי המכפלה והמשך ברקורסיה.","rule":"isGoremTree — עץ פירוק לגורמים","html":"<div class=\"qh\"><b>4.16</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2025 · ש'4 · 12 נק'</span><span class=\"src\">isGoremTree — עץ פירוק לגורמים</span></div>\n<p>לכל צומת פנימי שני בנים, ומכפלת האחים = ערך האב. ממש בדיקה.</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<pre class=\"c\">if (!p) return True;\nif (!p-&gt;l &amp;&amp; !p-&gt;r) return True;\nif (!p-&gt;l || !p-&gt;r) return False;\nif (p-&gt;l-&gt;key * p-&gt;r-&gt;key != p-&gt;key) return False;\nreturn rec(p-&gt;l) &amp;&amp; rec(p-&gt;r);</pre>\n<p><a class=\"golink\" onclick=\"jumpSol('d17','')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-5.1","cat":"מחסנית ותור","difficulty":3,"skills":["מחסנית ותור"],"origin":"bank","kind":"open","sourceLabel":"🤖 קלוד · 5.1","prompt":"התור <span dir=\"ltr\">q</span> מכיל (מהראש לזנב) את הערכים <span dir=\"ltr\">3, 7, 1</span>. עבור הפונקציה הרקורסיבית שלמטה: מה יוחזר מהקריאה <span dir=\"ltr\">what(q)</span>? כיצד ייראה התור אחרי הקריאה (מהראש לזנב)? והסבר בעד 15 מילים מה הפונקציה עושה.","qtype":"trace","hint":"ה-<span dir=\"ltr\">enque</span> מתבצע רק בדרך חזרה מהרקורסיה — מהרמה העמוקה ביותר כלפי מעלה.","rule":"מעקב — בסגנון 2025 ש'5 בדיוק","html":"<div class=\"qh\"><b>5.1</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🤖 קלוד</span><span class=\"src\">מעקב — בסגנון 2025 ש'5 בדיוק</span></div>\n<pre class=\"c\">int what(QUEUE* q)\n{\n    if (Q_isEmpty(q)) return 0;\n\n    int x = Q_deque(q);\n    int r = what(q);\n    Q_enque(q, x);\n    return r + 1;\n}</pre>\n<p>התור מכיל (מהראש): <code>3, 7, 1</code>. מה מוחזר? איך ייראה התור אחרי\nהקריאה? והסבר ב-≤15 מילים.</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<p><b>מוחזר: 3</b> (סופרים איבר בכל רמת רקורסיה).</p>\n<p><b>התור אחרי:</b> <code>1, 7, 3</code> — <b>הפוך!</b> ה-enque קורה\nבדרך חזרה, מהרמה העמוקה כלפי מעלה: קודם חוזר 1, אחריו 7, אחריו 3.</p>\n<p><b>ב-15 מילים:</b> \"מחזירה את מספר האיברים בתור, והופכת את סדר\nהאיברים בו\".</p>\n<div class=\"warn\" style=\"margin-bottom:0\"><b>ההשוואה ששווה לזכור:</b>\nבמחסנית, pop→רקורסיה→push <b>משמר</b> את הסדר. בתור, deque→רקורסיה→enque\n<b>הופך</b> אותו. זה ההבדל המבני בין LIFO ל-FIFO — ושאלת מעקב אוהבת\nלבדוק בדיוק את זה.</div>\n</div></details>"},{"id":"BK-5.2","cat":"מחסנית ותור","difficulty":2,"skills":["מחסנית ותור"],"origin":"bank","kind":"open","sourceLabel":"🤖 קלוד · 5.2","prompt":"כתוב פונקציה <b>רקורסיבית</b> <code>void removeAllX(STACK* s, int x)</code> המסירה מהמחסנית את כל המופעים של הערך <span dir=\"ltr\">x</span>, ומשאירה את שאר האיברים <b>בסדרם המקורי</b>. <b>בלי לולאות ובלי מבני עזר</b> — מותר רק <code>S_push</code>, <code>S_pop</code>, <code>S_isEmpty</code>.","qtype":"code","signature":"void removeAllX(STACK* s, int x)","hint":"השלד הוא <span dir=\"ltr\">pop → רקורסיה → push</span>; הוסף תנאי שקובע אילו איברים באמת מוחזרים למחסנית.","rule":"כתיבה — סינון","html":"<div class=\"qh\"><b>5.2</b><span class=\"diff diff-e\">קל</span><span class=\"diff srcb\">🤖 קלוד</span><span class=\"src\">כתיבה — סינון</span></div>\n<p>כתוב <code>void removeAllX(STACK* s, int x)</code> שמסירה מהמחסנית את\nכל המופעים של x ומשאירה את שאר האיברים <b>בסדרם המקורי</b>.\nבלי לולאות, בלי מבני עזר.</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<pre class=\"c\">void removeAllX(STACK* s, int x)\n{\n    if (S_isEmpty(s)) return;\n\n    int v = S_pop(s);\n    removeAllX(s, x);\n    if (v != x)\n        S_push(s, v);        // מחזירים רק את מי שאינו x\n}</pre>\n<p>השלד המוכר, עם תנאי לפני ה-push. הסדר נשמר כי ה-push-ים קורים\nבדרך חזרה, מהתחתית לראש.</p>\n</div></details>"},{"id":"BK-5.3","cat":"מחסנית ותור","difficulty":4,"skills":["מחסנית ותור"],"origin":"bank","kind":"open","sourceLabel":"🤖 קלוד · 5.3","prompt":"כתוב פונקציה <code>void enqueueFront(QUEUE* q, int x)</code> המכניסה את הערך <span dir=\"ltr\">x</span> ל<b>ראש</b> התור (ולא לסופו), כך שסדר שאר האיברים יישמר. מותר להשתמש רק בפעולות <code>Q_enque</code>, <code>Q_deque</code>, <code>Q_isEmpty</code> — <b>בלי לולאות ובלי מבני עזר</b> (מותר פונקציית עזר רקורסיבית).","qtype":"code","signature":"void enqueueFront(QUEUE* q, int x)","hint":"בתור, השלד <span dir=\"ltr\">deque → רקורסיה → enque</span> <b>הופך</b> את הסדר — נצל זאת פעמיים.","rule":"כתיבה — הקשה מהרגיל","html":"<div class=\"qh\"><b>5.3</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🤖 קלוד</span><span class=\"src\">כתיבה — הקשה מהרגיל</span></div>\n<p>כתוב <code>void enqueueFront(QUEUE* q, int x)</code> שמכניסה את x\n<b>לראש</b> התור (במקום לסוף). מותר רק <code>Q_deque / Q_enque /\nQ_isEmpty</code>, בלי לולאות ובלי מבני עזר.</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<pre class=\"c\">void revQ(QUEUE* q)              /* הופך את סדר התור */\n{\n    if (Q_isEmpty(q)) return;\n    int v = Q_deque(q);\n    revQ(q);\n    Q_enque(q, v);\n}\n\nvoid enqueueFront(QUEUE* q, int x)\n{\n    revQ(q);            /* 1,2,3  -&gt;  3,2,1     */\n    Q_enque(q, x);      /*        -&gt;  3,2,1,x   */\n    revQ(q);            /*        -&gt;  x,1,2,3   */\n}</pre>\n<p><b>הרעיון:</b> deque⟵רקורסיה⟵enque על תור <b>הופך</b> את הסדר —\nאז הופכים, מכניסים את x לסוף, והופכים שוב: ‏x מקדימה וכל השאר בסדרם\nהמקורי.</p>\n<div class=\"warn\" style=\"margin-bottom:0\"><b>המלכודת שכמעט עבדה עלינו:</b>\nהגרסה ה\"מתבקשת\" (deque ⟵ רקורסיה ⟵ enque עם ‏x בתחתית) משאירה את\n‏x בראש אבל <b>הופכת את שאר האיברים</b> (‏1,2,3 ⟵ ‏x,3,2,1) — בדוק\nבעצמך. בתור, שלד ההחזרה-בדרך-חזרה הופך סדר; לכן חייבים שני היפוכים.</div>\n</div></details>"},{"id":"BK-5.4","cat":"מחסנית ותור","difficulty":3,"skills":["מחסנית ותור"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 5.4","prompt":"ממש מחסנית בעזרת <b>תור אחד בלבד</b> <span dir=\"ltr\">Q</span> (ניתן להניח שהערכים ייחודיים), תוך שימוש בפעולות התור בלבד. תאר בפסאודו-קוד את הפעולות <span dir=\"ltr\">Init</span>, <span dir=\"ltr\">Push</span>, <span dir=\"ltr\">Pop</span>, <span dir=\"ltr\">Top</span> ו-<span dir=\"ltr\">IsEmpty</span>, וציין את סיבוכיות הזמן של כל אחת מהן.","qtype":"design","hint":"אחרי הכנסת איבר חדש, גלגל את כל האיברים שלפניו אל סוף התור — כך החדש תמיד יימצא בראש.","rule":"מבחן 2019 שאלון Y · שאלה 4 · 20 נק'","html":"<div class=\"qh\"><b>5.4</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן עבר</span><span class=\"src\"><span class=\"tag exam\">מבחן 2019 שאלון Y · שאלה 4 · 20 נק'</span> · מחסנית מתור אחד</span></div>\n<p>ממש מחסנית בעזרת <b>תור אחד בלבד</b> Q (הערכים ייחודיים). תאר\nבפסאודו-קוד את Init, Push, Pop, Top, IsEmpty וציין סיבוכיות.</p>\n<details class=\"sol\"><summary>הפתרון הרשמי</summary><div class=\"body\">\n<p><b>הרעיון:</b> אחרי כל Enque, מגלגלים את כל שאר האיברים מאחוריו —\nכך שהחדש תמיד בראש התור, והתור מתנהג כמחסנית.</p>\n<pre>Push(S, x):                              O(n)\n  1. אם Q ריק — Enque(Q, x), החזר True\n  2. Enque(Q, x)\n  3. כל עוד Head(Q) ≠ x:\n         Enque(Q, Deque(Q))     ← גלגול\n  4. החזר True\n\nPop(S):  אם ריק החזר EMPTY, אחרת Deque(Q)   O(1)\nTop(S):  החזר Head(Q)                        O(1)\nInit / IsEmpty: של התור                      O(1)</pre>\n<p>שים לב להיפוך התפקידים מהרגיל: כאן דווקא ה-<b>Push</b> יקר (O(n))\nוה-Pop זול — כי שילמנו את מחיר הסידור מראש.</p>\n</div></details>"},{"id":"BK-5.5","cat":"מחסנית ותור","difficulty":4,"skills":["מחסנית ותור"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 5.5","prompt":"כתוב את האלגוריתם של הפונקציה <code>createQMissNum(Q1)</code> המקבלת תור <span dir=\"ltr\">Q1</span> של מספרים שלמים הממוין בסדר <b>עולה ממש</b>, ומחזירה תור חדש <span dir=\"ltr\">Q2</span> המכיל את כל המספרים ה<b>חסרים</b> בטווח שבין המספר הקטן ביותר לגדול ביותר. בסיום, <span dir=\"ltr\">Q1</span> חייב להישאר ללא שינוי. לדוגמה: עבור <span dir=\"ltr\">Q1 = 2,4,5,9,12</span> יוחזר <span dir=\"ltr\">Q2 = 3,6,7,8,10,11</span>. השתמש בפעולות התור בלבד (<span dir=\"ltr\">Enque, Deque, Head, IsEmpty</span>).","qtype":"code","signature":"QUEUE* createQMissNum(QUEUE* Q1)","hint":"השתמש באיבר הראשון כ\"זקיף\" שמסמן סיום סיבוב שלם על התור, והרץ מונה על ה<b>ערכים</b> ולא על האיברים.","rule":"מבחן 2022 · שאלה 4 · 18 נק'","html":"<div class=\"qh\"><b>5.5</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🎓 מבחן עבר</span><span class=\"src\"><span class=\"tag exam\">מבחן 2022 · שאלה 4 · 18 נק'</span> · השלמת אלגוריתם</span></div>\n<p><code>createQMissNum(Q1)</code> מקבלת תור ממוין בסדר עולה ממש ומחזירה\nתור Q2 עם כל המספרים <b>החסרים</b>; Q1 נשאר ללא שינוי.\n<br>לדוגמה: ‏Q1 = ‏2,4,5,9,12 → ‏Q2 = ‏3,6,7,8,10,11.\nכתוב את האלגוריתם עם פעולות התור בלבד.</p>\n<details class=\"sol\"><summary>הפתרון הרשמי</summary><div class=\"body\">\n<pre>1. הגדר startNum, num; הגדר תור Q2 ואתחל\n2. startNum = Deque(Q1)\n3. num = startNum\n4. Enque(Q1, startNum)              ← הזקיף חוזר לסוף\n5. כל עוד Head(Q1) ≠ startNum:\n   5.1  num = num + 1\n   5.2  אם Head(Q1) ≠ num:\n            Enque(Q2, num)          ← מספר חסר\n   5.3  אחרת:\n            Enque(Q1, Deque(Q1))    ← קיים — גלגל הלאה\n6. החזר Q2</pre>\n<p><b>שני טריקים בשאלה אחת:</b> זקיף (האיבר הראשון מסמן סוף סיבוב —\nכמו ב-2021 ש'2 של המעבדה) + מונה שרץ על <b>הערכים</b> ולא על האיברים.</p>\n</div></details>"},{"id":"BK-5.6","cat":"מחסנית ותור","difficulty":3,"skills":["מחסנית ותור"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 5.6","prompt":"שליחים ממתינים בתור לפי סדר הגעתם; לכל שליח מספר ת\"ז ונפח מנוע. כתוב אלגוריתם המקבל את התור ונפח מנוע נדרש, מדפיס את ת\"ז השליח ה<b>ראשון</b> בתור שנפח מנועו מספיק ומוציא אותו מהתור, כאשר סדר שאר השליחים חייב להישאר <b>ללא שינוי</b>. אם אין שליח מתאים יש להדפיס <code>\"No delivery person is available\"</code> ולהשאיר את התור כפי שהיה. מהי סיבוכיות האלגוריתם?","qtype":"code","signature":"void FindDelivery(QUEUE* Q, int volume)","hint":"שמור את הת\"ז של האיבר הראשון כזקיף, וזכור שגם <b>אחרי</b> שמצאת והוצאת את השליח יש להמשיך לגלגל עד שהתור חוזר לסדרו המקורי.","rule":"מבחן 2018 שאלון A · שאלה 3 · 18 נק'","html":"<div class=\"qh\"><b>5.6</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן עבר</span><span class=\"src\"><span class=\"tag exam\">מבחן 2018 שאלון A · שאלה 3 · 18 נק'</span> · אלגוריתם על תור</span></div>\n<p>שליחים ממתינים בתור לפי סדר הגעה; לכל שליח ת\"ז ונפח מנוע. כתוב\nאלגוריתם שמקבל את התור ונפח נדרש, מדפיס את ת\"ז השליח <b>הראשון</b>\nשנפח מנועו מספיק ומוציא אותו — סדר השאר נשמר. אם אין מתאים:\n<code>\"No delivery person is available\"</code>. מה הסיבוכיות?</p>\n<details class=\"sol\"><summary>הפתרון הרשמי (תמצית)</summary><div class=\"body\">\n<pre>FindDelivery(Q, volume):\n  1. אם השליח בראש התור מתאים — הוצא, הדפס ת\"ז, סיים\n  2. אחרת: הוצא אותו, שמור firstID = ת\"ז שלו, החזר לסוף התור\n  3. כל עוד לא נמצא מתאים וה-ת\"ז בראש ≠ firstID:\n       אם הראש מתאים — הוצא והדפס, צא מהלולאה\n       אחרת — גלגל אותו לסוף\n  4. אם חזרנו ל-firstID בלי למצוא — הדפס את ההודעה\n  5. אחרת — המשך לגלגל עד ש-firstID חוזר לראש\n     (כדי שסדר השאר יישמר!)\n  סיבוכיות: O(N)</pre>\n<p><b>הנקודה שמפילה נבחנים:</b> שלב 5. אחרי שמצאת והוצאת את השליח,\nהתור \"מסובב\" — חייבים להמשיך לגלגל עד שהסדר המקורי חוזר. מי ששכח —\nאיבד את \"סדר שאר השליחים יישאר ללא שינוי\".</p>\n</div></details>"},{"id":"BK-5.7","cat":"מחסנית ותור","difficulty":4,"skills":["מחסנית ותור"],"origin":"bank","kind":"open","sourceLabel":"🌐 אינטרנט · 5.7","prompt":"כתוב אלגוריתם הממיין מחסנית <span dir=\"ltr\">S</span> כך שבסופו הערך הגדול ביותר יהיה בראשה, בעזרת <b>מחסנית עזר אחת בלבד</b> <span dir=\"ltr\">T</span>. <b>אסור להשתמש במערכים וברקורסיה</b>. מהי סיבוכיות זמן הריצה במקרה הגרוע? לאיזה אלגוריתם מיון מוכר זה שקול?","qtype":"code","signature":"void sortStack(STACK* S, STACK* T)","hint":"הוצא איבר מ-<span dir=\"ltr\">S</span> ו\"פנה לו מקום\" ב-<span dir=\"ltr\">T</span> על ידי החזרת איברים גדולים/קטנים ממנו חזרה ל-<span dir=\"ltr\">S</span> — בדיוק כמו מיון הכנסה.","rule":"מעובד ממאגרי תרגול באינטרנט (קלאסיקה) · מיון מחסנית","html":"<div class=\"qh\"><b>5.7</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🌐 אינטרנט</span><span class=\"src\">מעובד ממאגרי תרגול באינטרנט (קלאסיקה) · מיון מחסנית</span></div>\n<p>כתוב אלגוריתם שממיין מחסנית S (הגדול בראש) בעזרת <b>מחסנית עזר\nאחת</b> T בלבד, בלי מערכים ובלי רקורסיה. מה הסיבוכיות?</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<pre>כל עוד S לא ריקה:\n  1. tmp = Pop(S)\n  2. כל עוד T לא ריקה וגם Top(T) &lt; tmp:\n         Push(S, Pop(T))     ← מפנים מקום ל-tmp\n  3. Push(T, tmp)\nבסוף: T ממוינת (הקטן בראש) — שפוך אותה חזרה ל-S\n      והגדול יהיה בראש S.</pre>\n<p><b>הסיבוכיות: O(n²)</b> במקרה הגרוע — כל איבר עלול להידחף הלוך ושוב.\nזה בעצם מיון הכנסה, כשה\"מערך הממוין\" הוא מחסנית T.</p>\n</div></details>"},{"id":"BK-5.8","cat":"מחסנית ותור","difficulty":3,"skills":["מחסנית ותור"],"origin":"bank","kind":"open","sourceLabel":"📝 מטלה · 5.8","prompt":"כתוב פונקציה <b>רקורסיבית</b> <code>int maxStack(STACK* s)</code> המחזירה את הערך המקסימלי במחסנית, כאשר בסיום הריצה המחסנית נשארת <b>בדיוק כפי שהייתה</b>. <b>בלי לולאות ובלי מבני עזר.</b>","qtype":"code","signature":"int maxStack(STACK* s)","hint":"<span dir=\"ltr\">pop → רקורסיה → push</span> משחזר את הסדר במחסנית; שים לב לבחור ערך החזרה ניטרלי עבור מחסנית ריקה.","rule":"מקסימום במחסנית — ושחזורה","html":"<div class=\"qh\"><b>5.8</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">📝 מטלה HW3</span><span class=\"src\">מקסימום במחסנית — ושחזורה</span></div>\n<p>החזר את הערך המקסימלי במחסנית כך שבסוף היא נשארת <b>בדיוק כפי\nשהייתה</b>. בלי לולאות ובלי מבנה עזר.</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<pre class=\"c\">int maxStack(STACK* s)\n{\n    if (S_isEmpty(s)) return INT_MIN;\n    int v = S_pop(s);\n    int m = maxStack(s);\n    S_push(s, v);                /* שחזור בדרך חזרה */\n    return v &gt; m ? v : m;\n}</pre>\n<p>השלד המוכר (pop⟵רקורסיה⟵push משמר סדר) + ערך עצירה ניטרלי.\nזו הגרסה המבחנית של שאלת ה-HW3 שלך.</p>\n</div></details>"},{"id":"BK-5.9","cat":"מחסנית ותור","difficulty":4,"skills":["מחסנית ותור"],"origin":"bank","kind":"open","sourceLabel":"📘 מצגת · 5.9","prompt":"כתוב אלגוריתם הקולט מספרים מהמשתמש עד לקליטת הערך <span dir=\"ltr\">−999</span>, ובונה מחסנית שבה האיבר ה<b>קטן</b> ביותר נמצא בראש — כאשר המחסנית ממוינת <b>בכל רגע</b> ולא רק בסוף הקליטה. מותר להשתמש במחסנית עזר אחת. מהי סיבוכיות ההכנסה הבודדת ומהי הסיבוכיות הכוללת?","qtype":"code","signature":"void buildSortedStack(STACK* numbers, STACK* temp)","hint":"לכל מספר נקלט: פנה לו מקום על ידי העברת האיברים המפריעים למחסנית העזר, דחוף אותו, והחזר את הכול — זהו מיון הכנסה על מחסנית.","rule":"מצגת המחסנית — מחסנית ממוינת תוך כדי קליטה","html":"<div class=\"qh\"><b>5.9</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">📘 מצגת המרצה</span><span class=\"src\">מצגת המחסנית — מחסנית ממוינת תוך כדי קליטה</span></div>\n<p>קלוט מספרים עד ‎−999 ובנה מחסנית שבה <b>הקטן בראש</b> — הממוינת\nבכל רגע, לא רק בסוף. מותר מחסנית עזר אחת.</p>\n<details class=\"sol\"><summary>האלגוריתם מהמצגת</summary><div class=\"body\">\n<pre>קלוט num; כל עוד num != STOP:\n  1. כל עוד numbers לא ריקה וגם num &gt; Top(numbers):\n        Push(temp, Pop(numbers))    /* פנה מקום */\n  2. Push(numbers, num)\n  3. כל עוד temp לא ריקה:\n        Push(numbers, Pop(temp))    /* החזר הכול */\n  4. קלוט num</pre>\n<p>זה בדיוק <b>מיון הכנסה על מחסנית</b> — ה\"מערך הממוין\" הוא המחסנית.\nO(n) לכל הכנסה, O(n²) סה\"כ. השווה לשאלה 5.7 (מיון מחסנית שלמה).</p>\n</div></details>"},{"id":"BK-5.10","cat":"מחסנית ותור","difficulty":2,"skills":["מחסנית ותור"],"origin":"bank","kind":"open","sourceLabel":"📘 מצגת · 5.10","prompt":"במקרר מאוחסנים בקבוקי חלב, וידוע שבקבוקים חדשים מגיעים תמיד עם תאריך תפוגה מאוחר או שווה לזה של הבקבוקים הקיימים. תכנן מערכת המאתרת בכל רגע נתון את הבקבוקים שפג תוקפם ומוציאה אותם. באיזה מבנה נתונים תבחר ומדוע? תאר את הפעולות ואת סיבוכיותן.","qtype":"design","hint":"קרא היטב את ההבטחה שבשאלה — כשההכנסות כבר מגיעות בסדר ממוין, אין צורך במבנה מתוחכם.","rule":"מצגת התור — בקבוקי החלב","html":"<div class=\"qh\"><b>5.10</b><span class=\"diff diff-e\">קל</span><span class=\"diff srcb\">📘 מצגת המרצה</span><span class=\"src\">מצגת התור — בקבוקי החלב</span></div>\n<p>מקרר עם בקבוקי חלב; חדשים מגיעים תמיד עם תאריך תפוגה מאוחר או\nשווה לקיימים. תכנן מערכת שמאתרת בכל רגע את הפגי-תוקף. איזה מבנה ולמה?</p>\n<details class=\"sol\"><summary>הפתרון מהמצגת</summary><div class=\"body\">\n<p><b>תור.</b> ההכנסות מגיעות בסדר תפוגה לא-יורד ⟵ סדר ההגעה = סדר\nהתפוגה = FIFO טהור. הפעולה: כל עוד תאריך ‏Head(Q) עבר — הדפס\n‏id(Head) ובצע Deque. כל פעולה O(1).</p>\n<p><b>הלקח לזיהוי:</b> כשמובטח שהכנסות מגיעות ממוינות — לא צריך ערימה\nולא עץ; תור פשוט מספיק. לקרוא את ההבטחות שבשאלה!</p>\n</div></details>"},{"id":"BK-5.11","cat":"מחסנית ותור","difficulty":3,"skills":["מחסנית ותור"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 5.11","prompt":"\"בלוק\" מוגדר כרצף של שני איברים זהים או יותר במחסנית. כתוב/השלם אלגוריתם הסורק מחסנית, ולכל בלוק באורך <span dir=\"ltr\">n</span> של הערך <span dir=\"ltr\">k</span> דוחף למחסנית <span dir=\"ltr\">S</span> את הערך <span dir=\"ltr\">n·k</span>. במבחן ניתן שלד קוד ונדרש להשלים חמישה ביטויים חסרים — כתוב את האלגוריתם המלא.","qtype":"code","signature":"void blocks(STACK* pStack, STACK* S)","hint":"אל תשכח לטפל ב<b>רצף האחרון</b> אחרי סיום הלולאה — זו הנקודה שנשכחת אצל רוב הנבחנים.","rule":"אלגוריתם הבלוקים — 5 השלמות","html":"<div class=\"qh\"><b>5.11</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2020 שאלון X · ש'4 · 20 נק'</span><span class=\"src\">אלגוריתם הבלוקים — 5 השלמות</span></div>\n<p>\"בלוק\" = רצף של שניים או יותר זהים במחסנית; לכל בלוק דוחפים ל-S את ‏n·k.\nחמישה ביטויים חסרים.</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p>‏(1) ‏count=count+1 · ‏(2) <code>count &gt; 1</code> · ‏(3) דחוף count·num ·\n‏(4) ‏num=x · ‏(5) אם <code>count &gt; 1</code> דחוף count·num — <b>הרצף האחרון</b>\nאחרי הלולאה, המקום שכולם שוכחים.</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d17','')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-5.12","cat":"מחסנית ותור","difficulty":3,"skills":["מחסנית ותור"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 5.12","prompt":"כתוב פונקציה <b>רקורסיבית</b> <code>BOOL isSorted(STACK* s)</code> הבודקת אם המחסנית ממוינת בסדר עולה מהראש אל התחתית. מותר להשתמש רק ב-<code>S_isEmpty</code>, <code>S_pop</code> ו-<code>S_top</code>; <b>בלי לולאות ובלי מבני עזר</b>. הקפד שהפתרון לא יקרוס במקרי הקצה.","qtype":"code","signature":"BOOL isSorted(STACK* s)","hint":"פצל את הפעולות לשורות נפרדות — בצע <span dir=\"ltr\">pop</span>, בדוק אם המחסנית התרוקנה, ורק אז השווה ל-<span dir=\"ltr\">S_top</span>.","rule":"isSorted על מחסנית — בלי לולאות","html":"<div class=\"qh\"><b>5.12</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2021 · ש'2 · 18 נק'</span><span class=\"src\">isSorted על מחסנית — בלי לולאות</span></div>\n<p>האם המחסנית ממוינת עולה מהראש לתחתית? רק\n‏S_isEmpty/S_pop/S_top, בלי מבני עזר.</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<pre class=\"c\">BOOL isSorted(STACK* s){\n    if (S_isEmpty(s))        return True;\n    if (S_pop(s) &gt; S_top(s)) return False;\n    return isSorted(s); }</pre>\n<p style=\"font-size:12.5px\">⚠ זה הפתרון הרשמי, אבל יש בו שני חורים\nעדינים: כשנשאר איבר אחד — ‏pop מרוקן ואז ‏top רץ על מחסנית ריקה; וסדר\nחישוב האגפים ב-C אינו מובטח. הגרסה הבטוחה מפצלת:\n<code>x = S_pop(s); if (S_isEmpty(s)) return True; if (x &gt; S_top(s)) return False;</code>\nבמבחן — כתוב את המפוצלת.</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d07','')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-5.13","cat":"מחסנית ותור","difficulty":3,"skills":["מחסנית ותור"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 5.13","prompt":"כתוב פונקציה <code>void even(QUEUE* q)</code> המדפיסה את כל הערכים ה<b>זוגיים</b> שבתור, מהראש לסוף, כאשר בסיום הריצה התור נשאר <b>ללא שינוי</b>. <b>בלי לולאות ובלי מבנה עזר</b> — מותר להיעזר בפונקציית עזר רקורסיבית אחת ובפעולות התור בלבד.","qtype":"code","signature":"void even(QUEUE* q)","hint":"הכנס \"זקיף\" (ערך שאינו יכול להופיע בתור) לסוף התור כדי לדעת מתי הושלם סיבוב שלם — כך הסדר נשמר.","rule":"even — הדפסת זוגיים, התור נשמר","html":"<div class=\"qh\"><b>5.13</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2023 · ש'2 · 16 נק'</span><span class=\"src\">even — הדפסת זוגיים, התור נשמר</span></div>\n<p>הדפס את הזוגיים מהראש לסוף; בסוף התור ללא שינוי. בלי לולאות\nובלי מבנה עזר; מותר פונקציית עזר אחת.</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<pre class=\"c\">void even(QUEUE* q){ Q_enque(q,-1); rec(q); }\nvoid rec(QUEUE* q){\n    int x = Q_deque(q);\n    if (x != -1){\n        if (x%2==0) printf(\"%d, \",x);\n        Q_enque(q,x); rec(q); } }</pre>\n<p><b>טריק הזקיף:</b> ‏−1 מסמן סוף סיבוב ⟵ סדר נשמר.</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d07','sol-2023-2')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-5.14","cat":"מחסנית ותור","difficulty":3,"skills":["מחסנית ותור"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 5.14","prompt":"כתוב פונקציה <b>רקורסיבית</b> <code>int countValInStack(STACK* pStack, int val)</code> המחזירה כמה פעמים מופיע הערך <span dir=\"ltr\">val</span> במחסנית. בסיום הריצה המחסנית חייבת להישאר <b>ללא שינוי</b>, ו<b>אסור להשתמש במבנה עזר</b>.","qtype":"code","signature":"int countValInStack(STACK* pStack, int val)","hint":"<span dir=\"ltr\">pop → רקורסיה → push</span> משחזר את המחסנית במדויק; את הספירה אפשר לבצע בעזרת ערך הביטוי <span dir=\"ltr\">(x == val)</span>.","rule":"countValInStack — ספירה עם שחזור","html":"<div class=\"qh\"><b>5.14</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2024 · ש'5 · 12 נק'</span><span class=\"src\">countValInStack — ספירה עם שחזור</span></div>\n<p><code>int countValInStack(STACK* pStack, int val)</code> — כמה פעמים\n‏val מופיע; המחסנית תישאר ללא שינוי; אסור מבנה עזר.</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<pre class=\"c\">if (S_isEmpty(pStack)) return 0;\nint x = S_pop(pStack);\nint count = (x == val) + countValInStack(pStack, val);\nS_push(pStack, x);\nreturn count;</pre>\n<p>pop⟵רקורסיה⟵push — במחסנית זה משחזר את הסדר במדויק.</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d07','sol-2024-5')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-5.15","cat":"מחסנית ותור","difficulty":3,"skills":["מחסנית ותור"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 5.15","prompt":"הפונקציה הרקורסיבית <code>what</code> מבצעת <span dir=\"ltr\">deque</span> מהתור, יורדת ברקורסיה, מבצעת <span dir=\"ltr\">enque</span> בדרך חזרה, ומחזירה את המינימום המצטבר. התור מכיל (מהראש לזנב): <span dir=\"ltr\">4, 50, 1, 22, −10, 7</span>. מה יוחזר מהקריאה? כיצד ייראה התור בסיום? והסבר בעד 15 מילים מה הפונקציה עושה.","qtype":"trace","hint":"ה-<span dir=\"ltr\">enque</span> מתבצע בדרך חזרה מהרקורסיה — מה זה עושה לסדר האיברים בתור?","rule":"what על תור — מעקב מלא","html":"<div class=\"qh\"><b>5.15</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2025 · ש'5 · 12 נק'</span><span class=\"src\">what על תור — מעקב מלא</span></div>\n<p>‏what עושה deque, יורדת ברקורסיה, עושה enque בחזרה ומחזירה מינימום\nמצטבר. התור: ‏4,50,1,22,−10,7. מה מוחזר? מה מצב התור? ‏≤15 מילים?</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p>מוחזר: <b>‎−10</b> · התור אחרי: <b>‏7,−10,22,1,50,4 — הפוך</b> ·\n\"מחזירה את המינימום בתור וגם הופכת את סדרו\". אנימציה מלאה בפרק\nהפתרונות!</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d07','sol-2025-5')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-6.1","cat":"ערימה","difficulty":2,"skills":["ערימה"],"origin":"bank","kind":"open","sourceLabel":"🤖 קלוד · 6.1","prompt":"נתונה ערימת מקסימום (max-heap) המיוצגת במערך מאינדקס 1: <span dir=\"ltr\">[50, 30, 40, 10, 20, 35]</span>. הכנס אליה את הערך <span dir=\"ltr\">45</span> ולאחר מכן את הערך <span dir=\"ltr\">60</span>. כתוב את המערך המתקבל <b>אחרי כל אחת</b> מההכנסות, ופרט את ההחלפות שבוצעו.","qtype":"trace","hint":"כל איבר חדש נכנס למקום הפנוי האחרון ו\"מטפס\" מעלה (<span dir=\"ltr\">sift-up</span>) כל עוד הוא גדול מאביו.","rule":"מעקב הכנסות","html":"<div class=\"qh\"><b>6.1</b><span class=\"diff diff-e\">קל</span><span class=\"diff srcb\">🤖 קלוד</span><span class=\"src\">מעקב הכנסות</span></div>\n<p>נתונה ערימת מקסימום: <code>[50, 30, 40, 10, 20, 35]</code> (מאינדקס 1).\nהכנס את 45 ואחריו את 60. כתוב את המערך אחרי כל הכנסה.</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<p><b>הכנסת 45:</b> נכנס לאינדקס 7 (בן של 40). <code>45 &gt; 40</code> → מחליפים. <code>45 &lt; 50</code> → עוצרים.</p>\n<pre>[50, 30, 45, 10, 20, 35, 40]</pre>\n<p><b>הכנסת 60:</b> נכנס לאינדקס 8 (בן של 10). <code>60 &gt; 10</code> → עולה. <code>60 &gt; 30</code> → עולה. <code>60 &gt; 50</code> → עולה לשורש.</p>\n<pre>[60, 50, 45, 30, 20, 35, 40, 10]</pre>\n<p>שים לב מה קרה בדרך: 10 ירד לאינדקס 8, 30 ירד לאינדקס 4, 50 ירד\nלאינדקס 2 — כל מי שהוחלף <b>יורד רמה</b>.</p>\n</div></details>"},{"id":"BK-6.2","cat":"ערימה","difficulty":3,"skills":["ערימה"],"origin":"bank","kind":"open","sourceLabel":"🤖 קלוד · 6.2","prompt":"נתונה ערימת מקסימום המיוצגת במערך: <span dir=\"ltr\">[90, 70, 80, 30, 40, 60, 75, 10]</span>. בצע עליה פעולת <span dir=\"ltr\">Del_max</span> <b>פעמיים</b>, וכתוב את המערך המתקבל אחרי כל אחת מהפעולות. פרט את ההחלפות שבוצעו בכל שקיעה.","qtype":"trace","hint":"בשקיעה (<span dir=\"ltr\">sift-down</span>) מחליפים תמיד עם ה<b>גדול מבין שני הבנים</b>, ולא עם הראשון שגדול מהצומת.","rule":"Del_max פעמיים","html":"<div class=\"qh\"><b>6.2</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🤖 קלוד</span><span class=\"src\">Del_max פעמיים</span></div>\n<p>נתונה ערימת מקסימום: <code>[90, 70, 80, 30, 40, 60, 75, 10]</code>.\nבצע Del_max פעמיים וכתוב את המערך אחרי כל פעולה.</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<p><b>Del_max ראשון:</b> מוציאים 90, האחרון (10) עולה לשורש ושוקע:\nמול 70 ו-80 → מתחלף עם 80 · מול 60 ו-75 → מתחלף עם 75 · הגיע לעלה.</p>\n<pre>[80, 70, 75, 30, 40, 60, 10]</pre>\n<p><b>Del_max שני:</b> מוציאים 80, האחרון (10) עולה ושוקע:\nמול 70 ו-75 → מתחלף עם 75 · מול 60 → מתחלף עם 60.</p>\n<pre>[75, 70, 60, 30, 40, 10]</pre>\n<div class=\"tip\" style=\"margin-bottom:0\">בשקיעה תמיד מחליפים עם\n<b>הגדול מבין שני הבנים</b> — לא עם הראשון שגדול מאיתנו.</div>\n</div></details>"},{"id":"BK-6.3","cat":"ערימה","difficulty":4,"skills":["ערימה"],"origin":"bank","kind":"open","sourceLabel":"🤖 קלוד · 6.3","prompt":"ערימת מקסימום סופית נראית כך: <span dir=\"ltr\">[40, 35, 20, 10, 30]</span>. ידוע שהאיבר ה<b>ראשון</b> שהוכנס לערימה היה <span dir=\"ltr\">10</span>. מצא סדר הכנסה אפשרי של כל האיברים שמוביל למצב זה, והוכח את תשובתך על ידי הצגת מצב הערימה אחרי כל הכנסה. (ייתכן יותר מפתרון אחד.)","qtype":"trace","hint":"העיקרון היחיד: <b>אחרי כל הכנסה</b> המערך חייב להיות ערימה תקינה, וכל איבר חדש נכנס לסוף ו\"צף\" מעלה.","rule":"הנדסה לאחור — בסגנון 2025 ש'6","html":"<div class=\"qh\"><b>6.3</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🤖 קלוד</span><span class=\"src\">הנדסה לאחור — בסגנון 2025 ש'6</span></div>\n<p>הערימה הסופית: <code>[40, 35, 20, 10, 30]</code>. ידוע שהאיבר\n<b>הראשון</b> שהוכנס היה 10. מצא סדר הכנסה אפשרי.</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<p><b>תשובה אפשרית: 10, 35, 20, 30, 40.</b> בדיקה צעד-צעד:</p>\n<ol>\n<li>10 → <code>[10]</code> ✔</li>\n<li>35: נכנס כבן של 10, גדול ממנו → צף. <code>[35, 10]</code> ✔</li>\n<li>20: בן של 35, קטן ממנו → נשאר. <code>[35, 10, 20]</code> ✔</li>\n<li>30: בן של 10, גדול → מתחלף. <code>30 &lt; 35</code> → עוצר. <code>[35, 30, 20, 10]</code> ✔</li>\n<li>40: בן של 30, גדול → עולה. <code>40 &gt; 35</code> → לשורש. <code>[40, 35, 20, 10, 30]</code> ✔</li>\n</ol>\n<p>יש יותר מתשובה אחת נכונה — העיקרון היחיד: <b>אחרי כל הכנסה המערך\nחייב להיות ערימה תקינה</b>, וכל איבר חדש נכנס בסוף וצף.</p>\n</div></details>"},{"id":"BK-6.4","cat":"ערימה","difficulty":3,"skills":["ערימה"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 6.4","prompt":"נתון המערך <span dir=\"ltr\">A = [1, 2, 3, 9, 8, 7, 2, 3]</span>. בונים ממנו ערימת מקסימום באלגוריתם <span dir=\"ltr\">MakeHeap</span> (בנייה מלמטה למעלה, כפי שנלמד בכיתה). הצג את המערך <b>אחרי כל שינוי</b> — כל החלפה (<span dir=\"ltr\">swap</span>) נחשבת שלב נפרד ויש לרשום אותה בשורה משלה.","qtype":"trace","hint":"<span dir=\"ltr\">MakeHeap</span> עובר על הצמתים הפנימיים מהאחרון לראשון; שים לב שצומת יכול להמשיך לשקוע כמה רמות — כל החלפה נרשמת בנפרד.","rule":"מבחן 2018 שאלון A · שאלה 6 · 18 נק'","html":"<div class=\"qh\"><b>6.4</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן עבר</span><span class=\"src\"><span class=\"tag exam\">מבחן 2018 שאלון A · שאלה 6 · 18 נק'</span> · MakeHeap מלא</span></div>\n<p>נתון <code>A = [1, 2, 3, 9, 8, 7, 2, 3]</code>. בונים ערימת מקסימום\nעם MakeHeap (בנייה מלמטה למעלה, כמו בכיתה). הצג את המערך <b>אחרי כל\nשינוי</b> (swap = שלב אחד).</p>\n<details class=\"sol\"><summary>הפתרון הרשמי — כל השלבים</summary><div class=\"body\">\n<p>MakeHeap עובר על הצמתים הפנימיים <b>מהאחרון לראשון</b> (אינדקסים\n4→1 עבור n=8) ומבצע שקיעה לכל אחד:</p>\n<pre>1, 2, 3, 9, 8, 7, 2, 3     ← מצב פתיחה\n1, 2, 7, 9, 8, 3, 2, 3     ← i=3: ‏3 שוקע מול 7\n1, 9, 7, 2, 8, 3, 2, 3     ← i=2: ‏2 שוקע מול 9\n1, 9, 7, 3, 8, 3, 2, 2     ← ...וממשיך לשקוע מול 3\n9, 1, 7, 3, 8, 3, 2, 2     ← i=1: ‏1 שוקע מול 9\n9, 8, 7, 3, 1, 3, 2, 2     ← ...וממשיך לשקוע מול 8</pre>\n<p>(i=4: ‏9 כבר גדול מבנו 3 — אין שינוי, ולכן אין שורה.)</p>\n<div class=\"warn\" style=\"margin-bottom:0\"><b>מה שנבדק כאן:</b> שהשקיעה\nהיא תהליך <b>רב-שלבי</b> — צומת ממשיך לשקוע עד שהוא במקום, וכל swap\nנרשם בנפרד. מי שרשם רק את המצב הסופי (<code>9,8,7,3,1,3,2,2</code>)\nאיבד את רוב הנקודות.</div>\n</div></details>"},{"id":"BK-6.5","cat":"ערימה","difficulty":3,"skills":["ערימה"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 6.5","prompt":"ענה על שלושת הסעיפים: (א) כמה <b>החלפות</b> מתבצעות בבניית ערימת מקסימום (<span dir=\"ltr\">MakeHeap</span>) מהמערך <span dir=\"ltr\">[20,19,50,17,12,15,22,5,7,30,40,17]</span>? (ב) כיצד ייראה המערך <span dir=\"ltr\">[25,14,16,13,10,8,12]</span> אחרי שתי פעולות <span dir=\"ltr\">Del_max</span>? (ג) נתונה ערימת מינימום — כיצד היא תיראה אחרי הוספת <span dir=\"ltr\">7</span> ולאחריו <span dir=\"ltr\">30</span>? נמק כל סעיף.","qtype":"trace","hint":"רשום את מצב המערך אחרי כל החלפה; בסעיף ב' ייתכנו כמה ערימות תקינות — צרף נימוק לאלגוריתם שבו השתמשת.","rule":"שלוש פעולות ערימה","html":"<div class=\"qh\"><b>6.5</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2020 שאלון X · ש'6 · 15 נק'</span><span class=\"src\">שלוש פעולות ערימה</span></div>\n<p>א) כמה החלפות בבניית ערימת מקסימום מ-\n<code>[20,19,50,17,12,15,22,5,7,30,40,17]</code>?\nב) ‏[25,14,16,13,10,8,12] אחרי 2×Del_max?\nג) ערימת מינימום + הוספת 7 ואז 30?</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p>א: <b>6 החלפות</b> · ב: ‏[14,13,12,8,10] לפי אלגוריתם הכיתה\n(הרשמי: ‏[14,13,12,10,8] — שניהם ערימות תקינות, כתוב נימוק!) ·\nג: ‏[2,7,5,22,17,10,19,25,31,18,30].</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d17','')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-6.6","cat":"ערימה","difficulty":3,"skills":["ערימה"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 6.6","prompt":"סיור <span dir=\"ltr\">PostOrder</span> על ערימת מקסימום נתן את הסדרה: <span dir=\"ltr\">2, 8, 1, 19, 3, 4, 30, 50</span>. שחזר את הערימה וכתוב את המערך המייצג אותה (מאינדקס 1). הסבר את שיטת השחזור.","qtype":"trace","hint":"צורת עץ בינארי <b>שלם</b> עם 8 צמתים היא יחידה — צייר את השלד עם אינדקסים, בצע עליו <span dir=\"ltr\">PostOrder</span>, ושבץ את הערכים לפי הסדר.","rule":"שחזור ערימה מ-PostOrder","html":"<div class=\"qh\"><b>6.6</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2021 · ש'3 · 16 נק'</span><span class=\"src\">שחזור ערימה מ-PostOrder</span></div>\n<p>‏PostOrder על ערימת מקסימום נתן: ‏2,8,1,19,3,4,30,50.\nכתוב את המערך (מאינדקס 1).</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p><b>[50,19,30,8,1,3,4,2]</b> — שיטת השלד: צורת עץ שלם עם 8 צמתים\nיחידה; ‏PostOrder על השלד = ‏8,4,5,2,6,7,3,1; משבצים ערכים.</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d05','')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-6.7","cat":"ערימה","difficulty":3,"skills":["ערימה"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 6.7","prompt":"סיור <span dir=\"ltr\">InOrder</span> על ערימת מקסימום נתן את הסדרה: <span dir=\"ltr\">3, 6, 1, 11, 7, 9, 15, 1, 8, 5</span>. שחזר את המערך המייצג את הערימה, ואז הסר ממנה את השורש (<span dir=\"ltr\">Del_max</span>) וכתוב את המערך המתקבל.","qtype":"trace","hint":"בנה תחילה את שלד העץ השלם עם האינדקסים, בצע עליו <span dir=\"ltr\">InOrder</span> ושבץ את הערכים; רק אז בצע את המחיקה.","rule":"ערימה מ-InOrder + הסרת שורש","html":"<div class=\"qh\"><b>6.7</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2023 · ש'3 · 16 נק'</span><span class=\"src\">ערימה מ-InOrder + הסרת שורש</span></div>\n<p>‏InOrder נתן: ‏3,6,1,11,7,9,15,1,8,5. הסירו את השורש —\nכתוב את המערך שהתקבל.</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p>המערך: ‏[15,11,8,6,9,1,5,3,1,7] ⟵ אחרי Del_max:\n<b>[11,9,8,6,7,1,5,3,1]</b>. אותה שיטת שלד, סיור אחר.</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d05','sol-2023-3')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-6.8","cat":"ערימה","difficulty":3,"skills":["ערימה"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 6.8","prompt":"נתון המערך <span dir=\"ltr\">[85, 22, 120, 0, 89, 12, 1, 35, 13, 70]</span>. (א) בנה ממנו ערימת מקסימום באלגוריתם <span dir=\"ltr\">MakeHeap</span>, ורשום בטבלה כל החלפה (<span dir=\"ltr\">swap</span>) שבוצעה וכן את המערך הסופי. (ב) הוסף לערימה שהתקבלה את הערך <span dir=\"ltr\">99</span> וכתוב את המערך אחרי ההוספה.","qtype":"trace","hint":"בסעיף א' עבור על הצמתים הפנימיים מהאחרון לראשון; בסעיף ב' האיבר החדש נכנס בסוף המערך וצף מעלה.","rule":"בניית ערימה + רישום החלפות + הוספה","html":"<div class=\"qh\"><b>6.8</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2024 · ש'6 · 12 נק'</span><span class=\"src\">בניית ערימה + רישום החלפות + הוספה</span></div>\n<p>‏[85,22,120,0,89,12,1,35,13,70]: א) רשום כל swap של MakeHeap\nבטבלה. ב) הוסף 99.</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p>ההחלפות: ‏(0,35) ‏(22,89) ‏(22,70) ‏(85,120) ⟵\n‏[120,89,85,35,70,12,1,0,13,22] · הוספת 99: צף מעל 70 ו-89 ⟵\n‏[120,99,85,35,89,12,1,0,13,22,70]. יש אנימציה מלאה!</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d17','')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-6.9","cat":"ערימה","difficulty":4,"skills":["ערימה"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 6.9","prompt":"נתונה ערימת מקסימום סופית <span dir=\"ltr\">[100, 98, 60, 58, 70, 20]</span>. ידוע שהאיבר הראשון שהוכנס היה <span dir=\"ltr\">70</span> והאיבר הרביעי שהוכנס היה <span dir=\"ltr\">98</span>. השלם סדר הכנסה אפשרי של כל האיברים, ולאחר מכן בצע <span dir=\"ltr\">Del_max</span> וכתוב את המערך המתקבל.","qtype":"trace","hint":"אחרי כל הכנסה בודדת המערך חייב להיות ערימה תקינה — בדוק כל מועמד לסדר על ידי סימולציה.","rule":"הנדסה לאחור — סדר הכנסה + Del_max","html":"<div class=\"qh\"><b>6.9</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🎓 מבחן 2025 · ש'6 · 12 נק'</span><span class=\"src\">הנדסה לאחור — סדר הכנסה + Del_max</span></div>\n<p>הערימה: ‏[100,98,60,58,70,20]; הראשון שהוכנס 70, הרביעי 98.\nהשלם סדר אפשרי ובצע Del_max.</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p>שתי התשובות הרשמיות: ‏70,58,60,98,100,20 או ‏70,58,20,98,100,60 ·\nאחרי Del_max: ‏[98,70,60,58,20]. העיקרון: אחרי כל הכנסה — ערימה\nתקינה.</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d05','sol-2025-6')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-7.1","cat":"ערבול","difficulty":3,"skills":["ערבול"],"origin":"bank","kind":"open","sourceLabel":"🤖 קלוד · 7.1","prompt":"נתונה טבלת ערבול המשתמשת ב<b>ערבול כפול</b> בגודל <span dir=\"ltr\">m = 8</span>. קבע לגבי כל אחת מפונקציות הצעד הבאות האם היא <b>חוקית</b>, ונמק: (א) <code>s(x) = x%4 + 1</code>; (ב) <code>s(x) = 2·(x%4) + 1</code>; (ג) <code>s(x) = x%8</code>. מהו הכלל הכללי לפונקציית צעד חוקית?","qtype":"analysis","hint":"פונקציית צעד חוקית חייבת להחזיר תמיד ערך שונה מאפס שהוא <b>זר</b> ל-<span dir=\"ltr\">m</span> — רשום את קבוצת הערכים האפשריים של כל פונקציה ובדוק.","rule":"פונקציות צעד חוקיות — בסגנון 2025 ש'7א","html":"<div class=\"qh\"><b>7.1</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🤖 קלוד</span><span class=\"src\">פונקציות צעד חוקיות — בסגנון 2025 ש'7א</span></div>\n<p>טבלת ערבול כפול בגודל <b>m=8</b>. אילו מפונקציות הצעד הבאות חוקיות?</p>\n<p>א. <code>s(x) = x%4 + 1</code> · ב. <code>s(x) = 2·(x%4) + 1</code> ·\nג. <code>s(x) = x%8</code></p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<div class=\"tw\"><table>\n<thead><tr><th></th><th>ערכים אפשריים</th><th>דין</th></tr></thead>\n<tbody>\n<tr><td><b>א</b></td><td>1, 2, 3, 4</td><td class=\"c\">❌ — 2 ו-4 מחלקים את 8;\nצעד 2 מ-תא זוגי לעולם לא יגיע לתאים האי-זוגיים</td></tr>\n<tr><td><b>ב</b></td><td>1, 3, 5, 7</td><td class=\"c\">✔ — כולם אי-זוגיים,\nזרים ל-8, מכסים את כל הטבלה</td></tr>\n<tr><td><b>ג</b></td><td>0…7</td><td class=\"c\">❌ — צעד 0 אפשרי =\nלולאה אינסופית על אותו תא</td></tr>\n</tbody></table></div>\n<p><b>הכלל:</b> פונקציית צעד חוקית חייבת להחזיר תמיד ערך ≠ 0 שהוא\n<b>זר ל-m</b> (gcd = 1). כש-m חזקה של 2 — כל האי-זוגיים עובדים,\nוזה בדיוק למה נהוג <code>2·(…)+1</code>.</p>\n</div></details>"},{"id":"BK-7.2","cat":"ערבול","difficulty":3,"skills":["ערבול"],"origin":"bank","kind":"open","sourceLabel":"🤖 קלוד · 7.2","prompt":"נתונה טבלת ערבול בגודל 7 עם פונקציית הערבול <code>h(x) = x%7</code> ופתרון התנגשויות ב<b>סריקה ליניארית</b>. מכניסים לטבלה, לפי הסדר, את הערכים <span dir=\"ltr\">15, 22, 8, 29</span>. (א) צייר את הטבלה הסופית וציין כמה התנגשויות היו לכל איבר. (ב) כעת מוחקים את <span dir=\"ltr\">22</span> ואז מחפשים את <span dir=\"ltr\">29</span> — מה עלול להשתבש, וכיצד פותרים זאת?","qtype":"trace","hint":"בסעיף ב' חשוב מה קורה לחיפוש כשהוא נתקל בתא <b>ריק</b> באמצע שרשרת הסריקה.","rule":"סריקה ליניארית + מלכודת המחיקה","html":"<div class=\"qh\"><b>7.2</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🤖 קלוד</span><span class=\"src\">סריקה ליניארית + מלכודת המחיקה</span></div>\n<p>טבלה בגודל 7, <code>h(x)=x%7</code>, סריקה ליניארית. מכניסים:\n<code>15, 22, 8, 29</code> (15 ראשון).</p>\n<p>א. צייר את הטבלה וספור התנגשויות לכל איבר.\nב. מוחקים את 22 ואז מחפשים את 29 — מה עלול להשתבש?</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<p><b>א.</b> כולם מתנגשים בכוונה: 15%7=1, 22%7=1, 8%7=1, 29%7=1.</p>\n<div class=\"tw\"><table>\n<thead><tr><th class=\"c\">0</th><th class=\"c\">1</th><th class=\"c\">2</th><th class=\"c\">3</th><th class=\"c\">4</th><th class=\"c\">5</th><th class=\"c\">6</th></tr></thead>\n<tbody><tr><td class=\"c\"></td><td class=\"c\">15</td><td class=\"c\">22</td><td class=\"c\">8</td><td class=\"c\">29</td><td class=\"c\"></td><td class=\"c\"></td></tr></tbody>\n</table></div>\n<p>התנגשויות: 15 — 0 · 22 — 1 · 8 — 2 · 29 — 3.</p>\n<p><b>ב.</b> אם מוחקים את 22 ומשאירים את תא 2 <b>ריק</b>, חיפוש 29 יתחיל\nבתא 1 (תפוס, לא הוא), יגיע לתא 2 הריק — <b>ויעצור</b>: \"לא נמצא\",\nלמרות ש-29 בטבלה! לכן במיעון פתוח מסמנים תא שנמחק כ-<b>DELETED</b>\n(מצבה) ולא כריק: חיפוש ממשיך דרכו, הכנסה יכולה לדרוס אותו.</p>\n</div></details>"},{"id":"BK-7.3","cat":"ערבול","difficulty":4,"skills":["ערבול"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 7.3","prompt":"נתונה טבלת ערבול כפול עם <code>h(x) = x%7</code> ופונקציית צעד <code>s(x) = (x%3)+2</code>. מצב הטבלה הסופי מוצג למטה. האם קיימת סדרת הכנסות (החל מטבלה ריקה) שמביאה בדיוק למצב הזה? אם כן — הצג סדרה כזו והוכח אותה על ידי סימולציה.","qtype":"trace","hint":"חשב תחילה את <b>תא הבית</b> של כל ערך; ערך שיושב בתא הבית שלו כנראה נכנס מוקדם, וערך שרחוק ממנו נכנס אחרי שהמסלול כבר נחסם.","rule":"מבחן 2018 שאלון B · שאלה 5 · 18 נק'","html":"<div class=\"qh\"><b>7.3</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🎓 מבחן עבר</span><span class=\"src\"><span class=\"tag exam\">מבחן 2018 שאלון B · שאלה 5 · 18 נק'</span> · הנדסה לאחור</span></div>\n<p>טבלת ערבול כפול: <code>h(x) = x%7</code>, צעד <code>s(x) = (x%3)+2</code>.\nמצב הטבלה הסופי:</p>\n<div class=\"tw\"><table>\n<thead><tr><th class=\"c\">0</th><th class=\"c\">1</th><th class=\"c\">2</th><th class=\"c\">3</th><th class=\"c\">4</th><th class=\"c\">5</th><th class=\"c\">6</th></tr></thead>\n<tbody><tr><td class=\"c\">17</td><td class=\"c\">9</td><td class=\"c\">5</td><td class=\"c\">10</td><td class=\"c\">24</td><td class=\"c\">3</td><td class=\"c\">4</td></tr></tbody>\n</table></div>\n<p>האם קיימת סדרת הכנסות (מטבלה ריקה) שמביאה למצב הזה? אם כן — תן אחת.</p>\n<details class=\"sol\"><summary>התשובה הרשמית + איך בונים אותה</summary><div class=\"body\">\n<p><b>קיימת.</b> הסדר הרשמי: <code>10, 3, 17, 5, 24, 4, 9</code></p>\n<p><b>איך ניגשים:</b> קודם מחשבים לכל ערך את תא הבית שלו:\n‏10→3, 3→3, 17→3, 24→3 (ארבעה מתחרים על תא 3!), 5→5, 9→2, 4→4.</p>\n<ul>\n<li>מי שיושב בתא הבית שלו יכול להיכנס מוקדם: 10 בתא 3 → הוא נכנס\nראשון מבין ה\"3\"-ים.</li>\n<li>‏3 (צעד 2): ‏3→5 — יושב ב-5? כן... אבל אז 5 לא יוכל להיכנס לתא 5.\nלכן הסדר בין 3 ל-5 קריטי: 3 נכנס לפני 5 ותופס את 5? הפתרון הרשמי\nמכניס 3 שני — הוא מוצא את תא 5 פנוי — ורק אז את 5, שמגלה את\nתא הבית תפוס וקופץ (צעד 4) אל 9%7=2 ✔.</li>\n<li>ממשיכים באותה שיטה ומוודאים שכל ערך נוחת בדיוק בתא שבו הוא מופיע\nבטבלה הסופית.</li>\n</ul>\n<div class=\"tip\" style=\"margin-bottom:0\"><b>העיקרון:</b> בשאלות \"האם קיים\nסדר\" — קודם תאי הבית. ערך שיושב בתא הבית שלו כנראה נכנס מוקדם; ערך\nרחוק מתא הבית נכנס אחרי שהמסלול שלו כבר היה חסום. אותו עיקרון בדיוק\nכמו 2024 ש'7 — רק בערבול כפול.</div>\n</div></details>"},{"id":"BK-7.4","cat":"ערבול","difficulty":3,"skills":["ערבול"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 7.4","prompt":"נתונה טבלת ערבול כפול בגודל <span dir=\"ltr\">m = 11</span>, עם <code>h(x) = x%11</code> ופונקציית צעד <code>s(x) = x%5 + 1</code>. הכנס לטבלה, לפי הסדר, את הערכים <span dir=\"ltr\">23, 78, 34, 67, 45, 12, 24</span>. צייר את הטבלה הסופית, וציין כמה הפעלות של פונקציית הצעד נדרשו עד שנמצא מקום עבור <span dir=\"ltr\">24</span>.","qtype":"trace","hint":"אל תשכח את הגלגול המודולרי — האינדקס הבא הוא <span dir=\"ltr\">(index + s(x)) % m</span>.","rule":"ערבול כפול + ספירת צעדים","html":"<div class=\"qh\"><b>7.4</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2020 שאלון X · ש'5 · 10 נק'</span><span class=\"src\">ערבול כפול + ספירת צעדים</span></div>\n<p>‏m=11, ‏h=x%11, ‏s=x%5+1. הכנס ‏23,78,34,67,45,12,24.\nצייר את הטבלה; כמה הפעלות של s עד שנמצא מקום ל-24?</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p>הטבלה: ‏0:24, 1:23, 2:45, 4:67, 5:78, 6:34, 7:12 ·\nל-24: <b>4 הפעלות</b> (‏7→1→6→0, עם גלגול ‎%11!).</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d06','')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-7.5","cat":"ערבול","difficulty":3,"skills":["ערבול"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 7.5","prompt":"נתונה טבלת ערבול במצב סופי (ראה למטה). (א) איזה רצף הכנסות יכול להתאים לטבלה הנתונה? נמק. (ב) כמה התנגשויות יהיו בהכנסת הערך <span dir=\"ltr\">137</span> ולאיזה תא הוא ייכנס? (ג) כיצד היו משתנות התשובות אילו הערך <span dir=\"ltr\">19</span> לא היה מוכנס מעולם?","qtype":"trace","hint":"חשב תא בית לכל ערך וסמלץ את ההכנסות; שים לב שמיקומו של ערך חדש תלוי ב<b>היסטוריית</b> ההכנסות הקודמות.","rule":"סדר הכנסה + התנגשויות + מחיקה","html":"<div class=\"qh\"><b>7.5</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2024 · ש'7 · 12 נק'</span><span class=\"src\">סדר הכנסה + התנגשויות + מחיקה</span></div>\n<p>א) איזה רצף הכנסות מתאים לטבלה הנתונה? ב) כמה התנגשויות ל-137\nולאן ייכנס? ג) ואם 19 לא הוכנס מעולם?</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p>א: בודקים תא-בית לכל מועמד ומסמלצים (הפירוק המלא בדק) ·\nב: <b>7 התנגשויות, תא 1</b> · ג: ‏59 היה באינדקס 8 ⟵ ‏137 נכנס\nל-<b>9</b> עם <b>2</b> התנגשויות — המיקום תלוי היסטוריה!</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d06','sol-2024-7')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-7.6","cat":"ערבול","difficulty":3,"skills":["ערבול"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 7.6","prompt":"בטבלת ערבול כפול: (א) קבע אילו מפונקציות הצעד <span dir=\"ltr\">s(x)</span> הנתונות הן חוקיות ונמק לפי הכלל הכללי; (ב) ספור את מספר ההתנגשויות בהכנסות הנתונות; (ג) הסבר מה קורה בחיפוש ערך אחרי שבוצעה מחיקה בטבלה, וכיצד יש לממש מחיקה כדי שהחיפוש יישאר תקין.","qtype":"analysis","hint":"הכלל: <span dir=\"ltr\">s(x) ≠ 0</span> וגם זר ל-<span dir=\"ltr\">m</span>; כאשר <span dir=\"ltr\">m</span> הוא חזקה של 2 — רק ערכים אי-זוגיים מתאימים.","rule":"אילו פונקציות צעד חוקיות?","html":"<div class=\"qh\"><b>7.6</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2025 · ש'7 · 12 נק'</span><span class=\"src\">אילו פונקציות צעד חוקיות?</span></div>\n<p>ערבול כפול — אילו s(x) חוקיות? (+ ספירת התנגשויות וחיפוש אחרי\nמחיקה.)</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p>הכלל: ‏s(x)≠0 <b>וזר ל-m</b> (gcd=1). ‏m חזקת 2 ⟵ רק אי-זוגיים\n⟵ ‏2·(x%k)+1 תמיד חוקית. מחיקה = DELETED, חיפוש ממשיך דרכה.</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d06','sol-2025-7')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-8.1","cat":"מיונים","difficulty":2,"skills":["מיונים"],"origin":"bank","kind":"open","sourceLabel":"🤖 קלוד · 8.1","prompt":"נתון המערך <span dir=\"ltr\">[1, 2, 3, 5, 4]</span>. (א) איזה מבין אלגוריתמי המיון הבאים יבצע עליו את <b>מספר ההשוואות הקטן ביותר</b>: מיון בועות (עם דגל), מיון הכנסה, מיון בחירה או מיון מהיר? נמק תוך השוואה מספרית. (ב) מהו הקלט ה<b>גרוע ביותר</b> עבור מיון הכנסה, ומהי הסיבוכיות עליו?","qtype":"analysis","hint":"בדוק כמה השוואות דורש כל אלגוריתם על מערך <b>כמעט ממוין</b>, וזכור שמיון בחירה אינו מושפע כלל מסדר הקלט.","rule":"בסגנון 2025 ש'8 בדיוק","html":"<div class=\"qh\"><b>8.1</b><span class=\"diff diff-e\">קל</span><span class=\"diff srcb\">🤖 קלוד</span><span class=\"src\">בסגנון 2025 ש'8 בדיוק</span></div>\n<p>נתון המערך <code>[1, 2, 3, 5, 4]</code>.</p>\n<p>א. איזה מיון יבצע עליו את <b>מספר ההשוואות הקטן ביותר</b>:\nבועות (עם דגל), הכנסה, בחירה, מהיר?\nב. מהו הקלט <b>הגרוע ביותר</b> למיון הכנסה?</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<p><b>א. מיון הכנסה.</b> המערך כמעט ממוין: כל איבר מושווה פעם אחת לשכנו\n(4 השוואות) ורק ה-4 דורש השוואה נוספת אחת — סה\"כ 5. בועות עם דגל צריך\nמעבר שלם + מעבר אימות (~7). בחירה תמיד ~n²/2 (10). מהיר עם ציר אחרון\nנמצא כאן במקרה הגרוע שלו.</p>\n<p><b>ב. מערך ממוין הפוך</b> — כל איבר חדש צריך \"לנדוד\" עד תחילת\nהמערך: 1+2+…+(n−1) = O(n²) השוואות והזזות.</p>\n</div></details>"},{"id":"BK-8.2","cat":"מיונים","difficulty":2,"skills":["מיונים"],"origin":"bank","kind":"open","sourceLabel":"🤖 קלוד · 8.2","prompt":"נתונה <b>רשימה מקושרת</b> (ולא מערך) בת <span dir=\"ltr\">n</span> איברים. איזה מבין אלגוריתמי המיון שנלמדו מתאים לה ביותר? נמק לפחות שתי סיבות, והסבר מדוע מיון מהיר ומיון ערימה דווקא <b>אינם</b> מתאימים למבנה זה.","qtype":"analysis","hint":"שאל את עצמך אילו אלגוריתמים דורשים <b>גישה אקראית לאינדקסים</b> — פעולה שברשימה מקושרת עולה <span dir=\"ltr\">O(n)</span>.","rule":"שאלת התאמה","html":"<div class=\"qh\"><b>8.2</b><span class=\"diff diff-e\">קל</span><span class=\"diff srcb\">🤖 קלוד</span><span class=\"src\">שאלת התאמה</span></div>\n<p>נתונה <b>רשימה מקושרת</b> (לא מערך) עם n איברים. איזה מיון מהנלמדים\nהכי מתאים לה, ולמה דווקא הוא?</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<p><b>מיון מיזוג.</b> שלוש סיבות:</p>\n<ul>\n<li>הוא לא צריך <b>גישה אקראית לאינדקסים</b> — רק מעבר סדרתי, שזה\nבדיוק מה שרשימה יודעת.</li>\n<li>המיזוג ברשימה נעשה ב<b>הזזת מצביעים</b> — אפילו בלי מערך העזר\nשנדרש במערכים.</li>\n<li>מובטח O(n·log n) בכל מקרה.</li>\n</ul>\n<p>מיון מהיר וערימה בנויים על קפיצות לאינדקסים (ציר, בנים ב-2i) —\nברשימה כל \"קפיצה\" כזאת היא O(n) והסיבוכיות מתפוצצת.</p>\n</div></details>"},{"id":"BK-8.3","cat":"מיונים","difficulty":3,"skills":["מיונים"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 8.3","prompt":"נתונים אלגוריתמי המיון: <span dir=\"ltr\">1</span> מהיר, <span dir=\"ltr\">2</span> הכנסה, <span dir=\"ltr\">3</span> מיזוג, <span dir=\"ltr\">4</span> בחירה, <span dir=\"ltr\">5</span> ערימה, <span dir=\"ltr\">6</span> בסיס. ציין אילו מהם (ייתכן יותר מאחד) מקיימים כל אחת מהתכונות הבאות, ונמק: (א) רצים מהר יותר מ-<span dir=\"ltr\">QuickSort</span> במקרה הגרוע; (ב) עובדים ב-<span dir=\"ltr\">O(n)</span> כשהנתונים כבר ממוינים; (ג) עובדים ב-<span dir=\"ltr\">O(n²)</span> במקרה הגרוע; (ד) תמיד <span dir=\"ltr\">O(n·log n)</span> ללא תלות בקלט; (ה) אינם מבוססים על השוואות; (ו) דורשים מערך עזר.","qtype":"analysis","hint":"בנה טבלה של כל מיון מול המקרה הטוב, הממוצע והגרוע, וסמן בנפרד את דרישת הזיכרון הנוסף ואת השאלה אם המיון מבוסס-השוואות.","rule":"מבחן 2022 · שאלה 5 · 18 נק'","html":"<div class=\"qh\"><b>8.3</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן עבר</span><span class=\"src\"><span class=\"tag exam\">מבחן 2022 · שאלה 5 · 18 נק'</span> · סיווג מלא</span></div>\n<p>על המיונים: 1 מהיר · 2 הכנסה · 3 מיזוג · 4 בחירה · 5 ערימה · 6 בסיס.\nאילו מיונים (יכול להיות יותר מאחד):</p>\n<p>א. רצים מהר יותר מ-QuickSort במקרה הגרוע?\n<br>ב. עובדים ב-O(n) כשהנתונים כבר ממוינים?\n<br>ג. עובדים ב-O(n²) במקרה הגרוע?\n<br>ד. תמיד O(n·log n), לא משנה מה הקלט?\n<br>ה. אינם מבוססים על השוואות?\n<br>ו. דורשים מערך עזר?</p>\n<details class=\"sol\"><summary>התשובות הרשמיות</summary><div class=\"body\">\n<div class=\"tw\"><table>\n<thead><tr><th>סעיף</th><th>תשובה רשמית</th><th>הערה</th></tr></thead>\n<tbody>\n<tr><td>א</td><td><b>מיזוג, ערימה, בסיס</b></td>\n<td>מהיר = O(n²) בגרוע; אלה O(n·log n) או O(n·k)</td></tr>\n<tr><td>ב</td><td><b>הכנסה</b></td>\n<td>על קלט ממוין: n−1 השוואות ואפס הזזות</td></tr>\n<tr><td>ג</td><td><b>מהיר, הכנסה, בחירה</b></td><td></td></tr>\n<tr><td>ד</td><td><b>מיזוג, ערימה</b></td><td></td></tr>\n<tr><td>ה</td><td><b>בסיס</b></td>\n<td>ממיין לפי ספרות, בלי להשוות זוגות</td></tr>\n<tr><td>ו</td><td><b>מיזוג, בסיס</b></td><td></td></tr>\n</tbody></table></div>\n<p>זו אותה שאלה כמו 2021 ש'6 (משבצת 3ב בדק המיונים) בגרסה מורחבת —\n<b>הופיעה פעמיים בשנתיים</b>. הטבלה של דק המיונים סוגרת אותה לגמרי.</p>\n</div></details>"},{"id":"BK-ב.1","cat":"עיצוב מבנה נתונים","difficulty":3,"skills":["עיצוב מבנה נתונים"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · ב.1","prompt":"נתונים מערך <b>לא ממוין</b> <span dir=\"ltr\">Arr</span> בגודל <span dir=\"ltr\">size</span> ומספר <span dir=\"ltr\">num</span>. כתוב אלגוריתם <code>IsSumExist(Arr, size, num)</code> הבודק אם קיימים במערך <b>זוג</b> איברים שסכומם <span dir=\"ltr\">num</span>, בסיבוכיות זמן <b>קטנה מ-<span dir=\"ltr\">O(n²)</span></b>. הסבר את הסיבוכיות של כל שלב ואת הסיבוכיות הכוללת.","qtype":"code","signature":"BOOL IsSumExist(int Arr[], int size, int num)","hint":"מיין תחילה, ואז השתמש בשני מצביעים הנעים מקצוות המערך פנימה לפי השוואת הסכום ל-<span dir=\"ltr\">num</span>.","rule":"מבחן 2018 שאלון A · שאלה 2 · 16 נק'","html":"<div class=\"qh\"><b>ב.1</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן עבר</span><span class=\"src\"><span class=\"tag exam\">מבחן 2018 שאלון A · שאלה 2 · 16 נק'</span> · אלגוריתם יעיל</span></div>\n<p>מערך לא ממוין ומספר num. כתוב אלגוריתם <code>IsSumExist(Arr, size, num)</code>\nשבודק אם קיימים <b>זוג</b> איברים שסכומם num, בסיבוכיות\n<b>קטנה מ-O(n²)</b>. הסבר את הסיבוכיות.</p>\n<details class=\"sol\"><summary>הפתרון הרשמי</summary><div class=\"body\">\n<pre>1. מיין את המערך במיון מיזוג                O(n·log n)\n2. left = 0, right = size−1\n3. כל עוד left &lt; right:\n     אם Arr[left]+Arr[right] &lt; num → ‏left++\n     אם Arr[left]+Arr[right] &gt; num → ‏right−−\n     אם שווה — החזר True\n4. החזר False                               O(n)\nסה\"כ: O(n·log n)</pre>\n<p><b>תבנית שני המצביעים מהקצוות:</b> אחרי מיון, סכום קטן מדי → מקדמים\nאת השמאלי; גדול מדי → מקטינים את הימני. כל צעד מצמצם את החלון —\nלכן O(n) לשלב החיפוש.</p>\n</div></details>"},{"id":"BK-ב.2","cat":"עיצוב מבנה נתונים","difficulty":3,"skills":["עיצוב מבנה נתונים"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · ב.2","prompt":"בחברה קיימים 9 תפקידים (קודים <span dir=\"ltr\">1–9</span>). כשמפטרים עובד מתפקיד מסוים, מפטרים תמיד את העובד ה<b>אחרון שהגיע</b> באותו תפקיד. (א) הצג מבנה נתונים שבו הוספת עובד ופיטורי עובד מתבצעים ב-<span dir=\"ltr\">O(1)</span>, ונמק את הבחירה. (ב) כתוב אלגוריתם המפטר <span dir=\"ltr\">n</span> עובדים מתפקיד נתון, ומדפיס הודעה מתאימה אם אין מספיק עובדים בתפקיד זה.","qtype":"design","hint":"\"האחרון שנכנס — הראשון שיוצא\" מצביע על מבנה אחד מסוים; קבוצת קטגוריות קטנה וידועה מראש מאפשרת גישה ישירה במערך.","rule":"מבחן 2018 שאלון B · שאלה 3 · 18 נק'","html":"<div class=\"qh\"><b>ב.2</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן עבר</span><span class=\"src\"><span class=\"tag exam\">מבחן 2018 שאלון B · שאלה 3 · 18 נק'</span> · מערך של מחסניות</span></div>\n<p>בחברה 9 תפקידים (קוד 1–9). כשמפטרים עובד בתפקיד מסוים — מפטרים את\n<b>האחרון שהגיע</b> באותו תפקיד. הצג מבנה נתונים שבו הוספה ופיטורים\nב-O(1), וכתוב אלגוריתם שמפטר n עובדים מתפקיד נתון (עם הודעה אם אין\nמספיק).</p>\n<details class=\"sol\"><summary>הפתרון הרשמי</summary><div class=\"body\">\n<p><b>המבנה:</b> מערך באורך 9; כל תא — <b>מחסנית</b> של עובדים\n(ת\"ז + שם). \"אחרון נכנס — ראשון מפוטר\" = LIFO טהור, והמערך נותן גישה\nO(1) לפי קוד תפקיד.</p>\n<pre>DismissEmployees(code, count):\n  1. ST = המחסנית בתא code−1\n  2. num = 0\n  3. כל עוד ST לא ריקה וגם num &lt; count:\n       worker = Pop(ST); הדפס ת\"ז; ‏num++\n  4. אם num &lt; count:\n       הדפס \"Only &lt;num&gt; workers were dismissed\"</pre>\n<p><b>הלקח:</b> כשהדרישה היא \"האחרון ש...\" — מחסנית. כשיש קטגוריות\nבטווח קטן וידוע — מערך של המבנים. השילוב נותן O(1) לשתי הפעולות.</p>\n</div></details>"},{"id":"BK-ב.3","cat":"עיצוב מבנה נתונים","difficulty":4,"skills":["עיצוב מבנה נתונים"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · ב.3","prompt":"במרפאה מתקבלים חולים לפי סדר הגעתם, אך חולה <span dir=\"ltr\">VIP</span> (המזוהה לפי <span dir=\"ltr\">ID</span>) חייב להישלף מיד מהתור. תכנן מבנה נתונים התומך בפעולות הבאות: אתחול ב-<span dir=\"ltr\">O(1)</span>, הוספת חולה ב-<span dir=\"ltr\">O(1)</span>, שליפת \"הבא בתור\" ב-<span dir=\"ltr\">O(1)</span>, ושליפת חולה <span dir=\"ltr\">VIP</span> לפי <span dir=\"ltr\">ID</span> ב-<span dir=\"ltr\">O(1)</span> ממוצע. הגדר את המבנה, תאר כל אחת מהפעולות ונמק את הסיבוכיות.","qtype":"design","hint":"התבנית הקבועה: מבנה שומר-סדר לתור, ולצדו טבלת ערבול שממפה מפתח אל <b>מצביע לתוך</b> המבנה — שים לב איזה סוג רשימה נדרש כדי שמחיקת צומת נתון תהיה <span dir=\"ltr\">O(1)</span>.","rule":"מבחן 2019 שאלון X · שאלה 5 · 30 נק'","html":"<div class=\"qh\"><b>ב.3</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🎓 מבחן עבר</span><span class=\"src\"><span class=\"tag exam\">מבחן 2019 שאלון X · שאלה 5 · 30 נק'</span> · תור + ערבול</span></div>\n<p>במרפאה מתקבלים חולים לפי סדר הגעה, אבל חולה VIP (לפי ID) חייב להישלף\nמיד. נדרש: אתחול O(1) · הוספה O(1) · הבא בתור O(1) · שליפת VIP לפי ID\nב-O(1) ממוצע. הגדר מבנה ותאר כל פעולה.</p>\n<details class=\"sol\"><summary>הפתרון הרשמי</summary><div class=\"body\">\n<p><b>המבנה:</b> רשימה מקושרת <b>דו-כיוונית</b> שמתנהגת כתור\n(head להוצאה, tail להכנסה) + <b>טבלת ערבול</b> שממפה ID → מצביע ל-Node\nברשימה.</p>\n<ul>\n<li><b>הוספה:</b> לסוף הרשימה O(1); אם VIP — הכנס גם לטבלה O(1).</li>\n<li><b>הבא בתור:</b> הוצא מה-head ‏O(1); אם היה בטבלה — מחק גם משם.</li>\n<li><b>שליפת VIP:</b> הטבלה נותנת את ה-Node ישירות; ברשימה\n<b>דו-כיוונית</b> מחיקת צומת נתון היא O(1) (יש prev!). זו כל הסיבה\nשהרשימה חייבת להיות דו-כיוונית.</li>\n</ul>\n<div class=\"tip\" style=\"margin-bottom:0\"><b>התבנית הגדולה של שאלות\nהעיצוב:</b> \"גישה לפי מפתח ב-O(1)\" = טבלת ערבול שמצביעה <b>אל תוך</b>\nמבנה סדר (רשימה/תור). שמור אותה בראש — היא פותרת גם את ב.4.</div>\n</div></details>"},{"id":"BK-ב.4","cat":"עיצוב מבנה נתונים","difficulty":4,"skills":["עיצוב מבנה נתונים"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · ב.4","prompt":"במגרש רכבים, לכל רכב יש מספר לוחית זיהוי, סוג (מתוך קבוצת סוגים ידועה מראש) ומחיר. תכנן מבנה נתונים התומך בפעולות: הוספת רכב ב-<span dir=\"ltr\">O(log n)</span>; קבלת רשימת כל הרכבים שמחירם <span dir=\"ltr\">P</span> ב-<span dir=\"ltr\">O(log n)</span>; קבלת רשימת כל הרכבים מסוג <span dir=\"ltr\">T</span> ב-<span dir=\"ltr\">O(1)</span>; ומציאת המחיר הזול ביותר ב-<span dir=\"ltr\">O(log n)</span>. הגדר את המבנה, תאר כל פעולה ונמק את הסיבוכיות.","qtype":"design","hint":"החלט בנפרד לכל דרישה: טווח ערכים לא ידוע שדורש סדר ומינימום מוביל לעץ חיפוש מאוזן, וקטגוריות ידועות מראש מובילות לטבלת ערבול.","rule":"מבחן 2019 שאלון Y · שאלה 5 · 30 נק'","html":"<div class=\"qh\"><b>ב.4</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🎓 מבחן עבר</span><span class=\"src\"><span class=\"tag exam\">מבחן 2019 שאלון Y · שאלה 5 · 30 נק'</span> · עץ + ערבול + רשימות</span></div>\n<p>מגרש רכבים: לכל רכב לוחית, סוג (מתוך קבוצה ידועה) ומחיר. נדרש:\nהוספה O(log n) · רשימת רכבים במחיר P ב-O(log n) · רשימת רכבים מסוג T\nב-O(1) · המחיר הזול ביותר ב-O(log n). הגדר מבנה ותאר את הפעולות.</p>\n<details class=\"sol\"><summary>הפתרון הרשמי (תמצית)</summary><div class=\"body\">\n<ul>\n<li><b>עץ חיפוש (עדיף AVL) לפי מחיר</b> — כל צומת מחזיק <b>רשימה\nמקושרת</b> של כל הרכבים באותו מחיר. חיפוש/הוספה O(log n).</li>\n<li><b>טבלת ערבול (Chain Hashing) לפי סוג</b> — סוג → רשימת כל הרכבים\nמהסוג. שליפה O(1) ממוצע.</li>\n<li><b>הזול ביותר:</b> הליכה שמאלה-שמאלה עד העלה השמאלי ביותר בעץ —\nO(log n) בעץ מאוזן.</li>\n</ul>\n<p><b>למה זה שווה תרגול גם ב-2026:</b> השאלה מלמדת מתי עץ (טווח לא ידוע,\nצריך מינימום וסדר) ומתי ערבול (קטגוריות ידועות, גישה ישירה) — בדיוק\nההנמקות שנבחנות בשאלות הקצרות של הפורמט החדש.</p>\n</div></details>"},{"id":"BK-8.4","cat":"עיצוב מבנה נתונים","difficulty":3,"skills":["עיצוב מבנה נתונים"],"origin":"bank","kind":"open","sourceLabel":"📝 מטלה · 8.4","prompt":"הרץ את אלגוריתם <span dir=\"ltr\">Radix Sort</span> על המערך <span dir=\"ltr\">[454, 123, 113, 34, 21, 1261, 879, 8, 234, 103, 108]</span>, והצג את מצב המערך אחרי <b>כל מעבר</b> (אחדות, עשרות, מאות, אלפים).","qtype":"trace","hint":"במספר קצר יש להתייחס לעמדה החסרה כאל הספרה 0, והמיון בכל מעבר חייב להיות <b>יציב</b> — כלומר לשמר את הסדר מהמעבר הקודם בתוך כל דלי.","rule":"שאלה 2 — מעקב Radix מלא","html":"<div class=\"qh\"><b>8.4</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">📝 מטלה HW2</span><span class=\"src\">שאלה 2 — מעקב Radix מלא</span></div>\n<p>הרץ Radix Sort על:\n<code>[454,123,113,34,21,1261,879,8,234,103,108]</code> והצג כל שלב.</p>\n<details class=\"sol\"><summary>פתרון — כל המעברים</summary><div class=\"body\">\n<p><b>מעבר 1 (אחדות):</b>\n<code>[21,1261,123,113,103,454,34,234,8,108,879]</code></p>\n<p><b>מעבר 2 (עשרות):</b>\n<code>[103,8,108,113,21,123,34,234,454,1261,879]</code></p>\n<p><b>מעבר 3 (מאות):</b>\n<code>[8,21,34,103,108,113,123,234,1261,454,879]</code></p>\n<p><b>מעבר 4 (אלפים):</b>\n<code>[8,21,34,103,108,113,123,234,454,879,1261]</code> ✔</p>\n<p><b>שני כללים שמפילים:</b> מספר קצר = ספרה 0 בעמדה החסרה (‏8 מנצח\nאת כולם במעבר המאות), והמיון בכל מעבר חייב להיות <b>יציב</b> — הסדר\nמהמעבר הקודם נשמר בתוך כל דלי.</p>\n<p><b>🎬 ותראה את זה קורה — מעבר-מעבר:</b></p>\n<div id=\"d14_p1\"></div>\n</div></details>"},{"id":"BK-8.5","cat":"עיצוב מבנה נתונים","difficulty":3,"skills":["עיצוב מבנה נתונים"],"origin":"bank","kind":"open","sourceLabel":"📝 מטלה · 8.5","prompt":"נתונים מערך <b>ממוין</b> בסדר עולה וערך <span dir=\"ltr\">x</span>. כתוב פונקציה <b>רקורסיבית</b> <code>int countSmallers(int a[], int lo, int hi, int x)</code> המחזירה כמה איברים במערך קטנים מ-<span dir=\"ltr\">x</span>, בסיבוכיות <span dir=\"ltr\">O(log n)</span>. <b>בלי לולאות.</b> ציין גם את שורת הקריאה הראשונה.","qtype":"code","signature":"int countSmallers(int a[], int lo, int hi, int x)","hint":"אל תחפש את <span dir=\"ltr\">x</span> עצמו אלא את ה<b>גבול</b> שבו המערך עובר מ\"קטן מ-<span dir=\"ltr\">x</span>\" ל\"גדול או שווה\" — ושים לב מה מייצג <span dir=\"ltr\">lo</span> כשהחלון מתרוקן.","rule":"שאלה 3 — countSmallers ב-O(log n)","html":"<div class=\"qh\"><b>8.5</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">📝 מטלה HW2</span><span class=\"src\">שאלה 3 — countSmallers ב-O(log n)</span></div>\n<p>מערך ממוין וערך x — החזר כמה איברים קטנים מ-x, יעיל ככל האפשר,\nבלי לולאות.</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<pre class=\"c\">int countSmallers(int a[], int lo, int hi, int x)\n{\n    if (lo &gt; hi) return lo;    /* lo = מספר הקטנים מ-x */\n    int mid = (lo + hi) / 2;\n    if (a[mid] &lt; x)\n        return countSmallers(a, mid + 1, hi, x);\n    return countSmallers(a, lo, mid - 1, x);\n}\n/* קריאה: countSmallers(a, 0, n-1, x)  —  O(log n) */</pre>\n<p><b>חיפוש בינארי מוכלל:</b> לא מחפשים את x — מחפשים את <b>הגבול</b>\nשבו המערך עובר מ\"קטן מ-x\" ל\"גדול-שווה\". כשהחלון מתרוקן, ‏lo עומד\nבדיוק על מספר הקטנים. עובד גם עם כפילויות של x.</p>\n</div></details>"},{"id":"BK-8.6","cat":"עיצוב מבנה נתונים","difficulty":4,"skills":["עיצוב מבנה נתונים"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 8.6","prompt":"נתון מערך שערכיו <b>יורדים ואז עולים</b> (\"פרבולי\"). כתוב אלגוריתם המוצא את הערך המינימלי במערך בסיבוכיות <span dir=\"ltr\">O(log n)</span>. שים לב: המינימום עשוי להימצא גם באחד מקצות המערך. נמק את הסיבוכיות.","qtype":"code","signature":"int findMin(int A[], int n)","hint":"בצע חיפוש בינארי על ה<b>צורה</b>: אם האמצע קטן משני שכניו — מצאת; אחרת המשך אל הצד היורד. בדוק תחילה את שני הקצוות.","rule":"מינימום במערך \"פרבולי\" ב-O(log n)","html":"<div class=\"qh\"><b>8.6</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🎓 מבחן 2018 שאלון B · ש'2 · 16 נק'</span><span class=\"src\">מינימום במערך \"פרבולי\" ב-O(log n)</span></div>\n<p>מערך יורד-ואז-עולה; מצא את המינימום ב-O(log n). המינימום יכול\nלהיות בקצוות!</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p>חיפוש בינארי על הצורה: אמצע קטן משני שכניו ⟵ מצאנו; צד יורד ⟵\nהמשך בו. קודם בדוק קצוות (<code>A[0] &lt; A[1]</code> או <code>A[n-1] &lt; A[n-2]</code>).</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d17','')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-8.7","cat":"עיצוב מבנה נתונים","difficulty":2,"skills":["עיצוב מבנה נתונים"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 8.7","prompt":"לאחר ביצוע פעולת <span dir=\"ltr\">partition</span> אחת של מיון מהיר התקבל המערך <span dir=\"ltr\">2, 5, 1, 7, 9, 12, 11, 10</span>. האם הציר (<span dir=\"ltr\">pivot</span>) יכול היה להיות <span dir=\"ltr\">7</span>? האם הוא יכול היה להיות <span dir=\"ltr\">9</span>? נמק בעזרת התכונה שמאפיינת את מיקום הציר אחרי <span dir=\"ltr\">partition</span>.","qtype":"analysis","hint":"אחרי <span dir=\"ltr\">partition</span> הציר נמצא במקומו הסופי — כל האיברים משמאלו קטנים ממנו וכל שמימינו גדולים ממנו.","rule":"זיהוי פיבוט אחרי partition","html":"<div class=\"qh\"><b>8.7</b><span class=\"diff diff-e\">קל</span><span class=\"diff srcb\">🎓 מבחן 2020 שאלון X · ש'1ג · 5 נק'</span><span class=\"src\">זיהוי פיבוט אחרי partition</span></div>\n<p>אחרי partition אחד: ‏2,5,1,7,9,12,11,10. האם הפיבוט יכול היה\nלהיות 7? ‏9?</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p><b>שניהם אפשריים.</b> הכלל: הפיבוט במקומו הסופי — כל שמשמאלו\nקטנים, כל שמימינו גדולים. ‏7 ✔ וגם ‏9 ✔.</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d08','')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-8.8","cat":"עיצוב מבנה נתונים","difficulty":3,"skills":["עיצוב מבנה נתונים"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 8.8","prompt":"עבור אלגוריתמי המיון שנלמדו בקורס, ענה ונמק: (א) אילו מהם הם תמיד <span dir=\"ltr\">O(n·log n)</span>? (ב) אילו מהם הם תמיד <span dir=\"ltr\">O(n²)</span>? (ג) אילו מהם הם <span dir=\"ltr\">O(n²)</span> במקרה הגרוע בלבד? (ד) אילו מהם דורשים זיכרון נוסף?","qtype":"analysis","hint":"שים לב להבדל בין \"תמיד <span dir=\"ltr\">O(n²)</span>\" (לא רגיש לקלט) לבין \"<span dir=\"ltr\">O(n²)</span> בגרוע בלבד\" (תלוי בקלט).","rule":"סיווג 7 המיונים","html":"<div class=\"qh\"><b>8.8</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2021 · ש'6 · 18 נק'</span><span class=\"src\">סיווג 7 המיונים</span></div>\n<p>מי תמיד O(n·log n)? מי תמיד O(n²)? מי O(n²) בגרוע? מי דורש\nזיכרון נוסף?</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p>תמיד n·log n: <b>מיזוג, ערימה</b> · תמיד n²: <b>בחירה</b> ·\n‏n² בגרוע: <b>מהיר, בחירה, הכנסה</b> · זיכרון נוסף: <b>מיזוג, מנייה,\nבסיס</b>.</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d08','')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-8.9","cat":"עיצוב מבנה נתונים","difficulty":3,"skills":["עיצוב מבנה נתונים"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 8.9","prompt":"מיין את רשימת דגמי המטוסים <span dir=\"ltr\">C5, F16, F22, A10, F35, B2, C130, B1, B52, F15</span> לפי <b>אות הדגם</b> (<span dir=\"ltr\">A, B, C, F</span>) בעזרת <b>מיון מנייה</b> (<span dir=\"ltr\">Counting Sort</span>). הצג את כל שלבי האלגוריתם — מערך המניות, המערך המצטבר, והמערך הסופי — והסבר כיצד נשמרת יציבות המיון.","qtype":"trace","hint":"המעבר האחרון על הקלט חייב להתבצע <b>מהסוף להתחלה</b> — זה מה שמבטיח שהסדר הפנימי בכל קבוצה יישמר.","rule":"מיון מנייה על דגמי מטוסים","html":"<div class=\"qh\"><b>8.9</b><span class=\"diff diff-m\">בינוני</span><span class=\"diff srcb\">🎓 מבחן 2024 · ש'8 · 12 נק'</span><span class=\"src\">מיון מנייה על דגמי מטוסים</span></div>\n<p>מיין ‏C5,F16,F22,A10,F35,B2,C130,B1,B52,F15 לפי אות הדגם\n(A,B,C,F) — הצג כל שלב.</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p>‏3 שלבים: מנה (A:1,B:3,C:2,F:4) ⟵ מצטבר ⟵ מעבר <b>מהסוף</b>\nלתאים. יציבות: הסדר הפנימי בכל אות נשמר —\n‏A10,B2,B1,B52,C5,C130,F16,F22,F35,F15.</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d08','sol-2024-8')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-8.10","cat":"עיצוב מבנה נתונים","difficulty":2,"skills":["עיצוב מבנה נתונים"],"origin":"bank","kind":"open","sourceLabel":"🎓 מבחן אמיתי · 8.10","prompt":"(א) איזה מבין אלגוריתמי המיון שנלמדו יבצע את מספר ההשוואות הקטן ביותר על מערך (כמעט) ממוין? נמק, והתייחס במיוחד למיון מהיר עם בחירת ציר אחרון. (ב) מהו הקלט ה<b>גרוע ביותר</b> עבור מיון הכנסה, וכמה השוואות והזזות הוא דורש עליו?","qtype":"analysis","hint":"מיון אחד מזהה מיד שהאיבר כבר במקומו ומסתפק בהשוואה בודדת לכל איבר; ולמיון מהיר עם ציר קבוע דווקא קלט ממוין הוא המקרה הגרוע.","rule":"הכי מעט השוואות + הקלט הגרוע","html":"<div class=\"qh\"><b>8.10</b><span class=\"diff diff-e\">קל</span><span class=\"diff srcb\">🎓 מבחן 2025 · ש'8 · 10 נק'</span><span class=\"src\">הכי מעט השוואות + הקלט הגרוע</span></div>\n<p>איזה מיון עושה הכי מעט השוואות על מערך (כמעט) ממוין? ומה הקלט\nהגרוע ביותר למיון הכנסה?</p>\n<details class=\"sol\"><summary>התשובה + תמצית</summary><div class=\"body\">\n<p><b>הכנסה</b> (n−1 השוואות על ממוין; מהיר עם ציר אחרון דווקא\nבגרוע שלו!) · הקלט הגרוע להכנסה: <b>ממוין הפוך</b>.</p>\n<p><a class=\"golink\" onclick=\"jumpSol('d08','sol-2025-8')\">⬅ לפתרון המלא והמוסבר</a></p>\n</div></details>"},{"id":"BK-א.1·סיבוכיותמשולבת","cat":"אתגרי מבחן+","difficulty":4,"skills":["אתגרי מבחן+"],"origin":"bank","kind":"open","sourceLabel":"🧠 קודקס · א.1 · סיבוכיות משולבת","prompt":"מצא חסם <b>הדוק</b> לסיבוכיות זמן הריצה של הפונקציה הרקורסיבית שלמטה כפונקציה של <span dir=\"ltr\">n</span>. נמק: חשב תחילה את עלות זוג הלולאות המקוננות, ואז רשום ופתור את נוסחת הנסיגה.","qtype":"analysis","hint":"הלולאה הפנימית מתקדמת בצעדים של <span dir=\"ltr\">i</span> — כמה איטרציות היא מבצעת, ומה מתקבל כשסוכמים זאת על כל ערכי <span dir=\"ltr\">i</span> שהם חזקות של 2?","rule":"רקורסיה + לולאה תלוית-i","html":"<div class=\"qh\"><b>א.1 · סיבוכיות משולבת</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🧠 קודקס</span><span class=\"src\">רקורסיה + לולאה תלוית-i</span></div>\n<pre class=\"c\">long f(int n)\n{\n    long counter = 0;\n    if (n &lt;= 1) return 1;\n\n    for (int i = 1; i &lt; n; i *= 2)\n        for (int j = 0; j &lt; n; j += i)\n            counter++;\n\n    return f(n/2) + f(n/2) + counter;\n}</pre>\n<p>מצא חסם הדוק.</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<p>הלולאה הפנימית רצה n/i פעמים, ולכן הזוג עולה\n<code>n + n/2 + n/4 + … = Θ(n)</code> (הסכום ההנדסי מפרק היסודות!).\nמכאן <code>T(n) = 2T(n/2) + Θ(n)</code> → נוסחת האב →\n<b>Θ(n·log n)</b>.</p>\n</div></details>"},{"id":"BK-א.2·תור:הדפסהבמקומות","cat":"אתגרי מבחן+","difficulty":4,"skills":["אתגרי מבחן+"],"origin":"bank","kind":"open","sourceLabel":"🧠 קודקס · א.2 · תור: הדפסה במקומות זוגיים + שחזור מלא","prompt":"כתוב פונקציה <code>void printEvenPositions(QUEUE* q)</code> המדפיסה את האיברים הנמצאים במקומות ה<b>זוגיים</b> בתור (החל מראש התור), כאשר בסיום הריצה התור נשאר <b>ללא שינוי</b> — באותו סדר בדיוק שבו היה. <b>בלי לולאות ובלי מבנה עזר</b>; מותר להשתמש בפונקציית עזר רקורסיבית ובפעולות התור בלבד.","qtype":"code","signature":"void printEvenPositions(QUEUE* q)","hint":"בתור, השלד <span dir=\"ltr\">deque → רקורסיה → enque</span> <b>הופך</b> את הסדר (בניגוד למחסנית) — לכן דרוש מעבר רקורסיבי שני שמשחזר.","rule":"כולל התיקון לבאג מ-HW3","html":"<div class=\"qh\"><b>א.2 · תור: הדפסה במקומות זוגיים + שחזור מלא</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🧠 קודקס</span><span class=\"src\">כולל התיקון לבאג מ-HW3</span></div>\n<p>הדפס את האיברים במקומות הזוגיים מראש התור, בלי לולאות ובלי מבנה עזר —\nובסוף התור חייב להישאר <b>ללא שינוי</b>.</p>\n<details class=\"sol\"><summary>פתרון + הבאג שכדאי להכיר</summary><div class=\"body\">\n<pre class=\"c\">void rotate(QUEUE* q, int pos, BOOL print)\n{\n    if (Q_isEmpty(q)) return;\n    DATA x = Q_deque(q);\n    if (print &amp;&amp; pos % 2 == 0) printf(\"%d \", x);\n    rotate(q, pos + 1, print);\n    Q_enque(q, x);\n}\n\nvoid printEvenPositions(QUEUE* q)\n{\n    rotate(q, 1, True);    /* מדפיס — אבל הופך את התור */\n    rotate(q, 1, False);   /* מעבר שני בלי הדפסה — הופך חזרה */\n}</pre>\n<p><b>הנקודה:</b> deque→רקורסיה→enque על תור <b>הופך</b> את הסדר (בניגוד\nלמחסנית!). לכן חובה מעבר רקורסיבי <b>שני</b> שמשחזר. זה בדיוק הבאג\nשקודקס מצא ב-<code>even</code> של HW3 שלך: ההדפסה נכונה, אבל התור נשאר\nהפוך והבדיקה ב-main נכשלת.</p>\n</div></details>"},{"id":"BK-א.3·רשימהדו-כיווניתמ","cat":"אתגרי מבחן+","difficulty":4,"skills":["אתגרי מבחן+"],"origin":"bank","kind":"open","sourceLabel":"🧠 קודקס · א.3 · רשימה דו-כיוונית מעגלית — היסט בלי הקצאה","prompt":"נתונה רשימה מקושרת דו-כיוונית <b>מעגלית</b> בת <span dir=\"ltr\">n</span> צמתים. כתוב אלגוריתם המעביר את <span dir=\"ltr\">k</span> הצמתים האחרונים אל ראש הרשימה, <b>בלי הקצאת זיכרון</b>. פרט אילו מקרי קצה חובה לבדוק לפני שנוגעים במצביעים, והתייחס בנפרד למימוש עם מצביע ראש בלבד ולמימוש עם צומת דמה (כותר). מהי סיבוכיות הזמן והמקום?","qtype":"code","signature":"void rotateCircular(DLIST* pLst, int k)","hint":"ברשימה מעגלית ה\"אחרון\" וה\"ראשון\" כבר מחוברים — לעיתים קרובות די בהזזת נקודת ההתחלה; ואל תשכח לצמצם <span dir=\"ltr\">k %= n</span> ולטפל ב-<span dir=\"ltr\">k == 0</span>.","rule":"הרחבה של 2025 ש'3","html":"<div class=\"qh\"><b>א.3 · רשימה דו-כיוונית מעגלית — היסט בלי הקצאה</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🧠 קודקס</span><span class=\"src\">הרחבה של 2025 ש'3</span></div>\n<p>ברשימה דו-כיוונית <b>מעגלית</b> עם n צמתים, העבר את k האחרונים לראש\nבלי הקצאה. מה חייבים לבדוק לפני שנוגעים במצביע?</p>\n<details class=\"sol\"><summary>פתרון ברמת אינווריאנט</summary><div class=\"body\">\n<ol>\n<li><b>מקרי קצה:</b> רשימה ריקה, ‏k==0, או ‏k%n==0 — אין מה לעשות.\nמצמצמים <code>k %= n</code>.</li>\n<li>במעגל \"אחרון\" ו\"ראשון\" כבר מחוברים! לכן אם המימוש הוא רק מצביע\nראש — מספיק <b>להזיז את מצביע הראש</b> ‏n−k צעדים.</li>\n<li>אם יש צומת דמה (כותר) — מנתקים ומחברים את <b>ארבעת</b> הקישורים\nסביבו (‏next/prev משני הצדדים), אחרי ששמרנו מצביעים לכל ארבעת\nהגבולות.</li>\n</ol>\n<p>זמן O(n), מקום O(1). <b>הלקח:</b> במעגלית, רוב \"ההעברות\" הן בכלל\nהזזת נקודת מבט — לא ניתוח וחיבור.</p>\n</div></details>"},{"id":"BK-א.4·עץמאוזן-גודלבמעב","cat":"אתגרי מבחן+","difficulty":4,"skills":["אתגרי מבחן+"],"origin":"bank","kind":"open","sourceLabel":"🧠 קודקס · א.4 · עץ מאוזן-גודל במעבר אחד","prompt":"עץ בינארי נקרא <b>\"מאוזן לפי גודל\"</b> אם בכל צומת בו, הפרש <b>מספרי הצמתים</b> של תת-העץ השמאלי ותת-העץ הימני הוא לכל היותר 1. כתוב פונקציה <code>BOOL isSizeBalanced(NODE2* root)</code> הבודקת זאת בסיבוכיות <span dir=\"ltr\">Θ(n)</span> — כלומר <b>בלי לחשב את גודלו של אף תת-עץ יותר מפעם אחת</b>. נמק מדוע הפתרון שלך אכן <span dir=\"ltr\">Θ(n)</span>.","qtype":"code","signature":"BOOL isSizeBalanced(NODE2* root)","hint":"כתוב פונקציית עזר שמחזירה <b>שני דברים בערך אחד</b>: את גודל תת-העץ, או ערך דגל מיוחד (למשל <span dir=\"ltr\">−1</span>) שמסמן כישלון ומחלחל כלפי מעלה.","rule":"בלי לחשב גודל פעמיים","html":"<div class=\"qh\"><b>א.4 · עץ מאוזן-גודל במעבר אחד</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🧠 קודקס</span><span class=\"src\">בלי לחשב גודל פעמיים</span></div>\n<p>עץ \"מאוזן לפי גודל\" אם בכל צומת הפרש <b>מספרי הצמתים</b> של תתי-העצים\nהוא לכל היותר 1. בדוק זאת ב-Θ(n).</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<pre class=\"c\">int sizeOrFail(NODE2* p)      /* מחזיר גודל, או -1 אם נכשל */\n{\n    if (!p) return 0;\n    int l = sizeOrFail(p-&gt;left);\n    if (l == -1) return -1;\n    int r = sizeOrFail(p-&gt;right);\n    if (r == -1 || abs(l - r) &gt; 1) return -1;\n    return l + r + 1;\n}\n\nBOOL isSizeBalanced(NODE2* root)\n{\n    return sizeOrFail(root) != -1;\n}</pre>\n<p><b>הטריק:</b> פונקציה אחת שמחזירה <b>שני דברים</b> בערך אחד — גודל\nתקין, או ‎−1 כ\"דגל כישלון\" שמחלחל למעלה. כל צומת מחושב פעם אחת בלבד →\nΘ(n). השווה ל-CheckSymetric מ-2018 (מאגר 4.5) שמחשב גובה שוב ושוב —\nזו הגרסה החכמה.</p>\n</div></details>"},{"id":"BK-א.5·ערימה:הנדסהלאחור","cat":"אתגרי מבחן+","difficulty":4,"skills":["אתגרי מבחן+"],"origin":"bank","kind":"open","sourceLabel":"🧠 קודקס · א.5 · ערימה: הנדסה לאחור + Del_max","prompt":"ערימת מקסימום סופית נראית כך: <span dir=\"ltr\">[50, 40, 35, 10, 30, 20, 25]</span>. ידוע שהאיבר הראשון שהוכנס היה <span dir=\"ltr\">20</span> והרביעי היה <span dir=\"ltr\">30</span>. (א) תן סדר הכנסה אפשרי לכל האיברים והצג את מצב הערימה אחרי כל הכנסה. (ב) בצע <span dir=\"ltr\">Del_max</span> על הערימה הסופית וכתוב את המערך המתקבל, כולל ההחלפות בדרך.","qtype":"trace","hint":"אחרי כל הכנסה בודדת המערך חייב להיות ערימה תקינה; בשקיעה שאחרי <span dir=\"ltr\">Del_max</span> מחליפים תמיד עם הגדול מבין שני הבנים.","rule":"וריאציה נוספת לתרגול","html":"<div class=\"qh\"><b>א.5 · ערימה: הנדסה לאחור + Del_max</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🧠 קודקס</span><span class=\"src\">וריאציה נוספת לתרגול</span></div>\n<p>הערימה הסופית: <code>[50,40,35,10,30,20,25]</code>. הראשון שהוכנס:\n20, הרביעי: 30. תן סדר הכנסה אפשרי ובצע Del_max.</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<p><b>סדר אפשרי:</b> <code>20, 10, 40, 30, 50, 35, 25</code> —\nבדוק בעצמך שכל שלב הוא ערימה תקינה (סימולציה מלאה אחרי כל Insert).</p>\n<p><b>Del_max:</b> ‏25 (האחרון) עולה לשורש ושוקע: מול 40 ו-35 מחליף עם\n40, מול 10 ו-30 מחליף עם 30:</p>\n<pre>40  30  35  10  25  20</pre>\n</div></details>"},{"id":"BK-א.6·ערבול:צעדקבועומח","cat":"אתגרי מבחן+","difficulty":4,"skills":["אתגרי מבחן+"],"origin":"bank","kind":"open","sourceLabel":"🧠 קודקס · א.6 · ערבול: צעד קבוע ומחיקה","prompt":"בטבלת ערבול בגודל 12 מציעים להשתמש בערבול כפול עם צעד <b>קבוע</b> בגודל 4. (א) האם זו פונקציית צעד חוקית? נמק. אילו ערכי צעד קבוע כן יהיו חוקיים עבור <span dir=\"ltr\">m = 12</span>? (ב) בחיפוש ערך בטבלה, האם עוצרים כאשר מגיעים לתא המסומן כ\"נמחק\" (<span dir=\"ltr\">DELETED</span>)? נמק.","qtype":"analysis","hint":"חשב את <span dir=\"ltr\">gcd</span> של הצעד עם גודל הטבלה — הוא קובע בכמה תאים המסלול מבקר לפני שהוא חוזר על עצמו.","rule":"שאלת הבנה מהירה","html":"<div class=\"qh\"><b>א.6 · ערבול: צעד קבוע ומחיקה</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🧠 קודקס</span><span class=\"src\">שאלת הבנה מהירה</span></div>\n<p>בטבלה בגודל 12 מציעים צעד <b>קבוע</b> 4 לערבול כפול. חוקי? ובחיפוש —\nעוצרים בתא \"נמחק\"?</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<p><b>לא חוקי:</b> ‏gcd(4,12)=4 — המסלול מבקר רק ב-3 תאים וחוזר על\nעצמו; שאר הטבלה לא נגישה. הצעד חייב להיות זר ל-12 (למשל 1, 5, 7, 11).</p>\n<p><b>ובמחיקה:</b> בתא \"נמחק\" (DELETED) <b>לא עוצרים</b> — ממשיכים.\nעוצרים רק בתא שמעולם לא היה תפוס.</p>\n</div></details>"},{"id":"BK-א.7·מיעושההכימעטהשוו","cat":"אתגרי מבחן+","difficulty":4,"skills":["אתגרי מבחן+"],"origin":"bank","kind":"open","sourceLabel":"🧠 קודקס · א.7 · מי עושה הכי מעט השוואות על מערך ממוין?","prompt":"נתון מערך שכבר <b>ממוין</b> בסדר עולה. מבין מיון הכנסה (<span dir=\"ltr\">Insertion</span>), מיון בחירה (<span dir=\"ltr\">Selection</span>) ומיון בועות (<span dir=\"ltr\">Bubble</span>) <b>עם דגל עצירה</b> — מי מבצע את מספר ההשוואות הקטן ביותר? חשב במדויק את מספר ההשוואות של כל אחד, ונסח במפורש את ההנחות שעליהן מבוססת תשובתך.","qtype":"analysis","hint":"שים לב שאין כאן בהכרח מנצח יחיד — התשובה תלויה במימוש, ולכן ניסוח מפורש של ההנחה הוא חלק מהתשובה הנדרשת.","rule":"שאלת ניסוח-הנחות","html":"<div class=\"qh\"><b>א.7 · מי עושה הכי מעט השוואות על מערך ממוין?</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🧠 קודקס</span><span class=\"src\">שאלת ניסוח-הנחות</span></div>\n<p>על מערך ממוין: ‏Insertion, ‏Selection ו-Bubble <b>עם דגל עצירה</b>.\nמי עושה הכי מעט השוואות?</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<p>‏Insertion: ‏<b>n−1</b> השוואות. ‏Bubble עם דגל: מעבר אחד =\n<b>n−1</b> השוואות ועצירה. ‏Selection: ‏<b>n(n−1)/2</b> תמיד.</p>\n<p><b>המסקנה החשובה:</b> אין מנצח יחיד בין Insertion ל-Bubble-עם-דגל —\nהתשובה תלויה במימוש. במבחן: <b>כתוב את ההנחה שלך</b> (\"בהנחה ש-Bubble\nעם דגל עצירה…\") — זה ההבדל בין תשובה מלאה לוויכוח עם בודק.</p>\n</div></details>"},{"id":"BK-א.8·ביקורתקודC—4באגי","cat":"אתגרי מבחן+","difficulty":4,"skills":["אתגרי מבחן+"],"origin":"bank","kind":"open","sourceLabel":"🧠 קודקס · א.8 · ביקורת קוד C — 4 באגים בפונקציה אחת","prompt":"בקוד ה-C שלמטה, שנועד לשכפל צומת בודד של רשימה מקושרת, קיימות <b>ארבע</b> בעיות. אתר את כולן, הסבר מה התוצאה של כל אחת, וכתוב את הגרסה המתוקנת של הפונקציה.","qtype":"code","signature":"NODE* cloneOne(const NODE* p)","hint":"בדוק את <b>סדר</b> הפעולות מול בדיקת ה-<span dir=\"ltr\">NULL</span>, את מה בדיוק נמדד ב-<span dir=\"ltr\">sizeof</span>, את הטיפול בכישלון ההקצאה, ואילו שדות של הצומת החדש נשארו לא מאותחלים.","rule":"לפני שמאבדים נקודות בשאלות 3–4","html":"<div class=\"qh\"><b>א.8 · ביקורת קוד C — 4 באגים בפונקציה אחת</b><span class=\"diff diff-h\">קשה</span><span class=\"diff srcb\">🧠 קודקס</span><span class=\"src\">לפני שמאבדים נקודות בשאלות 3–4</span></div>\n<pre class=\"c\">NODE* cloneOne(const NODE* p)\n{\n    NODE* q = malloc(sizeof(NODE*));\n    if (!p) return NULL;\n    q-&gt;key = p-&gt;key;\n    return q;\n}</pre>\n<p>מצא ארבע בעיות והצע תיקון.</p>\n<details class=\"sol\"><summary>פתרון</summary><div class=\"body\">\n<ol>\n<li>ההקצאה קורית <b>לפני</b> בדיקת p — אם p==NULL יש דליפת זיכרון.</li>\n<li><code>sizeof(NODE*)</code> מקצה גודל של <b>מצביע</b> (8 בתים) במקום\nשל הצומת — דריסת זיכרון.</li>\n<li>אין בדיקה אם malloc נכשל.</li>\n<li><code>q-&gt;next</code> נשאר לא מאותחל — זבל.</li>\n</ol>\n<pre class=\"c\">NODE* cloneOne(const NODE* p)\n{\n    if (!p) return NULL;\n    NODE* q = malloc(sizeof(*q));   /* sizeof על מה שמוצבע! */\n    if (!q) return NULL;\n    q-&gt;key  = p-&gt;key;\n    q-&gt;next = NULL;\n    return q;\n}</pre>\n</div></details>"}];
